INSERT INTO "chat_logs" VALUES(5,9,'Mack Chen (Super Admin)','mack.chen@viccollege.com','What is the grant amount for Better Jobs Ontario second career?','Victoria International College offers 100% free application assistance for Ontario Government grants, including Better Jobs Ontario (formerly Second Career). Eligible applicants can receive up to $28,000+ in non-repayable funding covering full tuition, textbooks, transportation, child care, and basic living allowances. Eligible individuals include laid-off workers, gig/contract workers, self-employed, low-income earners, permanent residents, and Canadian citizens. Contact our admissions advisors at 416-665-6668 or book a consultation on our website for an eligibility assessment.','vic-knowledge-base-direct',0,'127.0.0.1','2026-09-02T04:35:31.221764');
INSERT INTO "chat_logs" VALUES(6,9,'Mack Chen (Super Admin)','mack.chen@viccollege.com','Where is your Markham campus located?','Victoria International College has two convenient Greater Toronto Area campuses:
INSERT INTO "chat_logs" VALUES(7,9,'Mack Chen (Super Admin)','mack.chen@viccollege.com','Tell me about your Personal Support Worker PSW program','The NACC Personal Support Worker (PSW) DE 2022 Certificate Program consists of intensive classroom theory and hands-on clinical practicum placement in top Ontario nursing homes and healthcare facilities. Graduates receive their NACC PSW Certificate, Standard First Aid & CPR Level C certification. High employment demand across hospitals, long-term care homes, and community healthcare with $20-$28/hr starting wage. Financial aid and Second Career grants are applicable.','vic-knowledge-base-direct',0,'127.0.0.1','2026-09-02T04:35:35.348888');
INSERT INTO "chat_logs" VALUES(8,NULL,'Guest','guest@viccollege.com','How do I get the $28,000 government grant for PSW?','Victoria International College offers 100% free application assistance for Ontario Government grants, including Better Jobs Ontario (formerly Second Career). Eligible applicants can receive up to $28,000+ in non-repayable funding covering full tuition, textbooks, transportation, child care, and basic living allowances. Eligible individuals include laid-off workers, gig/contract workers, self-employed, low-income earners, permanent residents, and Canadian citizens. Contact our admissions advisors at 416-665-6668 or book a consultation on our website for an eligibility assessment.','vic-knowledge-base-direct',0,'127.0.0.1','2026-09-02T04:36:12.497262');
