INSERT INTO "chat_logs" VALUES(61,9,'Mack Chen (Super Admin)','mack.chen@viccollege.com','What is the grant amount for Better Jobs Ontario second career?','Victoria International College offers 100% free application assistance for Ontario Government grants, including Better Jobs Ontario (formerly Second Career). Eligible applicants can receive up to $28,000+ in non-repayable funding covering full tuition, textbooks, transportation, child care, and basic living allowances. Eligible individuals include laid-off workers, gig/contract workers, self-employed, low-income earners, permanent residents, and Canadian citizens. Contact our admissions advisors at 416-665-6668 or book a consultation on our website for an eligibility assessment.','vic-knowledge-base-direct',0,'127.0.0.1','2026-09-07T02:01:17.815126');
