INSERT INTO "job_fairs" VALUES(1,'Upcoming Event','近期重磅活动','IN-PERSON PSW JOB FAIR','维多利亚线下 PSW 护工专场招聘会','Connect with employers, find jobs','知名养老机构 HR 亲临现场直接面试，岗位充足，当天即可锁定实习与工作机会！','Friday, 12 May | 10:00AM – 12:00PM','每周五 上午 10:00 – 中午 12:00','Suite 300, 7050 Woodbine Ave. Markham L3R 4G8','7050 Woodbine Ave., Unit 300, Markham, ON L3R 4G8','Secure Your Spot','立即免费抢占席位','#consultation','images/job-fair.png',1,'2026-09-05T17:32:06.272223','2026-09-26T03:38:52.238811');
INSERT INTO "knowledge_base" VALUES(1,'financial_aid','Better Jobs Ontario (Second Career) - Up to $28,000+ Government Grant','financial aid, second career, better jobs ontario, grant, funding, government grant, free tuition, allowance, living expense, eligibility, 28000','Victoria International College offers 100% free application assistance for Ontario Government grants, including Better Jobs Ontario (formerly Second Career). Eligible applicants can receive up to $28,000+ in non-repayable funding covering full tuition, textbooks, transportation, child care, and basic living allowances. Eligible individuals include laid-off workers, gig/contract workers, self-employed, low-income earners, permanent residents, and Canadian citizens. Contact our admissions advisors at 416-665-6668 or book a consultation on our website for an eligibility assessment.',2,'2026-09-02T04:23:23.817230','2026-09-02T04:23:23.817230',1);
INSERT INTO "knowledge_base" VALUES(2,'programs','NACC Personal Support Worker (PSW) DE 2022 Certificate Program','psw, personal support worker, healthcare, nursing home, clinic, practicum placement, cpr, first aid, nacc, caregiving, hospital, medical, duration, how long, 23 weeks, 23周','The NACC Personal Support Worker (PSW) DE 2022 Certificate Program is an intensive 23-week accredited program consisting of classroom/online theory, hands-on clinical lab simulations at our campuses, and 300+ hours of guaranteed clinical practicum placement in leading Ontario nursing homes and healthcare facilities. Graduates receive their official NACC PSW Certificate, Standard First Aid & CPR Level C certification. High employment demand across hospitals, long-term care homes, and community healthcare with competitive wages starting wage. Better Jobs Ontario government funding grants (up to $28,000+) are applicable.',2,'2026-09-02T04:23:23.817230','2026-09-06T23:48:51.692659',1);
INSERT INTO "knowledge_base" VALUES(3,'programs','Full Stack Web Technician Diploma Program','full stack, web development, software, programming, java, springboot, react, javascript, nodejs, aws, mysql, cloud, coding, developer, diploma','The Full Stack Web Technician Diploma covers core & advanced Java, SpringBoot, Spring Cloud, React, Node.js, Webpack, MySQL, Netty, AWS Cloud deployment, and enterprise software engineering design patterns. Includes hands-on real-world capstone projects and resume/interview preparation for high-paying tech careers (competitive tech salaries) in Canada.',2,'2026-09-02T04:23:23.817230','2026-09-02T04:23:23.817230',1);
INSERT INTO "knowledge_base" VALUES(4,'programs','Accounting, Tax and Payroll Administration Diploma','accounting, tax, payroll, bookkeeper, sage 50, quickbooks, canadian taxation, cra, financial, accounts payable, accounts receivable, t1, t2','This 30-week intensive instructor-led diploma covers Canadian corporate & personal taxation (T1/T2), computerized bookkeeping, Sage 50, QuickBooks, and certified payroll administration under CPA supervision. Graduates qualify for careers as Bookkeepers, Accounting Assistants, Tax Preparers, and Payroll Officers.',1,'2026-09-02T04:23:23.817230','2026-09-02T04:23:23.817230',1);
INSERT INTO "knowledge_base" VALUES(5,'programs','Early Childcare Assistant (ECA) Diploma Program','eca, early childcare assistant, daycare, kindergarten, child development, nutrition, field placement, childcare, educator, preschool','The Early Childcare Assistant (ECA) Diploma prepares students for careers in licensed daycares, preschools, and early learning centers. Curriculum includes child development, health, safety, nutrition, creative expression, customer service, and an extensive supervised field practicum.',1,'2026-09-02T04:23:23.817230','2026-09-02T04:23:23.817230',1);
INSERT INTO "knowledge_base" VALUES(6,'programs','Acupuncture & Holistic Wellness Program (Non-Vocational)','acupuncture, tcm, wellness, health, complementary health, holistic, meridian, herbal, non-vocational, traditional','The Acupuncture program is a Non-Vocational Program designed for personal interest, wellness, and complementary health education. This program does not require approval under the Ontario Career Colleges Act, 2005. It provides foundational theory in TCM meridians, holistic wellness, and practical demonstrations.',1,'2026-09-02T04:23:23.817230','2026-09-02T04:23:23.817230',1);
INSERT INTO "knowledge_base" VALUES(7,'programs','Electrician (Construction & Maintenance 309A / 442A)','electrician, 309a, 442a, construction, maintenance, apprenticeship, red seal, electrical, wiring, code, cec','Taught by master electricians with 20+ years Canadian industry experience in major Ontario electrical contracting. Features 1-on-1 hands-on training at recognized apprenticeship training facilities, placement on real construction projects, and preparation for Ontario 309A Construction & Maintenance Electrician certification with top journeyperson wages earning potential.',1,'2026-09-02T04:23:23.817230','2026-09-02T04:23:23.817230',1);
INSERT INTO "knowledge_base" VALUES(8,'campuses','Victoria International College Campuses, Addresses & Contact Info','address, location, campus, phone, contact, email, markham, hours, opening hours, directions, where are you located','Victoria International College Markham Main Campus is located at 7050 Woodbine Ave., Unit 300, Markham, ON L3R 4G8
INSERT INTO "knowledge_base" VALUES(9,'general','President Maria Sun & 22+ Years of College History','maria sun, president, dean, founder, history, mission, leadership, about us, 2005, harvard, victoria group','Victoria International College was founded to empower new immigrants and career transitioners in Canada. Led by President Maria Sun (Dean of Victoria International College, Chief Secretary of Canadian Youth Union & Canadian Women''s Service Centre), who has dedicated over 22 years to higher education and career development in Canada, helping tens of thousands of immigrants secure professional jobs.',1,'2026-09-02T04:23:23.817230','2026-09-02T04:23:23.817230',1);
INSERT INTO "knowledge_base" VALUES(10,'admissions','How to Apply & Book a Free Career Consultation','apply, admissions, registration, book consultation, free class, appointment, advisor, schedule, interview','Prospective students can book a 100% free virtual or in-person career consultation directly on our website at http://localhost:5050/#consultation or by calling 416-665-6668. Our admissions advisors evaluate your career background, assess eligibility for government grants ($28,000+), provide course syllabi, and arrange free demo classes.',2,'2026-09-02T04:23:23.817230','2026-09-02T04:23:23.817230',1);
INSERT INTO "knowledge_base" VALUES(11,'financial_aid','Tuition Payment Plans, 0% Interest Installments & Scholarships','tuition, fee, cost, payment plan, installment, scholarship, interest free, financial assistance, self funded','In addition to government grants (Better Jobs Ontario), Victoria International College provides flexible, 0% interest monthly installment payment plans and institutional scholarships for students paying self-funded tuition.',1,'2026-09-02T04:23:23.817230','2026-09-02T04:23:23.817230',1);
INSERT INTO "knowledge_base" VALUES(12,'admissions','Co-op & Career Placement Guarantee (Updated)','co-op, career placement, job guarantee, hiring, internship, qa','Victoria International College partners with over 150+ Canadian employers to guarantee structured practicum and resume referrals for all diploma students.',3,'2026-09-02T04:27:02.712654','2026-09-02T04:27:04.777377',1);
