INSERT INTO "knowledge_base" VALUES(22,'admissions','Does Victoria International College offer Construction and Maintenance Electrician 309A license preparation?','does, victoria, college, offer, construction, maintenance, electrician, 309a','Taught by master electricians with 20+ years Canadian industry experience in major Ontario electrical contracting. Features 1-on-1 hands-on training at recognized apprenticeship training facilities, placement on real construction projects, and preparation for Ontario 309A Construction & Maintenance Electrician certification with top journeyperson wages earning potential.',2,'2026-09-02T04:41:56.736050','2026-09-02T04:41:56.736050',1);
