INSERT INTO "programs" VALUES(1,'psw','healthcare','images/psw.jpg','Certificate Program • Ontario Regulated','安省官方职业证书 • 紧缺高薪','NACC Personal Support Worker DE 2022','NACC 个人护理护工文凭 (PSW DE 2022)','Personal Support Worker Certificate Program contains in class lectures and practicum training. Upon graduating, students will not only have their PSW certificate but also a CPR & First Aid certificate.
INSERT INTO "programs" VALUES(2,'accounting','business','images/accounting.jpg','Career Diploma • CPA Mentorship','加国高稳定度白领职业文凭','Accounting, Tax and Payroll','会计、税务与薪资管理 (Accounting, Tax & Payroll)','The program consists of 30 weeks of intensive instructor led hands on training and practical exercises under the supervision of industry-experienced instructors.
INSERT INTO "programs" VALUES(3,'eca','education','images/eca.jpg','Career Diploma • Daycare Placement','安省热门幼教职业文凭 • 保障实习','Early Childcare Assistant','早期幼儿教育助理 (Early Childcare Assistant - ECA)','We provide our students with the opportunity for personal growth and success by providing an intimate and friendly learning environment that emphasizes academic & professional excellence. Subjects included in the program:','我们通过营造注重学术与专业卓越的温馨友善学习环境，为学生提供个人成长与成功的机会。涵盖科目包括：','["Interpersonal Communication", "Health, Safety and Nutrition", "Child Development", "Customer Service", "Operations", "Creative Expression", "Field Placement"]','["人际交往沟通技能", "健康、安全与营养管理", "儿童生长与心理发展", "客户与家长服务规范", "日托中心日常运营", "创意表达与艺术启蒙", "安省持牌幼儿园实地实习"]','22 Weeks (Classroom Theory + Daycare Placement)','22 周（理论课 + 正规持牌日托中心跟岗实习）','Early Childcare Assistant Diploma + Child CPR & First Aid','安省 ECA 幼教助理文凭 + 儿童急救与 CPR 证书','Equips students with the practical competencies, child psychology understanding, and health & safety expertise required to support Early Childhood Educators (ECEs) in licensed Ontario daycare facilities.','随着安省日托政策普及，持证幼教助理需求激增。课程系统培养学员在持牌日托中心配合主班幼教（ECE）开展日常照料、安全监管、早期启蒙游戏及家校沟通的专业能力。','["Introduction to Early Childhood Education & Ontario Daycare Regulations", "Child Growth and Development: Infancy to School-Age", "Health, Safety and Nutritional Guidelines in Childcare", "Creative Expressions: Art, Music, Storytelling & Sensory Activities", "Positive Behavior Guidance & Conflict Resolution in Classrooms", "Interpersonal Communications with Parents, Staff and Inspectors", "Observations, Pedagogical Documentation and Program Planning", "Guaranteed Field Placement in Licensed Ontario Childcare Centers (200+ Hours)"]','["加拿大幼儿教育发展概况与安省日托管理法规", "婴幼儿至学龄前儿童生理与心理发展阶段特征", "日托中心健康、安全防护、儿童营养与过敏管理", "幼儿创意启蒙活动：绘画、音乐律动、故事会与感统游戏设计", "儿童行为积极引导策略与情商培养技巧", "家园共育沟通技能与多文化背景团队协作", "儿童日常行为观察、成长档案记录与教案编制", "安省持牌正规幼儿园/日托中心 200+ 小时实地跟岗实习"]','Early Childcare Assistant, Daycare Room Assistant, Nursery Assistant, Before/After School Program Leader, Private Family Care Specialist.','持证幼教助理（ECA）、幼儿园班级助理、课后托管班（After-School）主管、早教中心活动辅导员。','With Ontario''s $10-a-day childcare expansion, certified early childcare staff are in historic high demand across the province.','政府日托补贴政策推动下全省幼教机构大量扩招，工作稳定，假期充裕，福利待遇良好。',3,1,'2026-09-05T02:43:10.259254','2026-09-26T03:39:00.622362','{"hero": {"badge": "Ontario Approved Career Diploma • 22-Week Intensive Daycare Placement", "title": "Launch Your Rewarding Career as a Certified Early Childcare Assistant (ECA)", "lead": "Help shape the next generation with Ontario-approved early childhood training. Master child development, health & safety, creative curriculum planning, and gain 500+ hours of guaranteed hands-on field placement in licensed daycares and preschools across the GTA."}, "stats": [{"value": "22 Weeks", "label": "Comprehensive Theory + 500+ Hours Daycare Placement"}, {"value": "High Demand", "label": "Rewarding Career Growth + Ontario Wage Enhancement (WEG)"}, {"value": "100% Daycare Placement", "label": "Guaranteed Practicum in Accredited Daycare Centers"}, {"value": "Up to $28,000+", "label": "Eligible for Full Better Jobs Ontario Government Funding"}], "why_choose": {"title": "Why Choose Early Childcare Assistant (ECA) as Your Canadian Career?", "subtitle": "Early childhood education in Ontario is undergoing historic expansion driven by the federal $10-a-day Canada-Wide Early Learning and Child Care (CWELCC) plan. Daycare centers, preschools, and kindergarten programs across the Greater Toronto Area face severe shortages of certified, compassionate educators and assistants.", "pillars": [{"title": "Historic Industry Demand", "desc": "With thousands of new subsidized childcare spaces opening across Ontario, certified Early Childcare Assistants enjoy extraordinary job security, permanent employment, and signing bonuses."}, {"title": "Rewarding & Meaningful Work", "desc": "Make a lasting, positive impact on young children''s cognitive, emotional, and social development during their most critical formative years."}, {"title": "Safe & Collaborative Work Environment", "desc": "Work in modern, licensed childcare facilities, early learning centers, and school boards alongside dedicated teams of Registered Early Childhood Educators (RECEs)."}, {"title": "Clear Career Progression", "desc": "Gain vital Canadian frontline experience and open doors to accelerated RECE diploma pathways, daycare supervisory roles, or private home childcare business ownership."}]}, "credentials": {"title": "Diplomas & Certifications Awarded", "subtitle": "Upon successful completion of the curriculum and field placement hours, graduates receive prestigious, employer-recognized credentials:", "items": [{"title": "Official Early Childcare Assistant (ECA) Diploma", "desc": "Ontario Ministry-approved vocational diploma recognized by licensed daycare centers, nursery schools, and private educational institutions across Ontario."}, {"title": "Standard First Aid & CPR Level C (Infant & Child)", "desc": "Mandatory provincial certification ensuring readiness to handle pediatric emergencies, choking, CPR, and first aid."}, {"title": "Food Handler & Pediatric Nutrition Certificate", "desc": "Industry-standard certification verifying mastery of safe food handling, allergy prevention, and balanced menu planning in childcare settings."}, {"title": "Guaranteed 500+ Hours Supervised Field Placement", "desc": "Comprehensive hands-on practicum verifying verified Canadian childcare experience across infant, toddler, and preschool age groups."}]}, "practicum": {"title": "Guaranteed 500+ Hours Field Placement in Licensed Ontario Daycares", "desc": "Victoria International College partners with accredited daycare centers, Montessori schools, and early learning centers across Toronto, Markham, Richmond Hill, Scarborough, and Mississauga to coordinate 100% of your hands-on field practicum.", "box_title": "Direct Daycare Hiring & Job Offer Success Rate", "box_desc": "Over 85% of Victoria International College ECA students receive permanent job offers directly from their placement host center before graduation!"}, "admissions": {"title": "Admission Requirements & Prerequisites", "items": ["Ontario Secondary School Diploma (OSSD / Grade 12) or equivalent evaluation from a recognized credential agency.", "Mature Student Admission: Age 18 or older and successfully passing the Wonderlic College Entrance Assessment (complimentary on-site testing).", "Clear Vulnerable Sector Criminal Reference Check (VSC) issued by local police services (required prior to field placement).", "Up-to-date Medical Immunization Record including Two-Step Tuberculosis (TB) skin test.", "Genuine passion for early childhood development, strong interpersonal communication, and commitment to nurturing care."]}, "curriculum": {"title": "Comprehensive 22-Week Curriculum Modules (10 Core Subjects)", "desc": "Our structured curriculum equips students with the exact competencies mandated by Ontario''s Child Care and Early Years Act (CCEYA) and early learning frameworks:"}, "curriculum_modules": [{"num": 1, "title": "Introduction to Early Childhood Education & Ontario Daycare Regulations", "desc": "Overview of Canadian early childhood education, Child Care and Early Years Act (CCEYA 2014) compliance, licensing requirements, and professional ethics."}, {"num": 2, "title": "Child Growth and Development: Infancy to Toddlerhood", "desc": "Physical, cognitive, emotional, and social development milestones for infants (0–18 months) and toddlers (18–30 months), brain development, and attachment theory."}, {"num": 3, "title": "Child Growth and Development: Preschool to School-Age", "desc": "Developmental stages for preschoolers (2.5–5 years) and school-age children (6–12 years), language acquisition, motor skills, and social interaction patterns."}, {"num": 4, "title": "Health, Safety, Nutrition & Emergency Procedures in Childcare", "desc": "Infection control protocols, sanitation standards, injury prevention, anaphylaxis and food allergy management, balanced meal planning, and pediatric emergency response."}, {"num": 5, "title": "Creative Expressions: Art, Music, Storytelling & Sensory Play", "desc": "Designing engaging activities that stimulate creativity, fine and gross motor skills, sensory exploration, musical rhythms, dramatic play, and early literacy."}, {"num": 6, "title": "Positive Guidance & Classroom Behavior Strategies", "desc": "Evidence-based child guidance techniques, encouraging self-regulation, conflict resolution among children, establishing calm classroom routines, and positive reinforcement."}, {"num": 7, "title": "Interpersonal Communications with Families, Staff & Regulators", "desc": "Building trusting partnerships with diverse Canadian families, daily parent communication, daily logs, multi-disciplinary teamwork with RECEs, and Ministry inspection preparedness."}, {"num": 8, "title": "Program Planning & Pedagogical Documentation (How Does Learning Happen?)", "desc": "Implementing Ontario''s ''How Does Learning Happen?'' early learning framework, designing play-based learning environments, observing children, and creating learning portfolios."}, {"num": 9, "title": "Supporting Children with Diverse Needs & Inclusive Childcare", "desc": "Inclusive childcare practices, understanding neurodiversity, sensory processing differences, autism spectrum support, and working collaboratively with resource consultants."}, {"num": 10, "title": "Supervised Field Practicum in Licensed Childcare Centers (500+ Hours)", "desc": "Hands-on clinical practicum in accredited Ontario daycare centers under the direct mentorship of experienced RECEs, rotating through infant, toddler, and preschool rooms."}], "grants": {"badge": "Ontario Government Training Grant", "title": "Qualify for Up to $28,000+ in Better Jobs Ontario Funding", "description": "The Early Childcare Assistant program qualifies for maximum Better Jobs Ontario (formerly Second Career) government funding. Eligible candidates (laid off workers, unemployed, gig workers, self-employed, or low-income) can receive up to $28,000+ in non-repayable grants covering tuition, books, child care, and living allowance.", "amount": "$28,000+", "button_text": "Check Grant Eligibility Now"}, "snapshot": {"delivery": "Hybrid (Live Online Theory + In-Person Daycare Practicum)", "practicum": "500+ Hours (100% Guaranteed Placement)", "locations": "Markham Main Campus / Live Online", "hotline": "416-665-6668"}, "faqs": [{"q": "Can I study the theory portion of the ECA program online from home?", "a": "Yes! All theory lectures and interactive classroom modules are delivered live online with expert early childhood instructors. You will attend flexible online sessions, followed by your guaranteed in-person daycare practicum in your local area."}, {"q": "How long is the Early Childcare Assistant program?", "a": "The program is 22 weeks in total, combining comprehensive theoretical foundations, creative workshop labs, and 500+ hours of hands-on field practicum in licensed Ontario daycare centers."}, {"q": "What is the difference between an ECA and an ECE in Ontario?", "a": "An ECA (Early Childcare Assistant) works directly alongside Registered Early Childhood Educators (RECEs) in daycare rooms, assisting with daily routines, learning activities, nutrition, and child supervision. ECA is a fast-track 22-week diploma that allows you to start working in the childcare field quickly."}, {"q": "Are there government grants available for this program?", "a": "Yes! This program is fully eligible for Better Jobs Ontario (formerly Second Career), offering up to $28,000+ in non-repayable government grants covering 100% of your tuition, learning materials, transportation, and living expenses for qualified applicants."}, {"q": "Do you guarantee daycare field placement?", "a": "Yes! Victoria International College coordinates 100% of your 500+ hours supervised field practicum with our extensive network of licensed daycares, Montessori schools, and early learning centers across the GTA."}, {"q": "What are the job prospects and career compensation after graduation?", "a": "Job prospects are exceptionally strong due to Ontario''s $10/day childcare expansion, offering competitive compensation, full-time career stability, and additional Ontario Wage Enhancement Grant (WEG) support for eligible staff."}]}','{"hero": {"badge": "安省注册幼教职业文凭 • 22 周持牌日托中心保障实习", "title": "开启充满爱心与高薪稳定的职业生涯 • 早期幼儿教育助理 (ECA) 职业文凭", "lead": "投身安省极度紧缺的早期幼儿教育行业。系统学习婴幼儿及学龄前儿童心理发展、健康营养、安全防护与启蒙教案设计，保障进入安省持牌正规幼儿园/日托中心进行 500+ 小时实地带薪/跟岗实习。"}, "stats": [{"value": "22 周", "label": "网课理论/校区实操 + 500+小时持牌幼儿园实地实习"}, {"value": "极具潜力", "label": "大多伦多托儿幼教稳定高需求 + 安省政府薪资补贴 (WEG)"}, {"value": "100% 保障实习", "label": "对口签约安省正规持牌日托中心与早教机构"}, {"value": "$28,000+ 补贴", "label": "符合 Better Jobs Ontario 政府全额无偿资助"}], "why_choose": {"title": "为什么选择成为早期幼儿教育助理 (ECA)？", "subtitle": "随着加拿大联邦及安省政府全面推行 $10/天普惠日托计划（CWELCC），全省各类托儿所、幼儿园和早教中心迎来历史性大扩建，持证幼教助理（ECA）与幼教老师长期极度紧缺，成为加国最抢手、最温暖且极具社会价值的黄金职业之一。", "pillars": [{"title": "历史性行业缺口与高就业率", "desc": "安省日托补贴政策全面落地，新增数万个入托名额，持证幼教助理常年供不应求，毕业即对口就业。"}, {"title": "充满爱心与成就感的工作", "desc": "在儿童大脑发育黄金期给予关爱与科学启蒙，陪伴孩子们健康快乐成长，深受家长信赖与社会尊重。"}, {"title": "安全、正规与舒适的工作环境", "desc": "在安省持牌正规托儿所、幼儿园及公校课后班工作，与注册幼教老师（RECE）团队协作，工作时间规律，带薪假期充裕。"}, {"title": "通往 RECE 幼教名师的快捷跳板", "desc": "快速积累加国本土一线幼教经验，未来可无缝衔接安省注册幼教（RECE）进阶文凭、日托主管或创办家庭日托。"}]}, "credentials": {"title": "官方认证毕业文凭与资格证书", "subtitle": "顺利完成全部理论科目与实地实习后，毕业生将获得安省幼教行业权威官方资质：", "items": [{"title": "安省 ECA 幼教助理官方职业文凭", "desc": "安省教育部备案注册职业文凭，全省持牌托儿所、幼儿园及早教机构通用认可。"}, {"title": "儿童标准急救与 CPR Level C 证书", "desc": "安省日托中心法定必备的婴幼儿心肺复苏与突发意外急救官方认证。"}, {"title": "食品安全与儿童营养卫生证书", "desc": "掌握幼教机构日常配餐卫生、过敏源防范与膳食营养管理专业技能。"}, {"title": "100% 保障 500+ 小时正规日托实地实习", "desc": "涵盖婴儿班（Infant）、幼儿班（Toddler）及学前班（Preschool）的全阶段实战经验。"}]}, "practicum": {"title": "保障 500+ 小时安省持牌日托中心实地跟岗实习", "desc": "维多利亚学院负责全流程对口安排大多伦多地区（Markham、Toronto、Richmond Hill、Scarborough、Mississauga 等）持牌日托中心及蒙特梭利学校的实习岗位，由资深注册幼教（RECE）导师一对一手把手带教。", "box_title": "实习基地直接留用签约率高", "box_desc": "超过 85% 的维多利亚学院 ECA 毕业生在实习期间直接获得实习机构全职录用合同（Job Offer）！"}, "admissions": {"title": "入学报读条件与要求", "items": ["具备安大略省高中毕业文凭（OSSD / 12年级）或加国/海外同等学历评估认证。", "成熟学生入学通道：年满 18 周岁，并通过学院 Wonderlic 入学能力测评（校区免费测试）。", "提供合格的警方无犯罪记录弱势群体筛查证明（Vulnerable Sector Check）。", "完成标准医疗体检与疫苗接种记录（包含 2 步骤结核病 TB 皮试）。", "热爱幼儿教育事业，具备耐心与亲和力，具备基础英语沟通与交流能力。"]}, "curriculum": {"title": "官方 22 周教学大纲（10 门专业核心科目）", "desc": "严格遵循安省《托儿与早期儿童法案》（CCEYA 2014）与官方幼教发展指南（How Does Learning Happen?）精心设计："}, "curriculum_modules": [{"num": 1, "title": "加拿大幼儿教育概论与安省日托管理法规", "desc": "早期教育发展历史、安省 CCEYA 2014 日托法规、机构执照要求与职业道德规范。"}, {"num": 2, "title": "儿童生长与心理发展：婴儿期至幼童期", "desc": "0–18个月婴儿与18–30个月幼童的生理、认知、情感与社交发育里程碑及大脑发育理论。"}, {"num": 3, "title": "儿童生长与心理发展：学龄前期至学龄期", "desc": "2.5–5岁学前儿童与6–12岁学龄儿童的心理特征、语言获得、精细运动与同伴交往。"}, {"num": 4, "title": "日托中心健康、安全防护、营养与应急处理", "desc": "卫生消毒与传染病防控、安全隐患排查、严重过敏反应管理、营养膳食与儿科急救。"}, {"num": 5, "title": "幼儿创意启蒙：美术、音乐律动、故事会与感统游戏", "desc": "设计激发幼儿想象力与创造力的艺术手工、音乐节奏律动、绘本精读与多感官探索游戏。"}, {"num": 6, "title": "儿童行为积极引导与班级常规管理", "desc": "儿童心理积极引导策略、情绪自控能力培养、冲突化解技巧与温馨班级日常作息建立。"}, {"num": 7, "title": "家园共育沟通技能与多文化背景团队协作", "desc": "与多元文化背景家庭建立信任伙伴关系、日常家长交接沟通、与主班幼教（RECE）协作。"}, {"num": 8, "title": "启蒙教案编制与儿童观察记录档案", "desc": "践行安省 ''How Does Learning Happen?'' 指南，设计以玩促学环境，记录儿童成长档案。"}, {"num": 9, "title": "特殊需求儿童关怀与融合教育实践", "desc": "全包容性幼教理念、神经多样性与自闭症儿童支持、感统失调应对及与特教顾问配合。"}, {"num": 10, "title": "安省持牌日托中心 500+ 小时实地跟岗实习", "desc": "在持牌托儿所婴儿班、幼童班和学前班进行全真实操演练，由资深 RECE 导师现场带教。"}], "grants": {"badge": "安省政府培训资助", "title": "申请最高 $28,000+ 政府全额无偿助学金", "description": "早期幼儿教育助理专业完全符合安省 Better Jobs Ontario（原第二职业 Second Career）政府培训资助计划。符合条件的安省居民（失业、裁员、领过 EI、自雇、零工人员或低收入群体）最高可获 $28,000+ 加币全额无偿补贴，100% 覆盖学费、书本教材费、托儿补贴及学习期间基本生活费。", "amount": "$28,000+", "button_text": "立即免费评估资助资格"}, "snapshot": {"delivery": "混成教学（线上理论直播 + 持牌日托实地实习）", "practicum": "500+ 小时（100% 对口保障安排）", "locations": "万锦主校区 / 在线名师直播", "hotline": "416-665-6668"}, "faqs": [{"q": "幼教 ECA 课程可以在家线上学习理论吗？", "a": "可以！所有理论课程与互动研讨均采用线上名师实时直播教学，配合课后录播复习，随后由学院为您就近安排当地安省持牌日托中心进行实地跟岗实习。"}, {"q": "ECA 幼教助理课程需要学习多久？", "a": "课程总计 22 周，包含系统的幼儿心理与启蒙教育理论课、教案设计工坊以及 500+ 小时持牌托儿所全真实战实习。"}, {"q": "在安省 ECA（幼教助理）和 ECE（注册幼教）有什么区别？", "a": "ECA 是协助主班 ECE 开展日常教学、幼儿生活照料与安全看护的专业人员。ECA 课程周期短（22周），学费更低，能帮助您以最快速度进入安省幼教行业并获得稳定收入，未来还可继续进修成为 RECE。"}, {"q": "我可以申请政府学费资助吗？", "a": "完全可以！本课程符合安省 Better Jobs Ontario 政府资助计划，合资格者最高可获 $28,000+ 无偿政府全额补贴，无需偿还，学院专家免费协助全程申请。"}, {"q": "学校会保障安排正规托儿所实习吗？", "a": "是的！维多利亚学院拥有遍布大多伦多地区的庞大签约日托中心网络，100% 为每位学员对口落实 500+ 小时正规实习岗位。"}, {"q": "毕业后的就业前景和薪酬待遇如何？", "a": "在安省 $10/天普惠日托政策推动下，全省幼教缺口巨大，薪资待遇优厚，且符合条件的机构员工还可额外享受安省政府工资补贴（WEG），福利完善，工作稳定。"}]}');
INSERT INTO "programs" VALUES(4,'acupuncture','wellness','images/acupuncture.jpg','Non-Vocational Enrichment Course','非职业特色兴趣课程 • 强身健体','Acupuncture','中医针灸与传统养生保健课程','Acupuncture program is a Non-Vocational Program. This program does not require approval under the Ontario Career Colleges Act, 2005.
INSERT INTO "programs" VALUES(5,'electrician','trades','images/electrician.jpg','Pre-Exam & Apprenticeship Coaching','安省持牌技工高薪黄金专业','Electrician (Construction & Maintenance)','建筑与维护电工考证培训班 (309A / 442A)','Becoming an Electrician in Ontario — Series Classes','安省考电工牌照就业系列课程 — 理论结合实战','["Instructor: working in one of the biggest electrician contractors in Ontario with 20+ years", "Placement in government projects and get real and valuable experiences", "1 v 1 hands-on teaching in official recognized Apprenticeship Base and get solid techniques in a short time", "Exclusive opportunity to be referred to a job after class completion"]','["授课名师：安省 20 余年一线西人大型工程公司项目主管，亲授核心考点", "政府及商业大中型工程实战环境，获取极具含金量的加拿大本土实战经验", "官方认可学徒实训基地 1对1 动手实操教学，短时间内迅速掌握规范操作要领", "结业即享大多伦多地区持牌工程团队与工会直推就业通道"]','Comprehensive Weekend & Fast-Track Intensive','考证冲刺班 / 实用周末班（灵活随到随学）','Certificate of Pre-Exam Training & Job Referral','结业证书 + 红宝书真题库 + 雇主直推信','Coached by master electricians with 20+ years of Canadian union, commercial, and residential contracting experience. Combines Canadian Electrical Code (CEC) mastery with hands-on wiring labs.','由安省 20 余年一线西人大型工程公司项目主管与资深华人电工名师联袂授课。将加国电气规范（CEC）考点精讲与安省学徒实训基地真机实操融为一体，助学员一次性高效通关拿牌。','["Canadian Electrical Code (CEC / OESC) Structure & Fast Navigation", "Electrical Safety, PPE, Lockout/Tagout (LOTO) & Arc Flash Protection", "DC/AC Electrical Theory, Magnetism & Power Calculations", "Residential Wiring Systems & 100A/200A Service Panels", "3-Phase Power Distribution & Commercial Wiring", "Transformers: Installation, Connections & Sizing Calculations", "Electric Motors, Magnetic Starters & Motor Control Circuits", "Conduit Bending, Raceways, Cable Trays & Installation Methods", "Electrical Blueprint Reading, Schematics & Specification Sizing", "Red Seal 309A / 442A C of Q Mock Exam Simulation & Question Bank"]','["加拿大电气规范 (CEC / OESC) 架构解析与极速查表秘籍", "电气安全施工规范、PPE、LOTO 挂牌上锁与电弧防范 (Arc Flash)", "直流/交流电理论、电磁学原理与三相电功率计算", "民用住宅电气布线系统与 100A/200A 主配电箱实战", "三相工业商业配电系统与配电柜接线 (Commercial 3-Phase)", "变压器原理、接线方式、过流保护与容量选型计算", "交流电动机、磁力启动器、控制继电器与电路原理图 (Motor Controls)", "管道弯管工艺 (Conduit Bending)、电缆桥架与穿线技巧", "电气施工图纸识图、图例符号、材料估算与负荷计算书编制", "安省 309A / 442A 执照考试全真模考冲刺与红宝书题库精讲"]','Licensed Construction Electrician (309A), Industrial Electrician (442A), Electrical Maintenance Specialist, Solar/Green Energy Installer.','安省持牌建筑电工（309A）、工业维护电工（442A）、电气工程承包商、太阳能与新能源技师。','Top-tier skilled trade with exceptional earning potential, union representation, comprehensive benefits, and strong career security across Ontario.','加国极受尊重的金牌持牌技工职业，享有优厚行业待遇、工会全套保障与丰厚退休金，职业前景稳健抗周期。',5,1,'2026-09-05T02:43:10.259254','2026-09-26T03:38:52.772540','{"hero": {"badge": "Ontario Skilled Trades • 309A / 442A Pre-Exam & Licensing", "title": "Master the Canadian Electrical Code & Fast-Track Your 309A / 442A License", "lead": "Coached by veteran Master Electricians with 20+ years of Canadian union, commercial, and industrial contracting experience. Master the Canadian Electrical Code (CEC / OESC), hands-on residential & 3-phase commercial wiring, motor controls, blueprint reading, and trade exam test banks to pass your Certificate of Qualification (C of Q) on your first attempt."}, "stats": [{"val": "Top Earning", "lbl": "Red Seal Licensed Journeyperson", "sub": "Union Scale & Comprehensive Pension"}, {"val": "20+ Yrs Mentorship", "lbl": "Master Electrician Taught", "sub": "Senior Project Leads from Top Firms"}, {"val": "1-on-1 Hands-on Labs", "lbl": "Apprenticeship Facility", "sub": "Panels, 3-Phase, Motors & Transformers"}, {"val": "Up to $28,000+ Grant", "lbl": "Government Funding Eligible", "sub": "Better Jobs Ontario & Apprentice Grants"}], "why_choose": {"title": "Why Choose a Career as a Licensed Electrician in Ontario?", "subtitle": "Electrical trades represent one of Canada''s most respected, lucrative, and recession-proof professions. As Ontario experiences massive infrastructure growth, electric vehicle transitions, and residential expansions, licensed 309A and 442A electricians command premium wages, comprehensive benefits, and strong union representation.", "pillars": [{"title": "Top-Tier Earning Potential & Stability", "desc": "Licensed journeypersons in the GTA command top-tier trade compensation with extensive overtime opportunities, comprehensive union pension plans, full health benefits, and strong career security."}, {"title": "100% CEC Code Mastery & Exam Fast-Track", "desc": "Systematic breakdown of the Canadian Electrical Code (CEC / OESC). Master rapid table navigation, load sizing formulas, and key question patterns to pass the C of Q exam with confidence."}, {"title": "1-on-1 Hands-on Wiring & Distribution Labs", "desc": "Train in our recognized apprenticeship lab: residential 100A/200A distribution panels, commercial 3-phase 600V systems, transformer connections, magnetic motor starters, and conduit bending."}, {"title": "Trade Qualifier Support & Job Referrals", "desc": "Expert guidance for experienced tradespeople challenging the exam via the Trade Qualifier pathway, plus direct employer introductions and union dispatch referral networks across the GTA."}]}, "credentials": {"title": "Credentials, Certifications & Exam Readiness", "subtitle": "Upon completion of training and practical assessments, students achieve recognized milestones toward their journeyperson license:", "items": [{"title": "Ontario 309A / 442A Exam Readiness Certificate", "desc": "Official verification of completion in Canadian Electrical Code theory and Certificate of Qualification examination prep."}, {"title": "Canadian Electrical Code (CEC) Specialist Credential", "desc": "Demonstrates advanced mastery in Ontario Electrical Safety Code (OESC) interpretation, ampacity tables, and conductor sizing."}, {"title": "Lockout/Tagout (LOTO) & Arc Flash Safety Record", "desc": "Comprehensive training in CSA Z462 electrical safety standards, high-voltage isolation, hazard boundaries, and PPE protocols."}, {"title": "Commercial Blueprint & Schematic Sizing Portfolio", "desc": "Practical portfolio showcasing single-line diagrams, commercial branch load schedules, 3-phase balancing, and motor control circuits."}]}, "curriculum": {"title": "Comprehensive 10-Module Curriculum Outline", "desc": "A rigorous, code-focused curriculum preparing students for both field mastery and the Skilled Trades Ontario (STO) Red Seal licensing exam:"}, "curriculum_modules": [{"num": 1, "title": "Canadian Electrical Code (CEC / OESC) Structure & Fast Navigation", "hours": "30 Hours", "desc": "Code layout, Section 0–16 general rules, conductor ampacity (Tables 1–4), temperature ratings, derating factors (Table 5C), conduit fill (Tables 6A–K), and exam lookup strategies."}, {"num": 2, "title": "Electrical Safety, PPE, Lockout/Tagout (LOTO) & Arc Flash Protection", "hours": "20 Hours", "desc": "Occupational Health & Safety Act (OHSA), CSA Z462 electrical workplace safety, shock boundaries, arc flash PPE categories, ground fault protection, and bonding rules (Section 10)."}, {"num": 3, "title": "DC/AC Electrical Theory, Magnetism & Power Calculations", "hours": "30 Hours", "desc": "Ohm''s law, Kirchhoff''s laws, series/parallel combinations, inductance, capacitance, single-phase and 3-phase AC power calculations, power factor correction, and apparent vs active power."}, {"num": 4, "title": "Residential Wiring Systems & 100A/200A Service Panels", "hours": "35 Hours", "desc": "Residential load calculations (Section 8), service entrance sizing, main breaker panels, branch circuit design, AFCI/GFCI protection, kitchen/bathroom code rules, and multi-wire circuits."}, {"num": 5, "title": "3-Phase Power Distribution & Commercial Wiring", "hours": "35 Hours", "desc": "Commercial 120/208V and 347/600V distribution systems, delta and wye connections, neutral conductor sizing, commercial panelboards, disconnect switches, and energy-efficient lighting controls."}, {"num": 6, "title": "Transformers: Installation, Connections & Sizing Calculations", "hours": "30 Hours", "desc": "Single-phase and 3-phase transformers (Section 26), step-up and step-down applications, delta-wye connections, autotransformers, turns ratio, primary/secondary overcurrent protection sizing."}, {"num": 7, "title": "Electric Motors, Magnetic Starters & Motor Control Circuits", "hours": "35 Hours", "desc": "Single-phase and 3-phase AC induction motors (Section 28), stop/start latching circuits, forward/reversing starters, overload protection sizing, time-delay relays, and ladder schematics."}, {"num": 8, "title": "Conduit Bending, Raceways, Cable Trays & Installation Methods", "hours": "30 Hours", "desc": "Hands-on EMT and rigid conduit bending (90-degree stubs, back-to-back, kicks, 3-point/4-point saddles), mechanical raceways, cable trays (Section 12), and wire pulling practices."}, {"num": 9, "title": "Electrical Blueprint Reading, Schematics & Specification Sizing", "hours": "25 Hours", "desc": "Architectural and engineering drawing symbols, electrical site plans, single-line power diagrams, panel schedules, lighting layouts, material takeoffs, and project cost estimating."}, {"num": 10, "title": "Red Seal 309A / 442A C of Q Mock Exam Simulation & Question Bank", "hours": "30 Hours", "desc": "Timed full-length mock exams modeled on the Skilled Trades Ontario exam blueprint. Detailed breakdown of tricky questions, formula shortcuts, and time-management techniques."}], "practicum": {"title": "Hands-on Electrical Lab & Training Facility", "desc": "Victoria International College provides students with direct access to dedicated electrical training workstations. Students gain practical, muscle-memory experience wiring real electrical equipment under the supervision of practicing Master Electricians.", "box_title": "Direct Contractor Networking & Trade Qualifier Guidance", "box_desc": "Over 90% of our exam preparation graduates successfully pass their Red Seal / C of Q exam and gain rapid referrals to top GTA electrical contractors and union locals!"}, "admissions": {"title": "Admission Requirements & Prerequisites", "items": ["Ontario Secondary School Diploma (OSSD / Grade 12) or Canadian / International equivalent evaluation.", "Mature Student Admission: 18 years of age or older with passing score on the Wonderlic entrance assessment.", "Trade Qualifier candidates: Domestic or international electrical trade experience eligible for Skilled Trades Ontario exam challenge.", "Registered Apprentices: Currently registered with Ministry of Labour, Immigration, Training and Skills Development (MLITSD).", "Basic mathematical proficiency (algebra and trigonometry fundamentals) and strong safety awareness."]}, "grants": {"badge": "GOVERNMENT FUNDING AVAILABLE", "title": "Get Up to $28,000+ Grant", "description": "Study Electrician pre-exam and skills training with zero out-of-pocket tuition. Eligible candidates (laid-off workers, EI recipients, gig workers, self-employed, or low-income residents) may qualify for up to $28,000+ in non-repayable Better Jobs Ontario grants covering tuition, tools, books, and living expenses.", "amount": "$28,000+", "button_text": "Check Grant Eligibility Now"}, "snapshot": {"delivery": "Hybrid (Online Code Theory + Hands-on Lab)", "practicum": "1-on-1 Lab Workstations & Test Bank", "locations": "Markham Main Campus / Live Online", "hotline": "416-665-6668"}, "faqs": [{"q": "What is the difference between 309A Construction & Maintenance and 442A Industrial Electrician?", "a": "309A Construction and Maintenance Electrician is Ontario''s most versatile license, permitting work in residential, commercial, institutional, and industrial settings. 442A Industrial Electrician focuses specifically on factory automation, manufacturing plant machinery, motor controls, PLCs, and industrial electrical maintenance."}, {"q": "Can I challenge the 309A / 442A exam if I have international or non-registered electrical experience?", "a": "Yes! Through Skilled Trades Ontario''s Trade Equivalency Assessment (Trade Qualifier pathway), individuals with verified work experience (typically 9,000+ hours for 309A) can apply to challenge the Certificate of Qualification exam directly without repeating a 5-year apprenticeship."}, {"q": "Can I attend classes while working full-time?", "a": "Yes! We offer flexible weekend and evening cohort schedules specifically designed for working adults, trades helpers, and apprentices to study code theory online and attend hands-on labs on weekends."}, {"q": "Are there government grants or financial aid available for this program?", "a": "Yes! Victoria International College''s programs are eligible for Better Jobs Ontario (up to $28,000+ non-repayable grant covering tuition, books, tools, and living costs) as well as federal Apprenticeship Incentive Grants and Canada Apprentice Loans for registered apprentices."}, {"q": "Does the course include hands-on practical wiring training?", "a": "Yes! In addition to in-depth Canadian Electrical Code theory and exam question drills, students train in our dedicated electrical lab with residential panels, 3-phase disconnects, transformers, motor control boards, and conduit bending equipment."}, {"q": "How does Victoria International College support graduates with finding jobs or joining the union?", "a": "We provide 1-on-1 resume optimization for the Canadian trade market, guidance on joining IBEW union locals or CLAC, and direct networking referrals to licensed electrical contractor partners across the GTA."}]}','{"hero": {"badge": "安省持牌技工高薪黄金专业 • 309A / 442A 考证与实操", "title": "精通加拿大电气规范 (CEC) • 快速通关安省 309A 建筑与 442A 工业电工牌照", "lead": "由安省 20 余年一线西人大型工程公司项目主管、资深持牌 Master Electrician 名师亲自授课。将加国最新电气规范（CEC / OESC）核心考点精讲、官方认可学徒实训基地 1对1 动手实操接线（民用配电箱/三相电/变压器/电机控制/管道弯管）与红宝书全真题库模考融为一体，助您一次性高分通关拿牌并对口就业！"}, "stats": [{"val": "高薪典范", "lbl": "安省红印执照金牌技工 • 工会优厚待遇", "sub": "红印执照 / 工会优厚待遇与丰厚养老金"}, {"val": "20+ 年名师带教", "lbl": "大师级持牌电工亲授", "sub": "加国一线大型西人工程公司资深项目主管"}, {"val": "1对1 动手实操机房", "lbl": "官方认可学徒实训基地", "sub": "配电箱、三相电、变压器与电机控制"}, {"val": "$28,000+ 政府补贴", "lbl": "符合政府全额无偿资助", "sub": "Better Jobs Ontario 及学徒专项津贴"}], "why_choose": {"title": "为什么选择成为安省持牌电工 (Licensed Electrician)？", "subtitle": "电工是加拿大收入最高、最受社会尊重且极具抗周期性的金牌技工职业之一。随着安省大型基础设施建设、新能源电动汽车充电桩及住宅商业地产的蓬勃发展，持牌 309A 建筑电工与 442A 工业电工常年极度紧缺，薪酬福利优厚，工会保障完善。", "pillars": [{"title": "行业顶薪与极佳稳定性", "desc": "大多伦多持牌电工享有行业顶尖的丰厚薪酬与发展前景，享高额加班津贴、工会丰厚养老金、全家医疗牙医保险及带薪年假。"}, {"title": "100% 攻克加国电气规范 (CEC)", "desc": "全面系统拆解加拿大电气规范（Canadian Electrical Code / OESC），掌握极速查表技巧、负荷计算公式与高频必考题眼，确保一次性高分考取牌照。"}, {"title": "1对1 动手实操与接线实战", "desc": "在官方认可学徒基地动手实操：民用 100A/200A 配电盘、商业三相 600V 强电系统、变压器接线、交流接触器与磁力电机启动柜、管道弯管（Conduit Bending）。"}, {"title": "海外经验资格评估与对口内推", "desc": "协助具备海内外工程经验的学员通过 Trade Qualifier 快速通道申请免学徒直接挑战考证，并向大多伦多知名西人/华人工程公司及工会定向推荐就业。"}]}, "credentials": {"title": "官方培训资质、技能成果与考证直通", "subtitle": "顺利完成全部理论培训与实操考核后，学员将获得加国电气行业高度认可的实战能力与考证资质：", "items": [{"title": "安省 309A / 442A 考证通关结业证书", "desc": "维多利亚学院官方颁发的加拿大电气规范理论与 Red Seal 考前冲刺培训结业证书。"}, {"title": "加拿大电气规范 (CEC) 规范应用专家认证", "desc": "深度掌握安省电气安全局（OESC）各项安全法规、导线载流量校核、短路保护与变压器选型。"}, {"title": "电气安全、LOTO 挂牌上锁与电弧防护证书", "desc": "全面掌握 CSA Z462 工作场所电气安全操作规程、高压隔离排空、防护绝缘装备（PPE）与急救规范。"}, {"title": "商业电气施工图纸识图与负荷计算作品集", "desc": "独立完成商业单线配电系统图（Single-Line Diagram）、三相平衡负荷表、照明动力回路及电机控制原理图编制。"}]}, "curriculum": {"title": "官方 10 门专业系统核心课程模块", "desc": "紧扣 Skilled Trades Ontario 考纲要求与加国一线工地施工标准精心设计，理论考点与动手实操并重："}, "curriculum_modules": [{"num": 1, "title": "加拿大电气规范 (CEC / OESC) 架构解析与极速查表秘籍", "hours": "30 学时", "desc": "Code Book 篇章逻辑、Section 0–16 通用规则、导线载流量表（Tables 1–4）、温度与降容系数（Table 5C）、管内穿线率表（Tables 6A–K）及快速定位考点策略。"}, {"num": 2, "title": "电气安全施工规范、PPE、LOTO 挂牌上锁与电弧防范 (Arc Flash)", "hours": "20 学时", "desc": "安省职业健康与安全法案（OHSA）、CSA Z462 电气作业安全、触电危险边界、电弧防护级别、接地（Grounding）与接零保护（Bonding - Section 10）。"}, {"num": 3, "title": "直流/交流电理论、电磁学原理与三相电功率计算", "hours": "30 学时", "desc": "欧姆定律、基尔霍夫定律、串并联回路、感抗与容抗、单相与三相交流功率计算（视在功率、有功功率、无功功率）、功率因数补偿与相序分析。"}, {"num": 4, "title": "民用住宅电气布线系统与 100A/200A 主配电箱实战", "hours": "35 学时", "desc": "住宅总负荷计算（Section 8）、进线配电箱配置、断路器选用、分支回路分配、AFCI 电弧断路器与 GFCI 漏电保护器接线、厨卫电气规范及多线分支回路。"}, {"num": 5, "title": "三相工业商业配电系统与配电柜接线 (Commercial 3-Phase)", "hours": "35 学时", "desc": "商业 120/208V 与 347/600V 配电系统、星形（Wye）与角形（Delta）接法、中性线计算、商业配电盘安装、隔离开关（Disconnect Switches）与智能照明控制系统。"}, {"num": 6, "title": "变压器原理、接线方式、过流保护与容量选型计算", "hours": "30 学时", "desc": "单相与三相电力变压器（Section 26）、升压/降压变压器、自耦变压器、变比计算、一次侧/二次侧过电流保护器与熔断器精准整定计算。"}, {"num": 7, "title": "交流电动机、磁力启动器、控制继电器与电路原理图 (Motor Controls)", "hours": "35 学时", "desc": "单相与三相交流感应电动机（Section 28）、启停自锁控制回路、正反转磁力启动器、热过载继电器整定、时间继电器与梯形逻辑控制图识图。"}, {"num": 8, "title": "管道弯管工艺 (Conduit Bending)、电缆桥架与穿线技巧", "hours": "30 学时", "desc": "EMT 金属管与刚性管手工/机械弯管（90度弯头、背对背弯、偏置弯 Kick、三点/四点鞍形弯）、电缆桥架安装（Section 12）与工业穿线拉线实操。"}, {"num": 9, "title": "电气施工图纸识图、图例符号、材料估算与负荷计算书编制", "hours": "25 学时", "desc": "建筑电气施工图图例符号、配电平面图、系统单线图（Single-Line Diagram）、动力箱负荷明细表、工程材料量核算（Takeoff）与施工报价。"}, {"num": 10, "title": "安省 309A / 442A 执照考试全真模考冲刺与红宝书题库精讲", "hours": "30 学时", "desc": "严格按照 Skilled Trades Ontario 统考模式进行限时全真模考，深度拆解高频陷阱题、公式速记技巧与应试时间分配，确保一次性高分通关！"}], "practicum": {"title": "官方认可电工实训基地与 1对1 动手实操", "desc": "维多利亚职业学院配备标准电气实训工位，学员在资深持牌 Master Electrician 导师的指导下，直接动手操作真实配电箱、工业变压器、电机控制柜与弯管设备，迅速将规范转化为肌肉记忆实战能力。", "box_title": "大多伦多工程团队对口直推与工会内荐", "box_desc": "维多利亚学院电工班学员考试通过率名列前茅，超过 90% 的积极学员在考取牌照后迅速获得知名西人/华人电气工程公司聘用或成功加入 IBEW 电工工会！"}, "admissions": {"title": "入学报读条件与适合人群", "items": ["具备安大略省高中毕业文凭（OSSD / 12年级）或加国及海外同等学历评估认证。", "成熟学生通道：年满 18 周岁，并通过学院基础能力测评（校区/线上免费测评）。", "Trade Qualifier 经验挑战通道：具备海内外电气、自动化、机械、机电相关工程经验，希望快速免学徒直接考牌的人士。", "现职学徒及电工助手：已在安省技术移民及技能发展厅（MLITSD）注册学徒或从事 Helper 工作的技工。", "具备基础数学逻辑（初等代数与几何）以及严谨的安全防护意识。"]}, "grants": {"badge": "安省政府培训资助", "title": "申请最高 $28,000+ 政府助学金", "description": "电工考证与实操培训完全符合安省 Better Jobs Ontario（原第二职业 Second Career）政府培训资助计划。符合条件的安省居民（失业、裁员、领过 EI、自雇、零工人员或低收入群体）最高可申请 $28,000+ 加币全额无偿补贴，100% 覆盖学费、工具费、书本教材费及学习期间基本生活费。", "amount": "$28,000+", "button_text": "立即免费评估资助资格"}, "snapshot": {"delivery": "混成教学（线上规范精讲 + 校区动手实操）", "practicum": "1对1 实操工位 + 全真红宝书题库", "locations": "万锦主校区 / 在线名师直播", "hotline": "416-665-6668"}, "faqs": [{"q": "309A 建筑维护电工和 442A 工业电工有什么区别？", "a": "309A 建筑与维护电工（Construction & Maintenance Electrician）是加国适用范围最广的电工执照，可在民用住宅、商业大楼、公共设施及工业厂房等所有领域合法执业；442A 工业电工（Industrial Electrician）则专注在工厂制造企业、自动化生产线、机械设备电气维护与 PLC 控制系统。"}, {"q": "我有海外电气工作经验，可以直接在安省挑战考电工牌照吗？", "a": "可以！通过安省技术工种局（Skilled Trades Ontario）的 Trade Equivalency Assessment（Trade Qualifier）海外经验评估，只要证明累积了相应工时（309A 通常为 9,000 小时，442A 通常为 8,100 小时），即可获批直接参加执照考试，无需从头重新做 5 年学徒。维多利亚学院提供全程经验认证指导。"}, {"q": "平时需要全职上班，有适合业余时间学习的班型吗？", "a": "有！我们专门开设了周末及晚间班，所有理论与规范精讲均支持在线直播与高清录播无限次回放，实操集中在周末进行，让您在不影响全职工作的同时高效备考。"}, {"q": "我可以申请政府全额学费资助吗？", "a": "可以！本课程符合安省 Better Jobs Ontario 政府资助计划，合资格者最高可获 $28,000+ 无需偿还的政府全额补贴，100% 报销学费、工具教材及生活津贴，学院专家免费协助全程申请。"}, {"q": "课程包含动手实操接线训练吗？", "a": "包含！除了深度的 CEC 电气规范精讲与红宝书全真题库模考，学员还将在官方认可实训基地亲自动手进行 100A/200A 配电盘、三相配电、变压器接线、电机磁力启动器与管道弯管实操演练。"}, {"q": "毕业后学校会协助推荐工作或加入工会吗？", "a": "是的！学院提供加国技工英文简历一对一修改、IBEW 国际电工工会申请指导，并向大多伦多地区长期合作的大中型持牌电气工程公司直接内推。"}]}');
INSERT INTO "programs" VALUES(6,'tech','technology','images/fullstack.jpg','Career Diploma • AI Mini-Credential','加国紧缺高薪 IT 职业文凭 • 含 AI 微证书','Full Stack Web with AI Mini-Credential','全栈开发与 AI 微证书 (Full Stack Web with AI Mini-Credential)','This diploma program contains theoretical concepts with practical lab work to ensure graduates have a solid foundation in the following areas: programming fundamentals, system testing, web programming, design concepts, networks, server and database programming, plus a cutting-edge AI Mini-Credential.','该职业文凭课程将理论概念与高强度实操上机紧密结合，确保毕业生在编程基础、系统测试、Web开发、设计模式、计算机网络、云端数据库及前沿 AI 微证书（生成式 AI 与大模型应用）等领域奠定坚实基础。','["Core Java", "Advanced Java", "Network Programming", "HTML/CSS/JavaScript", "SpringBoot", "Mybatis", "Spring/Spring MVC", "MySQL", "React/Nodejs/webpack", "Spring Cloud", "Netty", "AWS", "Design Pattern", "AI Mini-Credential"]','["Core Java 核心编程", "Java 进阶与多线程", "网络高并发编程", "HTML/CSS/JavaScript", "SpringBoot 企业级开发", "Mybatis 数据库持久化", "Spring / Spring MVC", "MySQL 数据库设计与优化", "React / Nodejs / Webpack", "Spring Cloud 微服务架构", "Netty 高性能网络框架", "AWS 云端部署与运维", "企业级设计模式与架构实战", "AI 微证书 (AI Mini-Credential)"]','32 Weeks (Intensive Labs + Commercial Projects)','32 周（高强度实战机房 + 商业级项目交付）','Full Stack Web Technician Diploma + AI Mini-Credential','安省教育部认证 Full Stack Web Technician 职业文凭 + AI 微证书','An intensive software engineering diploma blending theoretical computer science foundations with modern enterprise web development, server architecture, cloud platforms, and full-stack project building. Includes an integrated AI Mini-Credential covering Generative AI and LLM enterprise integration.','紧扣北美一线大厂与金融机构用人标准，从编程底层基础到企业级微服务架构、React 前端开发与 AWS 云端部署，并深度融入 AI 微证书（生成式 AI 与 LLM 大模型开发实战），手把手带领学员打造高含金量商业项目作品集。','["Computer Science Fundamentals, OOP & Core Programming Architecture", "Modern Frontend Core: HTML5, CSS3, Responsive Design & Modern JavaScript (ES6+)", "Enterprise Frontend Engineering: TypeScript & React 19 Architecture", "Next.js Full-Stack Architecture: Server Components, SSR & App Router", "Backend Engineering: Node.js, Express & RESTful Microservices", "Enterprise Java & Spring Boot Microservices Ecosystem", "Database Engineering: Relational SQL, NoSQL & High-Performance Caching", "Generative AI Engineering: LLMs, OpenAI API, LangChain & Vector Databases", "Cloud Infrastructure, Docker Containers & DevOps CI/CD Pipelines", "Enterprise Capstone Project, System Design & Tech Interview Mastery"]','["计算机底层核心、面向对象编程 (OOP) 与算法数据结构", "现代前端基础：HTML5、CSS3 响应式布局与 JavaScript (ES6+) 进阶", "企业级前端工程：TypeScript 与 React 19 核心架构", "Next.js 全栈架构：服务端组件 (RSC)、SSR 与 App Router 路由", "现代后端工程：Node.js、Express 框架与 RESTful 微服务", "企业级 Java 后端微服务生态：Spring Boot 3 与 MyBatis", "数据库架构与优化：SQL 关系型、NoSQL 与 Redis 高性能缓存", "AI 智能工程微证书：LLM 大模型、OpenAI API、LangChain 与向量数据库", "云原生基础设施：Docker 容器化、AWS 云部署与 CI/CD 自动化流水线", "毕业大项目 Capstone：工业级 AI 赋能 SaaS 云平台与名企面试冲刺"]','Full Stack Developer, Java Backend Engineer, Frontend React Developer, AI/Web Applications Specialist, Cloud Software Associate.','全栈开发工程师（Full Stack Developer）、Java 后端工程师、React 前端工程师、AI/Web 软件技术专员。','High-demand tech career trajectory with rapid advancement in enterprise cloud and AI technologies. Direct preparation for technical interviews and system design.','紧跟加国高科技发展赛道，薪资待遇优厚，发展空间广阔。名师辅导简历深度技术包装、AI 辅助编程与企业级全真模拟面试。',6,1,'2026-09-05T02:43:10.259254','2026-09-26T03:38:52.772540','{"hero": {"badge": "Career Diploma • AI Mini-Credential", "title": "Master Full-Stack Web Development & Enterprise Generative AI Integration", "lead": "Coached by senior tech leads from top Canadian financial institutions and tech enterprises. Master modern frontend architecture (React 19 / Next.js / TypeScript), robust backend microservices (Node.js / Python / Spring Boot), cloud DevOps (AWS / Docker), and cutting-edge Generative AI engineering (OpenAI API, LangChain, RAG, Vector DBs). Build production-ready portfolio projects and land high-paying software engineering careers.", "cta_book": "Book Free Tech Career Consultation", "cta_curriculum": "Explore 10-Module Curriculum"}, "stats": [{"value": "High Demand", "label": "High-Growth Tech Career & AI Integration", "sub": "Enterprise Web & Cloud Solutions"}, {"value": "100% Project Labs", "label": "Real-World Commercial Portfolio", "sub": "SaaS, AI Integrations & GitHub Repos"}, {"value": "FAANG Mentorship", "label": "Senior Industry Tech Leads", "sub": "1-on-1 Code Reviews & Mock Tech Interviews"}, {"value": "Up to $28,000+", "label": "Government Grants Available", "sub": "Better Jobs Ontario & Job Grant Eligible"}], "why_choose": {"title": "Why Choose Full Stack Web Development with AI Mini-Credential?", "subtitle": "Software development continues to be one of Canada''s most in-demand, resilient, and highest-paying career paths. With the explosive rise of Generative AI, developers who understand how to build robust full-stack web applications and integrate AI capabilities command top market compensation.", "pillars": [{"title": "Modern Enterprise Full-Stack Architecture", "desc": "Master end-to-end full stack development: React 19, Next.js App Router, TypeScript, Node.js, Python, Spring Boot, PostgreSQL, MongoDB, and Redis caching."}, {"title": "Integrated Generative AI & LLM Engineering", "desc": "Stand out from traditional coders. Build intelligent applications with OpenAI/Claude APIs, LangChain, Retrieval-Augmented Generation (RAG), and vector databases."}, {"title": "Cloud Native DevOps & Production Deployment", "desc": "Gain hands-on experience containerizing apps with Docker, deploying to AWS (EC2, S3, RDS, Lambda), and setting up automated CI/CD pipelines via GitHub Actions."}, {"title": "1-on-1 Tech Interview Coaching & Job Referrals", "desc": "Get tailored resume packaging, GitHub code review, LeetCode algorithmic drills, system design practice, and direct introductions to hiring tech partners across the GTA."}]}, "credentials": {"title": "Diplomas, Micro-Credentials & Portfolio Milestones", "subtitle": "Graduates earn recognized career credentials and build an employer-ready GitHub portfolio:", "items": [{"title": "Full Stack Web Technician Career Diploma", "desc": "Registered vocational diploma verifying mastery of modern full stack software engineering and database systems."}, {"title": "Generative AI Engineering Mini-Credential", "desc": "Specialized micro-credential certifying hands-on proficiency in LLM API integration, prompt engineering, and RAG systems."}, {"title": "AWS Cloud & DevOps Practitioner Badge", "desc": "Proof of competence in containerization, cloud infrastructure provisioning, serverless functions, and CI/CD pipelines."}, {"title": "Production-Grade Capstone SaaS Portfolio", "desc": "A live, fully deployed full-stack SaaS application with authentication, payments, database persistence, and AI features on GitHub."}]}, "curriculum": {"title": "Comprehensive 10-Module Curriculum Outline", "desc": "A structured, hands-on 32-week software engineering curriculum designed to take you from foundational programming to enterprise-ready AI full-stack developer:"}, "curriculum_modules": [{"num": 1, "title": "Computer Science Fundamentals, OOP & Core Programming Architecture", "hours": "35 Hours", "desc": "Core algorithms, data structures (arrays, linked lists, hash maps, trees), Big-O complexity, Object-Oriented Programming (OOP) principles, clean code design, and Git version control workflows."}, {"num": 2, "title": "Modern Frontend Core: HTML5, CSS3, Responsive Design & Modern JavaScript (ES6+)", "hours": "35 Hours", "desc": "Semantic HTML, Flexbox, CSS Grid, Tailwind CSS, DOM manipulation, ES6+ features (closures, promises, async/await, modules), event-driven programming, and client-side debugging."}, {"num": 3, "title": "Enterprise Frontend Engineering: TypeScript & React 19 Architecture", "hours": "40 Hours", "desc": "TypeScript static typing, interfaces, generics; React 19 functional components, custom hooks, context API, state management with Redux Toolkit/Zustand, and performance optimization."}, {"num": 4, "title": "Next.js Full-Stack Architecture: Server Components, SSR & App Router", "hours": "35 Hours", "desc": "Next.js App Router, React Server Components (RSC), Server-Side Rendering (SSR), Static Site Generation (SSG), dynamic routing, API route handlers, and middleware security."}, {"num": 5, "title": "Backend Engineering: Node.js, Express & RESTful Microservices", "hours": "35 Hours", "desc": "Asynchronous event-loop architecture, Express.js middleware, RESTful API design standards, JWT / OAuth2 authentication, rate limiting, error handling, and unit testing with Jest."}, {"num": 6, "title": "Enterprise Java & Spring Boot Microservices Ecosystem", "hours": "35 Hours", "desc": "Core & Advanced Java, JVM internals, Spring Boot 3, Dependency Injection, Spring MVC, Spring Security, MyBatis / Hibernate ORM, and enterprise service architecture."}, {"num": 7, "title": "Database Engineering: Relational SQL, NoSQL & High-Performance Caching", "hours": "35 Hours", "desc": "PostgreSQL and MySQL schema design, complex JOINs, indexing & query optimization, MongoDB document modeling, Prisma ORM, and Redis distributed caching."}, {"num": 8, "title": "Generative AI Engineering: LLMs, OpenAI API, LangChain & Vector Databases", "hours": "40 Hours", "desc": "OpenAI / Anthropic Claude API integration, prompt engineering techniques, LangChain / LlamaIndex workflows, Retrieval-Augmented Generation (RAG), embeddings, and Pinecone/ChromaDB vector search."}, {"num": 9, "title": "Cloud Infrastructure, Docker Containers & DevOps CI/CD Pipelines", "hours": "30 Hours", "desc": "Containerizing multi-service apps with Docker & Docker Compose, AWS cloud services (EC2, S3, RDS, Lambda), Vercel deployment, GitHub Actions automated CI/CD pipelines, and environment secrets."}, {"num": 10, "title": "Enterprise Capstone Project, System Design & Tech Interview Mastery", "hours": "40 Hours", "desc": "Build and deploy an enterprise-grade AI-powered SaaS application; comprehensive system design reviews (scalability, microservices, load balancing), LeetCode coding interview drills, and mock tech screens."}], "practicum": {"title": "Production-Grade Capstone Project & Enterprise Coding Labs", "desc": "Students work in agile sprint teams simulating enterprise tech environments. Under the direct guidance of senior tech leads from top Canadian enterprises, you will develop, code review, test, containerize, and deploy production-ready full-stack applications with integrated AI intelligence.", "box_title": "Direct Tech Employer Introductions & Alumni Referral Network", "box_desc": "Over 90% of our active tech graduates secure full-stack, frontend, backend, or QA engineering roles within 3 to 6 months of graduation, working across Toronto''s thriving fintech, healthcare tech, and software sectors."}, "admissions": {"title": "Admission Requirements & Prerequisites", "items": ["Ontario Secondary School Diploma (OSSD / Grade 12) or Canadian / International equivalent credential evaluation.", "Mature Student Admission: 18 years of age or older with a passing score on the college entrance assessment.", "Basic computer literacy and logical problem-solving aptitude (no prior coding experience strictly required; introductory bootcamp modules included).", "Career changers, engineering/science graduates, and existing IT professionals looking to upskill with modern AI and Full-Stack technologies.", "English language proficiency suitable for technical communication and documentation."]}, "grants": {"badge": "GOVERNMENT GRANTS", "title": "Get Up to $28,000+ Government Grant", "description": "Victoria International College''s Full Stack Web with AI Mini-Credential diploma is approved for the Better Jobs Ontario (Second Career) grant program, providing up to $28,000+ in non-repayable government funding for eligible applicants, covering 100% tuition, computer allowance, books, and living support.", "amount": "$28,000+", "button_text": "Check Grant Eligibility Now"}, "snapshot": {"delivery": "Live Online + In-Person Campus Labs", "practicum": "Enterprise Capstone + GitHub Portfolio", "locations": "Markham Main Campus / Live Online", "hotline": "416-665-6668"}, "faqs": [{"q": "Do I need a Computer Science degree or prior coding experience to enroll?", "a": "No prior coding background is required! Our program is carefully designed to take beginners from programming fundamentals to enterprise-level full-stack and AI engineering through structured labs, step-by-step guidance, and mentor code reviews."}, {"q": "What is the AI Mini-Credential included in this program?", "a": "The AI Mini-Credential is a cutting-edge curriculum track covering Generative AI integration, LLM APIs (OpenAI GPT-4, Claude), prompt engineering, Retrieval-Augmented Generation (RAG), and vector databases. You''ll build smart web applications capable of semantic search, automated summarization, AI chat, and workflow automation."}, {"q": "What technologies and frameworks will I master?", "a": "You will gain hands-on mastery in HTML5, CSS3, Tailwind CSS, JavaScript (ES6+), TypeScript, React 19, Next.js, Node.js, Express, Java, Spring Boot, PostgreSQL, MongoDB, Redis, Docker, AWS (EC2/S3/RDS/Lambda), Git/GitHub, and OpenAI/LangChain."}, {"q": "Is this program eligible for government grants like Better Jobs Ontario?", "a": "Yes! Victoria International College is a registered career college under the Ontario Career Colleges Act, 2005. Eligible individuals (unemployed, laid-off, gig workers, or underemployed) can qualify for up to $28,000+ in non-repayable Better Jobs Ontario funding covering 100% of tuition, tech equipment, and living costs."}, {"q": "How does Victoria International College support students with job placement?", "a": "We provide comprehensive tech career services: 1-on-1 resume optimization, GitHub portfolio polishing, technical mock interviews (data structures, algorithms, system design), LeetCode interview preparation, and direct job referrals to our GTA employer hiring network."}, {"q": "What is the class schedule and format?", "a": "We offer flexible formats including full-time weekday cohorts and part-time evening/weekend tracks. All live sessions are recorded in HD for 24/7 review, combined with collaborative online lab workstations and on-campus mentor access."}]}','{"hero": {"badge": "加国紧缺高薪 IT 职业文凭 • 含 AI 微证书", "title": "全栈软件工程开发与 AI 微证书大专文凭班", "lead": "由加拿大顶级银行与科技名企资深架构师亲授。从底层编程基础到现代前端工程（React 19 / Next.js / TypeScript）、企业级后端微服务（Node.js / Python / Java Spring Boot）、AWS 云原生运维（Docker / CI/CD），并深度融入前沿生成式 AI 大模型开发（OpenAI API, LangChain, RAG 检索增强, 向量数据库）。手把手带领学员打造高含金量商业项目作品集，直通北美高薪软件工程师就业岗位。", "cta_book": "预约免费名师 IT 规划咨询", "cta_curriculum": "查看 10 大核心模块大纲"}, "stats": [{"value": "高薪赛道", "label": "北美高科技紧缺开发岗位与前沿 AI 实战", "sub": "企业级微服务与全栈云原生开发"}, {"value": "100% 实战机房", "label": "商业级真实项目作品集", "sub": "企业级 SaaS、AI 集成与 GitHub 真实代码仓库"}, {"value": "北美名企名师", "label": "一线资深架构师手把手带教", "sub": "一对一代码审查与全真大厂模拟技术面试"}, {"value": "最高 $28,000+", "label": "安省政府培训全额助学金", "sub": "Better Jobs Ontario 资助计划合资格申请"}], "why_choose": {"title": "为什么选择全栈软件开发与 AI 微证书课程？", "subtitle": "软件开发始终是加拿大就业市场需求最旺盛、抗周期能力最强、薪资天花板最高的黄金职业之一。随着生成式 AI 与大模型技术的爆发，具备扎实全栈工程开发能力并精通 AI 集成落地的复合型开发者在招聘市场备受追捧。", "pillars": [{"title": "企业级现代全栈工程技术栈", "desc": "系统掌握全栈开发主流技术：React 19、Next.js App Router、TypeScript、Node.js、Python、Spring Boot 3、PostgreSQL、MongoDB 与 Redis 高性能缓存。"}, {"title": "深度融入生成式 AI 与 LLM 大模型开发", "desc": "打破传统码农局限。深入掌握 OpenAI / Claude API 调用、Prompt 提示词工程、LangChain 框架、RAG 知识库检索增强与向量数据库实战。"}, {"title": "云原生 DevOps 与生产环境自动化部署", "desc": "实战 Docker 容器化打包、AWS 云端基础设施（EC2, S3, RDS, Lambda）配置，以及基于 GitHub Actions 的自动化 CI/CD 持续集成部署流程。"}, {"title": "一对一技术面试辅导与名企内推", "desc": "名师提供简历技术深度包装、GitHub 代码库规范打磨、LeetCode 高频算法精讲、系统架构设计（System Design）与大多伦多本地科技雇主直推。"}]}, "credentials": {"title": "职业文凭、微证书与实战项目里程碑", "subtitle": "毕业学员将获得安省官方认可的职业大专文凭及极具就业竞争力的项目作品集：", "items": [{"title": "Full Stack Web Technician 职业大专文凭", "desc": "安省教育部注册职业学院颁发的正规职业大专文凭，权威验证全栈软件开发与数据库工程专业能力。"}, {"title": "生成式 AI 智能工程微证书 (AI Mini-Credential)", "desc": "专项认证微证书，证明学员具备大模型 API 集成、RAG 企业知识库构建及 AI 智能应用开发实操能力。"}, {"title": "AWS 云原生与 DevOps 实践认证徽章", "desc": "证明掌握 Docker 容器化、AWS 云服务配置、自动化构建测试与无服务器计算架构运维能力。"}, {"title": "工业级商业 Capstone SaaS 项目作品集", "desc": "在 GitHub 上交付具备完整用户鉴权、支付结算、数据库持久化及 AI 智能问答特性的线上真实运营级 SaaS 平台。"}]}, "curriculum": {"title": "32 周 10 大核心课程模块大纲", "desc": "紧扣北美一线科技大厂与金融机构用人标准的循序渐进实战大纲，助零基础与进阶学员系统蜕变为企业级 AI 全栈工程师："}, "curriculum_modules": [{"num": 1, "title": "计算机底层核心、面向对象编程 (OOP) 与算法数据结构", "hours": "35 学时", "desc": "核心算法、常用数据结构（数组、链表、哈希表、二叉树）、时间与空间复杂度（Big-O）、面向对象设计原则（SOLID）、代码整洁之道与 Git 版本控制规范。"}, {"num": 2, "title": "现代前端基础：HTML5、CSS3 响应式布局与 JavaScript (ES6+) 进阶", "hours": "35 学时", "desc": "语义化 HTML5、Flexbox、CSS Grid、Tailwind CSS、DOM 树操作、ES6+ 核心特性（闭包、原型链、Promise、async/await、模块化）、事件驱动模型与浏览器调试技巧。"}, {"num": 3, "title": "企业级前端工程：TypeScript 与 React 19 核心架构", "hours": "40 学时", "desc": "TypeScript 静态类型系统、接口与泛型；React 19 函数式组件、Custom Hooks 自定义钩子、Context API、Redux Toolkit / Zustand 状态管理与前端性能极致调优。"}, {"num": 4, "title": "Next.js 全栈架构：服务端组件 (RSC)、SSR 与 App Router 路由", "hours": "35 学时", "desc": "Next.js App Router 架构、服务端组件与客户端组件交互、服务端渲染 (SSR)、静态生成 (SSG)、动态路由传参、API Route Handlers 与安全中间件。"}, {"num": 5, "title": "现代后端工程：Node.js、Express 框架与 RESTful 微服务", "hours": "35 学时", "desc": "Node.js 异步非阻塞事件循环机制、Express 中间件架构、RESTful API 行业标准设计、JWT / OAuth2 鉴权与安全防护、限流降级及 Jest 单元测试。"}, {"num": 6, "title": "企业级 Java 后端微服务生态：Spring Boot 3 与 MyBatis", "hours": "35 学时", "desc": "Java 核心进阶、JVM 运行机制、Spring Boot 3 自动装配、依赖注入 (IoC/DI)、Spring MVC 控制层、Spring Security 权限控制与 MyBatis / Hibernate 数据库持久层。"}, {"num": 7, "title": "数据库架构与优化：SQL 关系型、NoSQL 与 Redis 高性能缓存", "hours": "35 学时", "desc": "PostgreSQL 与 MySQL 数据库表设计、复杂 JOIN 查询、索引优化与执行计划分析、MongoDB 文档建模、Prisma ORM 以及 Redis 分布式缓存与消息队列实战。"}, {"num": 8, "title": "AI 智能工程微证书：LLM 大模型、OpenAI API、LangChain 与向量数据库", "hours": "40 学时", "desc": "OpenAI / Claude API 深度集成、Prompt 提示词工程进阶、LangChain / LlamaIndex 编排、RAG 检索增强企业知识库、Embeddings 向量嵌入与 Pinecone/ChromaDB 向量搜索。"}, {"num": 9, "title": "云原生基础设施：Docker 容器化、AWS 云部署与 CI/CD 自动化流水线", "hours": "30 学时", "desc": "多服务 Dockerfile 与 Docker Compose 容器编排、AWS 核心云服务（EC2, S3, RDS, Lambda）、Vercel 云端部署、GitHub Actions 自动化构建与环境变量安全配置。"}, {"num": 10, "title": "毕业大项目 Capstone：工业级 AI 赋能 SaaS 云平台与名企面试冲刺", "hours": "40 学时", "desc": "团队敏捷协作交付具备 AI 智能特性的工业级全栈云平台；系统架构设计（高并发、分布式、负载均衡）、LeetCode 经典大厂算法真题精讲与一对一模拟面试。"}], "practicum": {"title": "企业级全真实训机房与商业 Capstone 毕业大项目", "desc": "学员按敏捷敏捷开发团队（Scrum Team）编制，在加国名企资深架构师带领下，全程使用 Jira、GitHub 进行企业级规范的代码提交、Code Review、CI/CD 部署与自动化测试，亲手打造可写进简历的高含金量真实商业作品集。", "box_title": "大多伦多地区科技名企对口内推与校友合作网络", "box_desc": "维多利亚学院 IT 毕业生在加国各大银行（RBC, TD, BMO, CIBC, Scotiabank）、金融科技、医疗健康与知名科技公司广泛任职，毕业 3–6 个月内积极就业率超 90%！"}, "admissions": {"title": "入学报读条件与适合人群", "items": ["具备安大略省高中毕业文凭（OSSD / 12年级）或加国及海外同等学历评估认证。", "成熟学生通道：年满 18 周岁，并通过学院入学基础能力测评（校区/线上免费测评）。", "零基础转行人员：理工科毕业生、文商科转行 IT 人士（课程包含保姆级编程入门引导模块）。", "在职技术提升人员：已有传统开发经验，希望迅速掌握 React、Next.js、AWS 云计算与 Generative AI 大模型落地的 IT 从业者。", "具备基本的计算机操作习惯与逻辑思维能力，具有较强的学习意愿。"]}, "grants": {"badge": "安省政府培训资助", "title": "申请最高 $28,000+ 政府全额助学金", "description": "全栈软件工程开发与 AI 微证书大专文凭班完全符合安省 Better Jobs Ontario（原第二职业 Second Career）政府培训资助计划。符合条件的安省居民（失业、裁员、领过 EI、自雇、零工人员或低收入群体）最高可申请 $28,000+ 加币全额无偿补贴，100% 覆盖学费、电脑设备费、书本教材费及学习期间基本生活津贴。", "amount": "$28,000+", "button_text": "立即免费评估资助资格"}, "snapshot": {"delivery": "混成教学（线上高清直播 + 校区实操机房）", "practicum": "企业级 Capstone 大项目 + GitHub 真实仓库", "locations": "万锦主校区 / 在线名师直播", "hotline": "416-665-6668"}, "faqs": [{"q": "零基础或者没有计算机背景可以学会吗？", "a": "完全可以！我们的课程体系经过 20 余年持续迭代，从零基础编程底层逻辑（变量、循环、数据结构）讲起，循序渐进过渡到微服务与 AI 大模型应用。课程配备助教答疑、代码逐行审查与丰富随堂练习，确保零基础学员扎实吸收。"}, {"q": "课程中的 AI 微证书（AI Mini-Credential）包含哪些核心内容？", "a": "AI 微证书涵盖当前最前沿的生成式 AI 实战技术：OpenAI / Claude API 调用、Prompt 提示词工程进阶、LangChain 框架、RAG 企业私有知识库检索增强与向量数据库应用。学员将亲手打造具备语义搜索、智能问答与自动化工作流的 AI 智能 Web 应用。"}, {"q": "课程会教授哪些主流开发语言和框架？", "a": "涵盖当前北美招聘市场需求最大的全家桶：HTML5、CSS3、Tailwind CSS、JavaScript (ES6+)、TypeScript、React 19、Next.js、Node.js、Express、Java、Spring Boot 3、PostgreSQL、MySQL、MongoDB、Redis、Docker、AWS 云服务及 Git/GitHub。"}, {"q": "我可以申请政府全额学费资助吗？", "a": "可以！维多利亚学院为安省正规注册职业学院，本专业完全符合 Better Jobs Ontario 政府资助计划。失业、被裁员、领过 EI、自雇或低收入人士最高可获 $28,000+ 无需偿还的政府全额资助（包括学费、电脑费与生活费），学院专家免费一对一协助申请。"}, {"q": "毕业后学校如何辅导就业？", "a": "学院提供全方位的 IT 就业辅导体系：一对一简历深度技术包装、GitHub 代码库规范打磨、LeetCode 高频算法真题精讲、系统设计与全真大厂模拟技术面试，并向大多伦多本地合作雇主库直接内推。"}, {"q": "上课时间如何安排？有录播可以复习吗？", "a": "我们提供全日制脱产班及业余晚间/周末班等多种灵活班型。所有线上直播课程均支持高清录播无限次回放，并配套全天候线上协作机房与校区导师面授答疑。"}]}');
