INSERT INTO "site_translations" VALUES(1,'aid_badge','financial_aid','Government Assistance','政府培训资助','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(2,'aid_card1_desc','financial_aid','Government grant program providing laid-off workers, gig workers, and low-income individuals funding for tuition, books, transportation, and basic living support.','安省政府面向失业人士、零工人员（Gig Workers）及低收入居民设立的重返职场培训补助，全额涵盖学费、教材、交通及日常家庭生活津贴。','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(3,'aid_card1_title','financial_aid','Better Jobs Ontario (Second Career)','安省 Better Jobs Ontario 资助','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(4,'aid_card2_desc','financial_aid','Our experienced educational counselors guide you through eligibility assessment, resume preparation, research documentation, and submission step-by-step.','维多利亚资深教育规划师为您提供资格评估、市场调研报告准备、申请文书整理及面试辅导，确保高成功率获批。','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(5,'aid_card2_title','financial_aid','100% Free Application Assistance','100% 免费申请全程辅导','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(6,'aid_card3_desc','financial_aid','Interest-free monthly installment plans and institutional scholarships available for students not eligible for government grants.','针对未申请政府资助的自费学员，学院提供免息月度分期付款计划及专项优秀学员奖学金支持。','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(7,'aid_card3_title','financial_aid','Flexible Payment & Institutional Aid','灵活分期与学院奖学金','2026-09-25T20:50:06.150592');
