INSERT INTO "site_translations" VALUES(87,'lead_point1','leadership','Over 22 years of dedicated leadership in Canadian higher education & career coaching.','深耕加拿大职业教育与职业规划培训逾22年，业界声誉卓著。','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(88,'lead_point2','leadership','Chief Secretary of Canadian Youth Union & Canadian Women''s Service Centre.','兼任加拿大青年联合会秘书长、加拿大华人妇女联合会理事长。','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(89,'lead_point3','leadership','Helped tens of thousands of new immigrants land professional careers and adapt to Canadian life.','累计帮助数以万计的新老移民与毕业生成功跨入加国专业领域高薪白领阶层。','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(90,'lead_point4','leadership','A proud mother who successfully guided her daughter to Harvard University.','一位培养女儿成功考入美国哈佛大学的卓越母亲与教育名师。','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(91,'lead_quote','leadership','“Our mission is not just granting diplomas, but opening genuine career doors, building confidence, and securing high-paying futures for every student.”','“我们的宗旨绝不仅仅是发出一张文凭，而是为每一位学员真正推开高薪职场大门，重塑自信，赢在加拿大！”','2026-09-25T20:50:06.150592');
