INSERT INTO "site_translations" VALUES(138,'prog_psw_desc','programs','The Personal Support Worker Certificate Program includes classroom lectures, lab simulation, and real-world practicum in long-term care facilities and home care.','包含理论教学与正规医院/养老院临床实习。毕业可同时获得安省认可 NACC PSW 文凭及 CPR 急救证书，职场认可度高，待遇优厚。','2026-09-25T20:50:06.150592');
