INSERT INTO "site_translations" VALUES(142,'prog_psw_f3','programs','Competitive compensation, full benefits, and abundant full-time healthcare job openings','行业薪酬待遇优厚，享工会全套福利，医院与养老院全职岗位紧缺','2026-09-25T20:50:06.150592');
