INSERT INTO "site_translations" VALUES(159,'test_1_author','testimonials','Ms. May','May 女士','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(160,'test_1_prog','testimonials','PSW Certified Graduate','PSW 护工专业优秀毕业生','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(161,'test_1_text','testimonials','“I am a PSW graduate from Victoria International College. The instructors were patient and professional. They not only helped me overcome language barriers, but also secured an excellent practicum placement in a top nursing home. I was hired immediately before graduation!”','“我是维多利亚学院 PSW 护工班的学员。老师们特别有耐心和责任心，不仅帮我克服了英语专业词汇障碍，还帮我联系到一流西人养老院实习，毕业前我就拿到了全职 Offer！”','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(162,'test_2_author','testimonials','Ms. Huang','Huang 同学','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(163,'test_2_prog','testimonials','Full Stack Web Graduate','全栈开发专业毕业生','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(164,'test_2_text','testimonials','“I transitioned from having zero coding knowledge to working as a software data specialist in Montreal. The teachers structured the Full Stack curriculum with real-world enterprise projects that impressed my hiring manager. Truly life-changing!”','“我原本零IT基础，通过维多利亚全栈开发课程系统学习，导师带着做商业真实项目，结业后成功斩获蒙特利尔软件数据分析师职位，雇主对我的技术实力非常认可。”','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(165,'test_3_author','testimonials','Mr. Luo','Luo 先生','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(166,'test_3_prog','testimonials','Better Jobs Ontario Recipient','政府第二职业资助获批学员','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(167,'test_3_text','testimonials','“Thanks to VIC’s dedicated advisors, I successfully secured Second Career government funding covering all my tuition and living costs. The staff handled all my application paperwork seamlessly. I could focus 100% on learning.”','“在维多利亚老师的专业协助下，我顺利拿到了政府 Second Career 全额资助，学费生活费全免！老师们帮我精心准备了全部评估材料，省去了我大量摸索时间，非常感恩！”','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(168,'test_4_author','testimonials','Jennifer L.','Jennifer','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(169,'test_4_prog','testimonials','Accounting & Tax Graduate','会计与税务专业毕业生','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(170,'test_4_text','testimonials','“What sets Victoria College apart is their genuine dedication to job placement. Before I even completed the program, they coordinated resume workshops, mock interviews, and sent my profile to hiring partners. I landed my accounting role in 3 weeks.”','“维多利亚最突出的特色就是切实解决学员就业问题。快毕业时学院就业老师就开始为我改简历、模拟面试并推荐岗位，让我在面试 HR 时充满底气，三周内就入职了会计岗位。”','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(171,'test_badge','testimonials','Student Reviews','学子心声','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(172,'test_subtitle','testimonials','Real stories from students who transformed their careers and lives at Victoria College.','他们在这里重塑技能、获得资助、顺利跨入心仪职业大门。','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(173,'test_title','testimonials','What Our Graduates Say','听听维多利亚毕业生的成功故事','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(174,'topbar_address','header','7050 Woodbine Ave., Unit 300, Markham, ON L3R 4G8','7050 Woodbine Ave., Unit 300, Markham, ON L3R 4G8','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(175,'topbar_call','header','Call Us: 416-665-6668','咨询热线: 416-665-6668','2026-09-26T03:38:51.929585');
