INSERT INTO "site_translations" VALUES(178,'why_1_desc','value_props','Full assistance in applying for Better Jobs Ontario (Second Career) and government training grants up to $28,000+ without spending your own money.','专业顾问全程一对一协助申请安省 Better Jobs Ontario（第二职业）培训补贴，最高可得 $28,000+ 学费及生活补贴，免掏个人积蓄。','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(179,'why_1_title','value_props','Complimentary Grant Guidance','全免费政府助学金申请辅导','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(180,'why_2_desc','value_props','Curriculum designed with industry leaders, offering 1-on-1 practical training and recognized certifications that employers prioritize.','课程紧扣加拿大主流紧缺行业标准，结合 1对1 动手实验与正规职业资格证书，确保毕业生具备即战力。','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(181,'why_2_title','value_props','High-Demand Practical Skills','紧贴市场需求与认证技能','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(182,'why_3_desc','value_props','Exclusive cooperative placement partnerships, resume polishing, interview coaching, and direct employer referral for high job success.','拥有广泛的西人与华人企业合作资源，提供简历深度修改、面试模拟，直推合作雇主，实现快速就业。','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(183,'why_3_title','value_props','Internship & Career Placement','保障实习与雇主就业推荐','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(184,'why_subtitle','value_props','We combine government funding assistance, industry-certified curriculum, and dedicated job placement support.','全方位结合政府资助申请辅导、名师实战教学、及强大的本地雇主直推网络。','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(185,'why_title','value_props','Why Choose Victoria International College?','为什么选择维多利亚职业学院？','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(186,'cat_trades_desc','hero','309A / 442A certified electrician exam preparation, hands-on wiring labs & job referrals.','安省 309A / 442A 建筑与维护电工考证培训，大师级名师亲授、实操机房与学徒推荐。','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(187,'cat_trades_title','hero','Skilled Trades','建筑电工类','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(188,'psw_adm_1','general','Ontario Secondary School Diploma (OSSD / Grade 12) or Canadian / International equivalent evaluation.','安省高中毕业文凭（OSSD / 12年级）或加拿大及海外同等学历认证。','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(189,'psw_adm_2','general','<strong>Mature Student Status:</strong> 18 years of age or older with passing score on the Wonderlic Scholastic Level Exam (administered free on campus).','<strong>成年学生通道（Mature Student）：</strong>年满 18 周岁，并通过校区免费提供的 Wonderlic 基础水平测试。','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(190,'psw_adm_3','general','Clear Vulnerable Sector Police Check (VSS).','无犯罪记录证明（弱势群体排查 VSS）。','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(191,'psw_adm_4','general','Standard Medical & Immunization Clearance Form (TB 2-step test, Hepatitis B, Influenza, COVID-19).','符合标准的体检与疫苗接种证明（结核皮试、乙肝、流感、COVID-19）。','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(192,'psw_adm_5','general','Proficiency in English communication.','具备基础英语沟通与理解能力。','2026-09-25T20:50:06.150592');
