INSERT INTO "site_translations" VALUES(198,'psw_c1_desc','general','National Association of Career Colleges certified credential recognized nationwide across Canadian healthcare employers.','加拿大全国职业学院协会（NACC）认证文凭，全加拿大医疗行业通用认可。','2026-09-25T20:50:06.150592');
