INSERT INTO "site_translations" VALUES(200,'psw_c2_desc','general','Certified CPR/AED life support training required for all healthcare and long-term care clinical settings.','安省所有医院、长者院及医疗机构上岗必备的红十字会急救与心肺复苏认证。','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(201,'psw_c2_title','general','Standard First Aid & CPR Level C','标准急救与 CPR Level C 证书','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(202,'psw_c3_desc','general','Gentle Persuasive Approaches (GPA) certification for managing responsive behaviors in seniors with dementia.','权威温和劝导疗法（GPA）认证，专门针对阿尔茨海默病及失智症长者的行为护理。','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(203,'psw_c3_title','general','GPA Dementia Care Certificate','GPA 失智症护理专业证书','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(204,'psw_c4_desc','general','Over 310 hours of hands-on placement in accredited Ontario nursing homes and community care agencies.','完成 310+ 小时在安省正规长期护理院及社区护理机构的带教临床实习。','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(205,'psw_c4_title','general','Guaranteed Clinical Practicum','100% 保证临床实地实习','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(206,'psw_cred_desc','general','Upon successful completion of the course and national examination, graduates receive official industry-recognized credentials:','顺利完成课程并通过国家标准统考后，毕业生将获得加拿大医疗卫生行业高度认可的权威资质：','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(207,'psw_cred_title','general','Credentials & Certifications Awarded','毕业颁发权威职业文凭与认证证书','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(208,'psw_curr_desc','general','Our comprehensive curriculum covers all 15 core vocational modules mandated by the National Association of Career Colleges (NACC) and Ontario Ministry guidelines:','全面覆盖加拿大职业学院协会（NACC）与安省教育部大纲规定的 15 门职业核心课程：','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(209,'psw_curr_title','general','Official NACC Curriculum Modules (15 Subjects)','官方 NACC 教学大纲（15 门专业核心科目）','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(210,'psw_faq_a1','general','Yes! Eligible candidates (unemployed, laid-off, former EI recipients, self-employed, gig workers, or low-income PR/Citizens) can qualify for up to <strong>$28,000+</strong> in non-repayable government grants covering 100% of tuition, books, transportation, and living allowance. Our advisors assist you throughout the entire application process free of charge.','完全可以！符合条件的申请人（失业、被裁员、曾领 EI、自雇、零工人员或低收入的加拿大永久居民/公民）最高可获批 <strong>$28,000+</strong> 无需偿还的政府全额培训补助金，涵盖 100% 学费、教材费、交通补贴及家庭生活津贴。学院资深顾问全程免费协助申请！','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(211,'psw_faq_a2','general','The program takes <strong>23 weeks</strong> to complete (including online theory, hands-on lab training, and guaranteed clinical practicum).','PSW 护工课程学制为 <strong>23 周</strong>，包含线上理论教学、模拟实验室实操及 310+ 小时实地临床实习。','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(212,'psw_faq_a3','general','No! Our dedicated clinical placement coordinators handle the entire placement process and assign you to one of our accredited partner long-term care facilities and community health organizations across the GTA.','无需自己寻找！维多利亚学院拥有专属的实习协调团队，100% 为学员统一安排在大多伦多地区官方合作认证的公立/私立长期护理院及社区医疗机构。','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(213,'psw_faq_a4','general','PSWs in Ontario enjoy <strong>competitive industry compensation</strong>, along with government retention wage enhancements, shift premiums, overtime opportunities, and comprehensive employee benefits in unionized hospitals and long-term care homes.','安省持证 PSW 享受<strong>极具竞争力的行业薪资待遇</strong>，另享有安省政府留任津贴（Wage Enhancement）、加班补贴以及公立养老院和医院的工会全套医疗与退休金福利，发展前景广阔。','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(214,'psw_faq_q1','general','Can I get government funding (Better Jobs Ontario) to cover my tuition?','我可以通过政府培训资助（Better Jobs Ontario / Second Career）免费就读吗？','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(215,'psw_faq_q2','general','How long does the PSW course take to complete?','完成 PSW 课程通常需要多长时间？','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(216,'psw_faq_q3','general','Do I need to find my own clinical placement?','我需要自己寻找实习机构或长者院吗？','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(217,'psw_faq_q4','general','What are the career and compensation prospects for PSWs in Ontario?','安省 PSW 护工的就业前景与薪酬福利如何？','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(218,'psw_faq_title','general','Frequently Asked Questions','常见问题解答 (FAQ)','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(219,'psw_form_desc','general','Reserve your spot or request grant evaluation. An advisor will contact you within 24 hours.','锁定最新开班名额或申请政府学费评估，专业顾问将在 24 小时内与您联系。','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(220,'psw_form_email_lbl','general','Email Address *','电子邮箱 *','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(221,'psw_form_email_ph','general','name@example.com','例如：name@example.com','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(222,'psw_form_grant_check','general','Evaluate for Better Jobs Ontario Grant','评估 Better Jobs Ontario 政府补助金资格','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(223,'psw_form_name_lbl','general','Your Full Name *','您的姓名 *','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(224,'psw_form_name_ph','general','e.g. John Smith','例如：王小明','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(225,'psw_form_phone_lbl','general','Phone Number *','联系电话 *','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(226,'psw_form_phone_ph','general','416-665-6668','例如：416-665-6668','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(227,'psw_form_submit','general','Submit Application','提交申请与咨询','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(228,'psw_form_success','general','<strong>Thank You!</strong> Your request has been submitted. Our admissions advisor will reach out shortly.','<strong>感谢您的咨询！</strong> 表单已成功提交，我们的招生顾问将尽快与您取得联系。','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(229,'psw_form_title','general','Apply / Book Consultation','立即申请 / 预约专业咨询','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(230,'psw_hero_badge','general','Accredited Career Diploma • NACC PSW DE 2022','安省教育部认证职业文凭 • NACC PSW DE 2022','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(231,'psw_hero_cta_curriculum','general','View Curriculum','查看完整教学大纲','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(232,'psw_hero_cta_grant','general','Book Free Grant Assessment','免费预约政府补助评估','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(233,'psw_hero_lead','general','Transform lives with a fulfilling healthcare career. The NACC Personal Support Worker (PSW DE 2022) Certificate Program consists of intensive online theory, hands-on clinical lab simulations, and guaranteed clinical practicum placements in top Ontario nursing homes and long-term care facilities.','投身紧缺崇高的医疗护理事业。NACC 个人护理护工（PSW DE 2022）专业文凭课程包含线上互动理论教学、校区医院仿真模拟实操以及 100% 保证安排的公立长者护理院和社区医疗机构带教临床实习。','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(234,'psw_hero_title','general','Become a Compassionate & Skilled Caregiver with our Online & Hybrid PSW Program','报读安省官方 NACC 护工文凭课程，开启高薪稳定的加拿大医疗护理职业生涯','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(235,'psw_m1','general','<strong>PSW Foundations:</strong> Role, responsibilities, scope of practice, legal boundaries & healthcare ethics.','<strong>PSW 基础通论：</strong>角色职责、工作范围、法律规范与职业道德准则。','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(236,'psw_m10','general','<strong>Assisting with Medications:</strong> Pharmacological routes, medication reminders, blister packs & error reporting.','<strong>药物协助管理：</strong>给药途径认知、服药提醒、药盒管理与差错防范上报。','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(237,'psw_m11','general','<strong>Cognitive & Mental Health Issues:</strong> Alzheimer''s disease, dementia care, depression, delirium & acquired brain injuries.','<strong>认知与心理健康护理：</strong>阿尔茨海默病、失智症护理、抑郁症、谵妄与脑损伤照护。','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(238,'psw_m12','general','<strong>Common Health Conditions:</strong> Diabetes, cardiovascular diseases, stroke, respiratory conditions, arthritis & cancer care.','<strong>常见健康疾病照护：</strong>糖尿病、心血管疾病、中风后遗症、呼吸系统疾病、关节炎与癌症照护。','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(239,'psw_m13','general','<strong>Gentle Persuasive Approaches (GPA):</strong> Evidence-based dementia de-escalation techniques & patient-centered behavioral care.','<strong>温和劝导疗法 (GPA)：</strong>失智症情绪疏导技巧与以患者为中心的行为应对。','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(240,'psw_m14','general','<strong>Clinical Placement (Facility - 200+ Hours):</strong> Supervised on-site practicum in accredited Ontario Long-Term Care (LTC) nursing homes.','<strong>长者院临床实习（机构 - 200+小时）：</strong>在安省认证长期护理院（LTC）进行带教实战。','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(241,'psw_m15','general','<strong>Clinical Placement (Community - 110+ Hours):</strong> Hands-on in-home patient support with community healthcare agencies.','<strong>社区上门实习（社区 - 110+小时）：</strong>跟随社区医疗机构进行上门长者与病患照护。','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(242,'psw_m2','general','<strong>Safety and Mobility:</strong> Body mechanics, ergonomics, patient transfer techniques, infection control & WHMIS.','<strong>安全与行动协助：</strong>人体力学、病患安全搬移技巧、感染控制与 WHMIS 危险品安全。','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(243,'psw_m3','general','<strong>Body Systems & Anatomy:</strong> Comprehensive overview of human anatomy, physiology, aging processes & vital signs.','<strong>人体系统与解剖：</strong>人体各大生理系统结构、老化生理过程与生命体征测量。','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(244,'psw_m4','general','<strong>Assisting with Personal Hygiene:</strong> Bed baths, oral hygiene, skin integrity prevention, grooming & dignity care.','<strong>个人卫生护理：</strong>床上擦浴、口腔护理、压疮防范、仪容修饰与尊严护理。','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(245,'psw_m5','general','<strong>Abuse and Neglect:</strong> Identification, institutional abuse reporting protocols & client rights advocacy.','<strong>虐待与忽视防范：</strong>识别迹象、法定上报流程与长者权益保护。','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(246,'psw_m6','general','<strong>Household Management, Nutrition & Hydration:</strong> Meal planning, special dietary requirements, therapeutic diets & feeding assistance.','<strong>家政管理、营养与补水：</strong>餐食规划、特殊治疗饮食调配与辅助进食。','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(247,'psw_m7','general','<strong>Care Planning & Documentation:</strong> Restorative care goals, electronic health documentation (EHR) & reporting to RNs/RPNs.','<strong>护理计划与文书记录：</strong>康复护理目标制定、电子医疗记录 (EHR) 及向注册护士汇报。','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(248,'psw_m8','general','<strong>Assisting the Family / Growth & Development:</strong> Family dynamics, child development, supportive care across the lifespan.','<strong>家庭协助与成长发育：</strong>家庭人际互动、儿童发育心理与全生命周期关怀。','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(249,'psw_m9','general','<strong>Assisting the Dying Person:</strong> Palliative care, end-of-life comfort, hospice support & bereavement protocols.','<strong>临终关怀护理：</strong>姑息治疗、临终身心舒适护理、安宁疗护与家属哀伤辅导。','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(250,'psw_page_title','general','Online PSW Course • NACC Personal Support Worker DE 2022 | Victoria International College','线上 PSW 护工课程 • NACC 个人护理专业文凭 | 维多利亚国际职业教育学院','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(251,'psw_pillar_1_desc','general','PSWs are in extreme high demand across Ontario hospitals, long-term care homes (LTC), retirement residences, and home healthcare agencies, ensuring rapid job placement upon graduation.','大多伦多及安省各大公立医院、长期护理院（LTC）、长者公寓及上门护理机构急缺持证护理人员，毕业即上岗，就业率遥遥领先。','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(252,'psw_pillar_1_title','general','Abundant Job Opportunities','就业机会充裕，需求极为迫切','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(253,'psw_pillar_2_desc','general','Make a genuine difference every day by providing compassionate, dignified physical and emotional care that directly enhances the independence and quality of life for seniors and patients.','在日常工作中给予长者和病患无微不至的关怀与身心照料，提升其生活质量与尊严，收获来自家庭与社会的真诚感激与尊重。','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(254,'psw_pillar_2_title','general','Personal Fulfillment','充满温情与成就感的关爱事业','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(255,'psw_pillar_3_desc','general','Earn competitive compensation with opportunities for shift premiums, overtime, union benefits, comprehensive dental/medical plans, and paid vacation time.','享受优厚薪资与发展空间，并可享受政府长期留任津贴、加班费、工会福利、全面的牙医医疗保险及带薪年假。','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(256,'psw_pillar_3_title','general','Competitive Compensation','优渥起薪、工会保障与福利待遇','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(257,'psw_pillar_4_desc','general','Study live interactive theory online from home, paired with hands-on practice in our fully equipped on-campus hospital simulation lab in Markham Campus.','支持在家参加线上直播互动理论课，配合万锦主校区标准医院仿真实验室实操演练，学习与兼顾家庭两不误。','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(258,'psw_pillar_4_title','general','Flexible Hybrid Learning','灵活高效的混合制教学安排','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(259,'psw_prac_box_desc','general','Over <strong>85%</strong> of our graduates receive permanent job offers directly from their clinical placement facility before graduation!','维多利亚学院超过 <strong>85%</strong> 的毕业生在实习结束前即获得实习所在长者院或医疗机构的正式带薪工作录用！','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(260,'psw_prac_box_title','general','Direct Hire from Practicum','实习基地直接签约录用','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(261,'psw_prac_desc','general','Victoria International College coordinates 100% of your clinical placements. You will gain real-world experience under the direct mentorship of Registered Nurses (RNs) and Registered Practical Nurses (RPNs).','维多利亚国际学院全权协调并 100% 落实每位学员的实习名额。在注册护士（RN）和注册实用护士（RPN）的专业带教指导下积累宝贵临床经验。','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(262,'psw_prac_title','general','Hands-on Clinical Practicum Placement','实地临床实习安排与直聘保障','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(263,'psw_side_c_lbl','general','Credential:','文凭认证：','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(264,'psw_side_c_val','general','NACC Career Certificate','NACC 官方护工职业文凭','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(265,'psw_side_d_lbl','general','Duration:','学制时长：','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(266,'psw_side_d_val','general','23 Weeks','23 周','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(267,'psw_side_del_lbl','general','Delivery:','授课模式：','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(268,'psw_side_del_val','general','Hybrid (Online + Lab)','混合制（网课+实操）','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(269,'psw_side_grant_badge','general','GOVERNMENT GRANTS','政府全额资助','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(270,'psw_side_grant_btn','general','Check Eligibility Now','立即测试申请资格','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(271,'psw_side_grant_desc','general','Study PSW with zero out-of-pocket tuition. Book a 100% free eligibility assessment with our funding specialists today.','零学费负担就读 PSW 黄金专业。立即预约专家一对一免费评估您的资助申请资格。','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(272,'psw_side_grant_title','general','Get Up to $28,000+ Grant','最高可获 $28,000+ 补助金','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(273,'psw_side_hot_lbl','general','Hotline:','咨询热线：','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(274,'psw_side_loc_lbl','general','Locations:','校区地点：','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(275,'psw_side_loc_val','general','Markham Main Campus / Live Online','万锦主校区 / 在线直播','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(276,'psw_side_p_lbl','general','Practicum:','临床实习：','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(277,'psw_side_p_val','general','310+ Hours (Guaranteed)','310+ 小时（100%保证）','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(278,'psw_side_snap_title','general','Program Snapshot','专业概览速查','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(279,'psw_stat_1_lbl','general','Hybrid Theory + Lab + 310+ Hrs Practicum','线上理论 + 线下实操 + 310+小时实习','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(280,'psw_stat_1_val','general','23 Weeks','23 周','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(281,'psw_stat_2_lbl','general','Competitive Compensation & Job Security across GTA','优厚薪资待遇、工会保障与全面福利','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(282,'psw_stat_2_val','general','High Demand','长期紧缺','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(283,'psw_stat_3_lbl','general','Direct LTC Nursing Home Clinical Placement','对口公立长者护理中心与社区机构实习','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(284,'psw_stat_3_val','general','High Placement Rate','高就业与实习率','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(285,'psw_stat_4_lbl','general','Second Career / Better Jobs Ontario Eligible','安省政府培训津贴，学费生活费全包','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(286,'psw_stat_4_val','general','$28,000+ Grant','$28,000+ 补助金','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(287,'psw_why_desc','general','Personal Support Workers (PSWs) are among the most essential and respected healthcare professionals in Canada. With Ontario''s rapidly aging population and growing healthcare infrastructure, certified PSWs enjoy unmatched job security, flexible shifts, and meaningful daily patient impact.','个人护理护工（PSW）是加拿大医疗卫生体系中不可或缺的中坚力量。随着安省人口老龄化加剧以及长期护理政策支持，持证 PSW 享有极高的就业保障、灵活的轮班时间以及充实的职业尊严。','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(288,'psw_why_title','general','Why Choose a Career as a Personal Support Worker?','为什么选择成为个人护理护工 (PSW)？','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(289,'acc_adm_1','general','Ontario Secondary School Diploma (OSSD / Grade 12) or Canadian / International equivalent evaluation.','安省高中毕业文凭（OSSD / 12年级）或加拿大及海外同等学历认证。','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(290,'acc_adm_2','general','<strong>Mature Student Status:</strong> 18 years of age or older with a passing score on the Wonderlic Scholastic Level Exam (administered free on campus or online).','<strong>成年学生通道（Mature Student）：</strong>年满 18 周岁，并通过校区免费提供的 Wonderlic 基础水平测试。','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(291,'acc_adm_3','general','Basic computer literacy and foundational English communication proficiency.','具备基础计算机操作能力与基础英语沟通理解能力。','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(292,'acc_adm_4','general','Admissions interview with a Victoria College academic advisor.','参加维多利亚学院课程规划师的一对一入学评估与职业规划咨询。','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(293,'acc_adm_title','general','Admission Requirements','入学申请与报名条件','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(294,'acc_bread_business','general','Business & Accounting','会计税务与商业','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(295,'acc_bread_curr','general','Accounting, Tax and Payroll','会计、税务与薪资管理 (Accounting, Tax & Payroll)','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(296,'acc_bread_home','general','Home','首页','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(297,'acc_bread_programs','general','Programs','专业课程','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(298,'acc_c1_desc','general','Ministry-approved vocational diploma recognized by Canadian businesses and accounting firms nationwide.','安省教育部合规备案职业文凭，全加各大企业与会计师事务所通用认可。','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(299,'acc_c1_title','general','Official Accounting, Tax & Payroll Diploma','安省官方会计、税务与薪资管理文凭','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(300,'acc_c2_desc','general','Hands-on proficiency certification across both desktop enterprise and cloud bookkeeping workflows.','熟练掌握加国市场占有率第一的中小企业云端与桌面版账套管理。','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(301,'acc_c2_title','general','QuickBooks & QBO ProAdvisor Ready','QuickBooks / QBO 云端会计实操认证','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(302,'acc_c3_desc','general','Official credential verifying mastery of inventory, multi-currency, job costing, and general ledger operations.','全面掌握进销存、成本核算、多币种核算及企业财务报表编制。','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(303,'acc_c3_title','general','Sage 50 Computerized Accounting Specialist','Sage 50 电算化会计应用专家认证','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(304,'acc_c4_desc','general','Demonstrates mastery of CRA tax withholding, statutory deductions (CPP/EI/WSIB), T4/T4A, and corporate tax returns.','熟练掌握 CRA 工资代扣缴（CPP/EI/WSIB/税金）、T4/T4A 及公司税申报。','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(305,'acc_c4_title','general','Canadian Payroll & Tax Compliance Certificate','加拿大薪资合规与报税实战证书','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(306,'acc_cred_desc','general','Upon successful completion of the course and practical assessments, graduates receive prestigious industry credentials:','顺利完成全部课程与实践考核后，毕业生将获得加国商业财会领域高度认可的权威资质：','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(307,'acc_cred_title','general','Diplomas & Certifications Awarded','毕业颁发权威职业文凭与认证证书','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(308,'acc_curr_desc','general','Our structured curriculum covers all essential competencies required by Canadian employers, from fundamental double-entry bookkeeping to advanced ERP systems and complex corporate taxation:','全面覆盖加拿大职业财会工作必备核心技能，从复式记账法到企业级 ERP 财务系统与公司税实战：','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(309,'acc_curr_title','general','Comprehensive 30-Week Curriculum Modules (10 Core Subjects)','官方教学大纲与课程模块（10 门专业核心科目）','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(310,'acc_faq_a1','general','Yes! All theoretical lectures and software simulations are delivered live online with interactive CPA instructors. Students can participate from home across Ontario while accessing virtual labs and instructor office hours.','完全可以！课程从最基础的复式记账和商业概念讲起，循序渐进，由浅入深，配合大量真实案例手把手带教，零基础学员也能轻松跟上节奏。','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(311,'acc_faq_a2','general','No prior accounting experience is required. The curriculum begins with fundamental bookkeeping and double-entry concepts before progressively advancing to corporate accounting software and Canadian taxation.','可以！所有理论课程与软件操作均采用线上实时互动直播教学，课后提供录播回放与虚拟机实操环境，名师线上答疑。','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(312,'acc_faq_a3','general','You will gain intensive hands-on experience in <strong>QuickBooks Desktop</strong>, <strong>QuickBooks Online (QBO)</strong>, <strong>Sage 50 (Simply Accounting)</strong>, <strong>Sage 300 (ACCPAC)</strong>, <strong>Taxprep / Profile</strong>, and <strong>Advanced Excel for Finance</strong>.','课程涵盖加国企业最常用的财务工具：<strong>QuickBooks 桌面版及云端版 (QBO)</strong>、<strong>Sage 50 (Simply Accounting)</strong>、<strong>Sage 300 (ACCPAC)</strong>、<strong>Taxprep / Profile</strong> 专业报税系统及 <strong>Advanced Excel</strong>。','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(313,'acc_faq_a4','general','Yes! Victoria College''s Accounting, Tax and Payroll program is fully approved for the <strong>Better Jobs Ontario (Second Career)</strong> grant program, providing up to <strong>$28,000+</strong> in non-repayable government funding for eligible applicants.','可以！本专业完全符合安省 <strong>Better Jobs Ontario（原第二职业 Second Career）</strong>资助计划，合资格者最高可获 <strong>$28,000+</strong> 无需偿还的政府全额补贴，学院专家免费协助申请。','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(314,'acc_faq_q1','general','Can I study the Accounting, Tax and Payroll program online?','零基础或没有会计背景可以报名学习吗？','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(315,'acc_faq_q2','general','Do I need a prior background in math or accounting to enroll?','会计课程可以在家线上学习吗？','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(316,'acc_faq_q3','general','What accounting software will I learn in this program?','课程会教授哪些加拿大主流财务软件？','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(317,'acc_faq_q4','general','Are there government grants available for this diploma program?','我可以申请政府全额学费资助吗？','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(318,'acc_faq_title','general','Frequently Asked Questions','常见问题解答 (FAQ)','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(319,'acc_form_desc','general','Reserve your spot or request grant evaluation. An advisor will contact you within 24 hours.','锁定最新开班名额或申请政府学费评估，专业顾问将在 24 小时内与您联系。','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(320,'acc_form_email_lbl','general','Email Address *','电子邮箱 *','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(321,'acc_form_email_ph','general','name@example.com','例如：name@example.com','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(322,'acc_form_grant_check','general','Evaluate for Better Jobs Ontario Grant','评估 Better Jobs Ontario 政府补助金资格','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(323,'acc_form_name_lbl','general','Your Full Name *','您的姓名 *','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(324,'acc_form_name_ph','general','e.g. David Zhang / Sarah Miller','例如：王小明 / 张丽','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(325,'acc_form_phone_lbl','general','Phone Number *','联系电话 *','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(326,'acc_form_phone_ph','general','416-665-6668','例如：416-665-6668','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(327,'acc_form_submit','general','Submit Application','提交申请与咨询','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(328,'acc_form_success','general','<strong>Thank You!</strong> Your request has been submitted. Our admissions advisor will reach out shortly.','<strong>感谢您的咨询！</strong> 表单已成功提交，我们的招生顾问将尽快与您取得联系。','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(329,'acc_form_title','general','Apply / Book Consultation','立即申请 / 预约专业咨询','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(330,'acc_hero_badge','general','Ontario Approved Career Diploma • 30-Week Intensive','安省教育部正规职业文凭 • 30周密集实战班','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(331,'acc_hero_cta_curriculum','general','View Curriculum Modules','查看完整教学大纲','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(332,'acc_hero_cta_grant','general','Book Free Grant Assessment','免费预约政府补助评估','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(333,'acc_hero_lead','general','Fast-track your career as a high-demand corporate bookkeeper, payroll administrator, or tax associate with hands-on training led by veteran Canadian CPAs. Includes QuickBooks, Sage 50, ACCPAC, Profile/TaxPrep, advanced Excel modeling, and direct job placement support.','针对加拿大本土公司日常全流程商业做账、员工工资税核算、CRA 个人与公司税申报进行深度全真演练。熟练掌握 QuickBooks、Sage 50、ACCPAC、Profile/TaxPrep 及高级 Excel 财务建模，享受对口高薪白领就业推荐与最高 $28,000+ 政府全额学费资助。','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(334,'acc_hero_title','general','Master Full-Cycle Canadian Accounting, Tax & Payroll with CPA Mentorship','加国资深 CPA 亲授 • 掌握加拿大全盘会计账务、税务申报与薪资管理','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(335,'acc_m1','general','<strong>Canadian Financial Accounting Principles:</strong> GAAP / ASPE standards, double-entry bookkeeping, general journals, ledgers, trial balance & financial statements.','<strong>加拿大商业会计基础与复式记账原理：</strong>GAAP/ASPE 会计准则、借贷记账法、日记账与总分类账、试算平衡表及三大财务报表编制。','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(336,'acc_m10','general','<strong>Career Coaching & CPA Interview Prep:</strong> Canadian accounting resume workshops, CPA behavioral/technical interview drills & placement assistance.','<strong>财会职业求职规划、简历精修与 CPA 模拟面试：</strong>英文简历一对一精修、技术测试（Excel/会计分录）模拟、行为面试应答技巧及名企定向推荐。','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(337,'acc_m2','general','<strong>QuickBooks Desktop & Online (QBO):</strong> Business setup, chart of accounts, invoicing, bills, inventory, bank feeds & reconciliations.','<strong>QuickBooks 桌面版与 QBO 云端版账套：</strong>企业账套建立、科目表设置、应收/应付管理、发票、账单、库存与银行流水对账。','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(338,'acc_m3','general','<strong>Sage 50 Accounting (Simply Accounting):</strong> Sub-ledgers, job costing, departmental accounting, multi-currency & bank reconciliations.','<strong>Sage 50 财务软件企业级实战应用：</strong>企业进销存业务处理、往来账核算、多币种交易处理、部门/项目成本核算与期末结账。','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(339,'acc_m4','general','<strong>Sage 300 / ACCPAC ERP Accounting:</strong> Enterprise ERP navigation, multi-entity consolidations, GL/AP/AR modules & month-end closing.','<strong>Sage 300 / ACCPAC 中大型企业 ERP 模块：</strong>总账 (GL)、应付 (AP)、应收 (AR) 核心模块操作、跨部门凭证流转及年终关账流程。','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(340,'acc_m5','general','<strong>Canadian Payroll Compliance & Administration:</strong> NPI standards, statutory deductions (CPP, EI, Tax, EHT, WSIB), ROE issuance & T4/T4A filing.','<strong>加拿大薪资法规管理与工资税核算：</strong>NPI 规范、法定扣缴（CPP、EI、税金、WSIB、EHT）、ROE 制作、T4/T4A 汇总及 CRA 申报。','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(341,'acc_m6','general','<strong>Canadian Personal Taxation (T1):</strong> Personal income tax laws, deductions, credits, RRSP optimization & Profile/TaxPrep software filing.','<strong>加拿大个人所得税 (T1) 申报与税务规划：</strong>加国税法体系、雇佣收入、投资、房租、自雇、各项税收抵免、RRSP 及 Profile/TaxPrep 实战。','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(342,'acc_m7','general','<strong>Canadian Corporate Taxation (T2) & GST/HST:</strong> Corporate tax returns, active business income, CCA schedules, GST/HST & CRA audits.','<strong>加拿大公司所得税 (T2) 申报与消费税 (GST/HST)：</strong>公司税基础、主动营业收入计算、固定资产折旧 (CCA)、Schedule 1 及 CRA 审计应对。','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(343,'acc_m8','general','<strong>Advanced Excel for Financial Modeling:</strong> XLOOKUP, INDEX/MATCH, dynamic Pivot Tables, consolidations, variance models & dashboards.','<strong>高级 Excel 财务建模与商业数据分析：</strong>XLOOKUP, INDEX/MATCH, 动态数据透视表 (Pivot Table)、多表合并、预算差异模型与管理层看板。','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(344,'acc_m9','general','<strong>Full-Cycle Accounting Simulation:</strong> Practical cycle simulation for manufacturing, retail & services, adjusting entries & year-end working papers.','<strong>企业全流程真账实操与年终结账底稿：</strong>制造、零售及服务型企业全真实操，独立完成月结、年结调整分录及年终工作底稿 (Working Papers)。','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(345,'acc_page_title','general','Accounting, Tax and Payroll Course • Computerized Accounting Diploma | Victoria International College','会计、税务与薪资管理文凭课程 • 计算机做账实战班 | 维多利亚国际职业教育学院','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(346,'acc_pillar_1_desc','general','Essential business function required across all sectors. Enjoy consistent office/hybrid work hours, permanent positions, and clear career ladders toward Senior Accountant or CPA designation.','各行业常年极度刚需，无需重体力劳动。工作环境舒适稳定，规范双休，职业上升通道顺畅，可晋升高级会计师或报考 CPA。','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(347,'acc_pillar_1_title','general','High Job Stability & Career Growth','就业刚需，环境稳定','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(348,'acc_pillar_2_desc','general','Work on authentic full-cycle Canadian accounting sets, payroll reconciliations, and complex corporate/personal tax returns rather than mere abstract theory.','摒弃纯死记硬背理论，全程使用加拿大中小型企业真实账目、员工工资单及税表进行全流程模拟，毕业即具备 2-3 年本地实际工作经验。','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(349,'acc_pillar_2_title','general','100% Real-World Case Studies','100% 本地真账案例实操','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(350,'acc_pillar_3_desc','general','Master industry-standard tools employers mandate: QuickBooks (Desktop & Online), Sage 50 (Simply Accounting), Sage 300 / ACCPAC ERP, Taxprep/Profile, and Financial Excel.','全面攻克加国雇主必备主流软件：QuickBooks 桌面/云端版、Sage 50、Sage 300/ACCPAC、Profile/TaxPrep 专业报税系统及高级 Excel 建模。','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(351,'acc_pillar_3_title','general','Comprehensive Software Mastery','主流商业财务软件全精通','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(352,'acc_pillar_4_desc','general','1-on-1 resume optimization, Canadian accounting interview simulation, LinkedIn networking, and direct employer hiring referrals from our recruitment network.','专业修改加拿大标准财会英文简历、名师一对一模拟中英文专业面试与技术测试、精准内推至合作会计师事务所及企业财务部门。','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(353,'acc_pillar_4_title','general','Full CPA Mentorship & Placement','CPA 导师一对一求职辅导','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(354,'acc_prac_box_desc','general','Over <strong>90%</strong> of our active graduates secure full-time accounting, bookkeeping, or payroll roles within 3 to 6 months of graduation!','维多利亚学院超过 <strong>90%</strong> 的积极求职学员在毕业后 3 至 6 个月内成功入职加国企业财务部或知名会计师事务所！','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(355,'acc_prac_box_title','general','Direct Career Placement Assistance','对口就业直通与内推推荐','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(356,'acc_prac_desc','general','Victoria International College provides extensive hands-on laboratory simulation. Students work with live corporate accounting data sets and real-world tax scenarios under the guidance of practicing CPAs.','维多利亚职业学院配备先进仿真财务实验室，学员在资深持牌会计师的指导下直接上手真实商业公司账目与复杂税务案例，迅速将理论转化为实操战斗力。','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(357,'acc_prac_title','general','Hands-on Software Labs & Year-End Simulation','名师真账实训实验室与全真案例模拟','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(358,'acc_side_c_lbl','general','Credential:','文凭认证：','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(359,'acc_side_c_val','general','Accounting & Payroll Diploma','安省官方会计职业文凭','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(360,'acc_side_d_lbl','general','Duration:','学制时长：','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(361,'acc_side_d_val','general','30 Weeks','30 周','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(362,'acc_side_del_lbl','general','Delivery:','授课模式：','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(363,'acc_side_del_val','general','Live Online + Campus Labs','名师直播网课 + 校区实操','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(364,'acc_side_grant_badge','general','GOVERNMENT GRANTS','政府全额资助','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(365,'acc_side_grant_btn','general','Check Eligibility Now','立即测试申请资格','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(366,'acc_side_grant_desc','general','Study Accounting with zero out-of-pocket tuition. Book a 100% free eligibility assessment with our funding specialists today.','零学费负担就读会计、税务与薪资管理黄金专业。立即预约专家一对一免费评估您的资助申请资格。','2026-09-25T20:50:06.150592');
