INSERT INTO "site_translations" VALUES(382,'acc_why_desc','general','Computerized accounting and payroll administration is one of Canada''s most stable, respected, and recession-resilient professions. Every Canadian business, non-profit, and government entity requires certified professionals to manage financial records, CRA tax filings, and payroll compliance.','会计与薪资管理是加拿大各行各业最稳定、最受尊重、且最具抗周期性的白领黄金职业。无论是跨国企业、中小公司、非营利机构还是政府部门，都需要专业财会人员进行合规做账、CRA 报税与工资发放。','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(383,'acc_why_title','general','Why Choose Accounting, Tax and Payroll as Your Canadian Career?','为什么选择会计、税务与薪资管理作为加国职业方向？','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(384,'acu_adm_1','general','Individuals passionate about exploring traditional wellness concepts and natural holistic healing arts.','对传统中医文化、自然疗法及身心养生保健充满浓厚兴趣的广大爱好者。','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(385,'acu_adm_2','general','Anyone seeking personal interest learning, family health empowerment, and complementary self-care techniques.','希望掌握实用经络调理绝活，为自己与家人进行日常健康调护与亚健康调理的人士。','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(386,'acu_adm_3','general','Practicing wellness professionals, registered massage therapists (RMTs), aesthetic/spa specialists, and fitness trainers seeking to deepen their TCM knowledge.','现职注册按摩师（RMT）、美容水疗理疗师、健身教练及康复护理从业人员技能进阶拓展。','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(387,'acu_adm_4','general','No prior medical background required; classes are taught with clear, step-by-step bilingual instruction.','无需任何医学或理工科前置背景，零基础起步，中英双语名师手把手通俗易懂教学。','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(388,'acu_adm_5','general','Applicants must be 18 years of age or older with a commitment to holistic health learning.','年满 18 周岁，热爱中华传统医学文化与健康生活方式。','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(389,'acu_adm_title','general','Who Should Attend & Program Prerequisites','适合人群与报读要求','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(390,'acu_comp_mcu','general','Compliance Statement: This is a non-vocational, MCU-exempt program offered by Victoria International College of Business and Technology. This program does not require approval under the Ontario Career Colleges Act, 2005.','合规声明（Compliance Statement）：本课程为维多利亚学院开设的非职业性、安省高等院校厅（MCU）豁免课程。本课程不属于《2005年安大略省职业学院法》管辖及审批范围。','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(391,'acu_comp_reg','general','Regulatory Notice: This is a non-vocational program offered by Victoria International College of Business and Technology. It is intended for personal or professional development only and does not lead to licensure, certification, or authorization to practise acupuncture in Ontario.','法规提示（Regulatory Notice）：针灸课程属于维多利亚国际商业与技术学院开设的非职业性（Non-Vocational）课程。本课程仅供个人兴趣或专业技能拓展使用，不提供在安省从事针灸执业的执照、认证或执业许可。','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(392,'acu_comp_title','general','Regulatory Notice & Compliance Statement','法规提示与合规声明','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(393,'acu_cred_1_desc','general','Official Certificate of Course Completion in Traditional Acupuncture Foundations & Wellness (2250 Hours).','维多利亚学院官方颁发的 2250 学时中医针灸与传统养生保健基础结业证书。','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(394,'acu_cred_1_title','general','Victoria College Certificate of Completion','维多利亚学院结业证书','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(395,'acu_cred_2_desc','general','Comprehensive training in single-use needle hygiene, sterile protocols, contraindications, and clinic safety.','严格掌握单次使用一次性针灸针具、消毒灭菌规程、操作禁忌及个人防护规范。','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(396,'acu_cred_2_title','general','Clean Needle Technique (CNT) & Safety Record','无菌操作安全与卫生防护合格记录','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(397,'acu_cred_3_desc','general','Practical mastery in moxibustion (Ai Jiu), fire cupping therapy, Gua Sha scraping, and Tuina acupressure.','系统掌握艾灸温灸、玻璃火罐、闪罐走罐、经络刮痧及实用推拿点穴手法要领。','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(398,'acu_cred_3_title','general','Auxiliary Modalities Proficiency Portfolio','传统特色外治法技能掌握','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(399,'acu_cred_4_desc','general','Documented hours of live instructor demonstrations, palpation drills, and simulated case studies.','在专业实训诊室进行穴位按压、循经揣穴、手法演练与真实案例模拟分析。','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(400,'acu_cred_4_title','general','Supervised Clinical Observation & Lab Hours','诊室临床观摩与实操演练档案','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(401,'acu_cred_sub','general','Upon successfully completing the program, graduates receive comprehensive academic and practical documentation:','顺利完成全部理论科目与实训观摩后，学员将获得全面的学术与技能结业档案：','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(402,'acu_cred_title','general','Credentials & Learning Outcomes Awarded','课程学习成果与结业资质','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(403,'acu_curr_desc','general','A rigorous, structured journey through traditional Chinese medicine theory, meridian anatomy, diagnostic arts, and practical healing modalities:','涵盖传统中医哲学、经络腧穴、中医四诊、针灸实操、传统外治法与节气食疗的系统知识体系：','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(404,'acu_curr_title','general','Official 2250-Hour Curriculum Outline (10 Comprehensive Modules)','官方 2250 学时教学大纲（10 门系统核心科目）','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(405,'acu_faq_a1','general','Yes, absolutely! The program is structured from the ground up, starting with core TCM philosophy and intuitive meridian charts before advancing to practical techniques. Instructors guide you step-by-step.','完全可以！课程从中医最基础的阴阳五行和形象直观的经络穴位图解讲起，配合生动生活案例与大量现场实操演示，通俗易懂，手把手带您入门。','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(406,'acu_faq_a2','general','Yes! We offer a full-time Weekday Cohort (Mon–Fri 9am–5pm) and a flexible Weekend/Evening Cohort (Fri 6pm–10pm, Sat/Sun 10am–6:30pm). Live online theory lectures and recorded reviews make it easy for working professionals.','有！我们专门开设了周末及晚间班（周五晚 + 周六周日全天），所有理论课均支持在线直播与课后高清录播无限次回放，兼顾工作与学习毫无压力。','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(407,'acu_faq_a3','general','This is a Non-Vocational Program intended for personal interest, wellness knowledge, and complementary education. Under the Ontario Career Colleges Act, 2005, it is exempt from career college approval and does not lead to licensed acupuncturist registration (R.Ac) with CTCMPAO.','本课程属于非职业性（Non-Vocational）兴趣技能提升课程，不受《2005年安大略省职业学院法》管辖，旨在帮助学员掌握传统健康养生知识，不提供安省中医师及针灸师管理局（CTCMPAO）执业注册资格。','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(408,'acu_faq_a4','general','You will gain hands-on knowledge in clean needle safety protocols, acupoint location, moxibustion (Ai Jiu), glass fire cupping, Gua Sha meridian scraping, Tuina Chinese therapeutic massage, and seasonal TCM dietary therapy.','学员将系统学习针灸穴位经络定位、无痛进针与无菌安全规范、艾灸温灸、玻璃火罐拔罐、经络刮痧、中医推拿点穴手法以及四季节气食疗养生方。','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(409,'acu_faq_q1','general','Is this program suitable for beginners with no prior medical background?','零医学背景的新手可以学会吗？','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(410,'acu_faq_q2','general','What schedule options are available and can I study while working full-time?','平时需要上班，有适合业余时间学习的班型吗？','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(411,'acu_faq_q3','general','What is the regulatory status of this program in Ontario?','这门针灸课程在安省的法规性质是什么？','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(412,'acu_faq_q4','general','What practical skills and auxiliary modalities will I learn?','课程中会学习哪些实用的传统理疗技能？','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(413,'acu_faq_title','general','Frequently Asked Questions','常见问题解答 (FAQ)','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(414,'acu_form_desc','general','Reserve your spot or request program details. An advisor will contact you within 24 hours.','锁定最新开班名额或索取详细课程表与实训安排，专业顾问将在 24 小时内与您联系。','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(415,'acu_form_email_lbl','general','Email Address *','电子邮箱 *','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(416,'acu_form_email_ph','general','name@example.com','例如：name@example.com','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(417,'acu_form_name_lbl','general','Your Full Name *','您的姓名 *','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(418,'acu_form_name_ph','general','e.g. David Zhang / Sarah Miller','例如：王小明 / 张丽','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(419,'acu_form_phone_lbl','general','Phone Number *','联系电话 *','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(420,'acu_form_phone_ph','general','416-665-6668','例如：416-665-6668','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(421,'acu_form_sched_pref','general','Preferred Schedule: Weekend / Evening Cohort','意向学习班型：周末/晚间班（业余兼顾）','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(422,'acu_form_submit','general','Submit Consultation Request','提交咨询与预约','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(423,'acu_form_success','general','<strong>Thank You!</strong> Your request has been submitted. Our admissions advisor will reach out shortly.','<strong>感谢您的咨询！</strong> 表单已成功提交，我们的课程顾问将尽快与您取得联系。','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(424,'acu_form_title','general','Apply / Book Consultation','立即申请 / 预约专业咨询','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(425,'acu_hero_badge','general','NON-VOCATIONAL ENRICHMENT PROGRAM','非职业特色兴趣课程 • 传统中医养生','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(426,'acu_hero_btn_book','general','Book Free Consultation','免费预约课程咨询','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(427,'acu_hero_btn_curr','general','View 2250-Hour Curriculum','查看 2250 学时教学大纲','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(428,'acu_hero_compliance','general','Non-Vocational Program • MCU-Exempt • Ontario Career Colleges Act 2005 Exempt','非职业性兴趣课程 • MCU 豁免 • 不属于安省《2005年职业学院法》管辖','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(429,'acu_hero_lead','general','Discover the foundations of traditional wellness, holistic healthcare, and meridian balance. Designed for individuals seeking personal interest learning, wellness knowledge, or complementary health education.','探索数千年传统中医（TCM）养生智慧与经络调理精髓。本课程专为寻求个人兴趣学习、养生保健知识或自然疗法启蒙的人群设计，提供系统基础理论、经络穴位精确定位与丰富理疗实操演示。','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(430,'acu_hero_title','general','Acupuncture & Traditional Wellness Program','中医针灸与传统养生保健课程','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(431,'acu_m10_d','general','In-clinic observation of master practitioners, palpation drills, safe mock simulation workshops, practical case scenario analysis, and professional ethics.','资深中医师现场实操手法演示、学员相互揣穴演练、经典案例综合辨析、个人卫生规范与职业道德。','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(432,'acu_m10_h','general','250 Hours','250 学时','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(433,'acu_m10_t','general','Supervised Clinical Demonstrations, Case Workshops & Hands-on Labs','诊室实操观摩演示、手法实训与案例研讨','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(434,'acu_m1_d','general','Historical evolution of TCM, Yin-Yang philosophy, Five Elements (Wu Xing) correspondences, Zang-Fu organ systems, Qi, Blood, and Body Fluids physiology.','中医学发展简史、阴阳学说、五行生克乘侮、五脏六腑生理功能与相互关系、气血津液生成与运行。','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(435,'acu_m1_h','general','225 Hours','225 学时','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(436,'acu_m1_t','general','Foundations & Philosophy of Traditional Chinese Medicine (TCM)','中医基础理论与传统医学哲学','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(437,'acu_m2_d','general','Surface anatomy, pathway trajectories of the 12 Regular Meridians, Ren Mai and Du Mai extraordinary vessels, and landmark location of 100+ vital wellness acupoints.','经络系统总论、十二正经循行走向、任督二脉与奇经八脉、100+ 常用保健特效穴位骨度分寸法与精准定位。','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(438,'acu_m2_h','general','250 Hours','250 学时','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(439,'acu_m2_t','general','Meridian Channels & Acupoint Anatomy (14 Main Channels)','经络腧穴学与人体体表解剖','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(440,'acu_m3_d','general','The Four Diagnostic Methods: Inspection (Wang - tongue and complexion), Auscultation/Olfaction (Wen), Inquiry (Wen), and Palpation (Qie - radial pulse diagnosis).','望闻问切四诊方法：舌象观察（舌苔与舌质）、面色神气、问诊要点、脉诊基础触按及八纲辨证原则。','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(441,'acu_m3_h','general','225 Hours','225 学时','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(442,'acu_m3_t','general','TCM Diagnostic Fundamentals & Syndrome Differentiation','中医诊断学基础与四诊八纲辨证','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(443,'acu_m4_d','general','Needle anatomy and selection, single-use sterile filiform needles, insertion angles, depths, de-qi sensations, tonification/sedation, and safety contraindications.','毫针构造与规格选择、进针角度与深度、得气感应、提插捻转补泻手法、安全操作禁忌与防范措施。','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(444,'acu_m4_h','general','225 Hours','225 学时','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(445,'acu_m4_t','general','Acupuncture Needling Techniques & Clean Needle Safety Protocols (CNT)','针灸针刺手法、无菌操作规范与安全常识','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(446,'acu_m5_d','general','Direct and indirect moxibustion (Ai Jiu / moxa roll), fire cupping (glass and bamboo), moving cupping, flash cupping, and Gua Sha meridian scraping protocols.','直接灸与间接温和灸、隔姜/隔盐灸、玻璃火罐拔罐法、闪罐走罐、经络刮痧出痧原理与排湿排寒手法。','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(447,'acu_m5_h','general','200 Hours','200 学时','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(448,'acu_m5_t','general','Traditional Auxiliary Therapies: Moxibustion, Cupping & Gua Sha','传统中医外治特色疗法：艾灸、拔罐与刮痧','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(449,'acu_m6_d','general','Traditional hand techniques (pushing, kneading, grasping, rolling), meridian channel clearing, and acupressure protocols for muscle tension and stiffness.','推拿核心手法（推、拿、按、摩、滚、揉、拍打）、循经点穴、放松肌肉肌腱、舒缓日常酸痛与经络疏通。','2026-09-25T20:50:06.150592');
