INSERT INTO "site_translations" VALUES(451,'acu_m6_t','general','Tuina Chinese Therapeutic Massage & Acupressure for Pain Relief','中医经络推拿点穴手法与筋骨保健','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(452,'acu_m7_d','general','Holistic strategies for digestive harmonization, stress management, sleep quality improvement, vitality enhancement, and seasonal respiratory support.','脾胃消化调理、睡眠质量改善、情绪疏导解压、气血亏虚调补、呼吸系统与季节性不适的整体调理方案。','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(453,'acu_m7_h','general','225 Hours','225 学时','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(454,'acu_m7_t','general','TCM Internal Health & Common Wellness Condition Analysis','中医脏腑调理与常见亚健康状态分析','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(455,'acu_m8_d','general','Acupressure protocols, meridian thermal therapy, and joint mobility enhancement for neck, shoulder, lower back, and knee comfort.','颈椎、肩周、腰肌劳损、膝关节等常见部位的经络循行特点、穴位热敷温灸与手法舒缓综合方案。','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(456,'acu_m8_h','general','225 Hours','225 学时','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(457,'acu_m8_t','general','Musculoskeletal Wellness & Pain Management Techniques','筋骨关节保健与肌肉疼痛舒缓实战','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(458,'acu_m9_d','general','Thermal properties of foods (cold, cool, neutral, warm, hot), five flavors in nutrition, herbal tea formulations, seasonal dietetics, and mindful longevity practices.','食物四气五味属性、九种中医疗效体质辨识、春夏秋冬四季节气养生食谱、养生代茶饮配伍与健康生活方式。','2026-09-25T20:50:06.150592');
