INSERT INTO "site_translations" VALUES(461,'acu_page_title','general','Acupuncture & Traditional Wellness Program | Victoria International College','中医针灸与传统养生保健课程 | 维多利亚职业学院','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(462,'acu_sched_desc','general','We understand our students balance careers, family, and studies. Victoria College provides multiple convenient schedules:','我们充分理解学员兼顾工作、家庭与学习的实际需求，特设多种灵活授课班型：','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(463,'acu_sched_end_desc','general','Specially designed for working professionals and wellness enthusiasts seeking flexible part-time study without quitting their day jobs.','专为在职人士、创业者及家庭养生爱好者量身打造，无需辞职即可利用业余时间修完全部课程。','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(464,'acu_sched_end_time','general','Friday: 6:00 PM – 10:00 PM | Saturday & Sunday: 10:00 AM – 6:30 PM','周五：6:00 PM – 10:00 PM | 周六及周日：10:00 AM – 6:30 PM','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(465,'acu_sched_end_title','general','Weekend & Evening Professional Cohort','周末及晚间业余班（Weekend & Evening Cohort）','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(466,'acu_sched_format','general','Hybrid Delivery: Live interactive online theory lectures combined with in-person weekend practical clinic workshops.','线上理论直播 + 课后高清录播复习 + 线下实训诊室面对面手法演示。','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(467,'acu_sched_title','general','Flexible Schedule Options to Fit Your Life','灵活课时安排（满足多样化学习需求）','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(468,'acu_sched_week_desc','general','Accelerated full-time pace with immersive daily theory lectures and afternoon guided practical demonstrations.','适合时间充裕、希望短时间内系统全面掌握中医针灸与传统养生知识的学员。','2026-09-25T20:50:06.150592');
