INSERT INTO "site_translations" VALUES(482,'acu_side_sched_desc','general','Study traditional acupuncture and wellness without disrupting your full-time job. Contact our admissions team to explore cohort start dates.','兼顾全职工作与家庭生活，无需辞职即可利用业余时间系统掌握中医养生绝活。立即咨询课程顾问了解最新开班档期。','2026-09-25T20:50:06.150592');
