INSERT INTO "site_translations" VALUES(497,'acu_why_1_desc','general','Master foundational Traditional Chinese Medicine concepts: Yin-Yang balance, Five Elements (Wu Xing), Zang-Fu organ systems, Qi, Blood, and Body Fluids.','深入浅出领悟阴阳平衡、五行生克、五脏六腑生克制化与气血津液运行规律，建立宏观辨证的整体健康观。','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(498,'acu_why_1_title','general','Foundations of Ancient TCM Wisdom','传统中医经典理论哲学','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(499,'acu_why_2_desc','general','Gain deep anatomical understanding of the 12 primary meridians, Ren & Du extraordinary vessels, and precise landmark location of 100+ therapeutic acupoints.','系统掌握十二正经与任督二脉的循行路线，精准定位 100+ 常用保健特效穴位与经络气血疏通技巧。','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(500,'acu_why_2_title','general','14 Meridian Channels & Acupoint Anatomy','十四经络循行与特效穴位','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(501,'acu_why_3_desc','general','Empower yourself and your family with natural wellness knowledge, seasonal Yang Sheng lifestyle habits, food energetics, and non-pharmacological health maintenance.','传承中医''治未病''核心精髓，掌握体质辨识、四季节气调摄、食疗药膳配伍及非药物家庭健康管理方法。','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(502,'acu_why_3_title','general','Holistic Health & Preventative Life Cultivation','治未病与节气养生食疗','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(503,'acu_why_4_desc','general','Observe guided clean needle safety demonstrations, filiform needle insertion protocols, moxibustion (Ai Jiu), glass fire cupping, Gua Sha, and Tuina therapeutic massage.','由资深中医师现场演示规范无痛进针手法、艾灸温通经络、玻璃火罐排湿通络、经络刮痧及推拿点穴手法。','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(504,'acu_why_4_title','general','Practical Demonstrations & Multimodality Labs','综合中医传统理疗实操演示','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(505,'acu_why_sub','general','Immerse yourself in centuries of natural healing philosophy, meridian energetics, and hands-on non-invasive modalities for personal well-being.','传承千年华夏医学瑰宝，掌握终身受用的自然防病与身心自我调理实用绝活：','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(506,'acu_why_title','general','Why Choose Our Acupuncture & Traditional Wellness Program?','为什么选择维多利亚中医针灸与传统养生课程？','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(507,'eca_adm_1','general','Ontario Secondary School Diploma (OSSD / Grade 12) or Canadian / International equivalent evaluation.','具备安大略省高中毕业文凭（OSSD / 12年级）或加国/海外同等学历评估认证。','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(508,'eca_adm_2','general','<strong>Mature Student Status:</strong> 18 years of age or older with a passing score on the Wonderlic College Entrance Assessment (administered free on campus or online).','<strong>成熟学生入学通道：</strong>年满 18 周岁，并通过学院 Wonderlic 入学能力测评（校区免费测试）。','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(509,'eca_adm_3','general','Clear Vulnerable Sector Criminal Reference Check (VSC) issued by local police services.','提供合格的警方无犯罪记录弱势群体筛查证明（Vulnerable Sector Check）。','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(510,'eca_adm_4','general','Up-to-date Medical Immunization Record including Two-Step Tuberculosis (TB) skin test.','完成标准医疗体检与疫苗接种记录（包含 2 步骤结核病 TB 皮试）。','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(511,'eca_adm_title','general','Admission Requirements & Prerequisites','入学报读条件与要求','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(512,'eca_cred_1_desc','general','Ontario Ministry-approved vocational diploma recognized by licensed daycare centers, nursery schools, and private educational institutions across Ontario.','安省教育部备案注册职业文凭，全省持牌托儿所、幼儿园及早教机构通用认可。','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(513,'eca_cred_1_title','general','Official Early Childcare Assistant (ECA) Diploma','安省 ECA 幼教助理官方职业文凭','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(514,'eca_cred_2_desc','general','Mandatory provincial certification ensuring readiness to handle pediatric emergencies, choking, CPR, and first aid.','安省日托中心法定必备的婴幼儿心肺复苏与突发意外急救官方认证。','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(515,'eca_cred_2_title','general','Standard First Aid & CPR Level C (Infant & Child)','儿童标准急救与 CPR Level C 证书','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(516,'eca_cred_3_desc','general','Industry-standard certification verifying mastery of safe food handling, allergy prevention, and balanced menu planning in childcare settings.','掌握幼教机构日常配餐卫生、过敏源防范与膳食营养管理专业技能。','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(517,'eca_cred_3_title','general','Food Handler & Pediatric Nutrition Certificate','食品安全与儿童营养卫生证书','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(518,'eca_cred_4_desc','general','Comprehensive hands-on practicum verifying verified Canadian childcare experience across infant, toddler, and preschool age groups.','涵盖婴儿班（Infant）、幼儿班（Toddler）及学前班（Preschool）的全阶段实战经验。','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(519,'eca_cred_4_title','general','Guaranteed 500+ Hours Supervised Field Placement','100% 保障 500+ 小时正规日托实地实习','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(520,'eca_cred_subtitle','general','Upon successful completion of the curriculum and field placement hours, graduates receive prestigious, employer-recognized credentials:','顺利完成全部理论科目与实地实习后，毕业生将获得安省幼教行业权威官方资质：','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(521,'eca_cred_title','general','Diplomas & Certifications Awarded','官方认证毕业文凭与资格证书','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(522,'eca_curr_subtitle','general','Our structured curriculum equips students with the exact competencies mandated by Ontario''s Child Care and Early Years Act (CCEYA) and early learning frameworks:','严格遵循安省《托儿与早期儿童法案》（CCEYA 2014）与官方幼教发展指南（How Does Learning Happen?）精心设计：','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(523,'eca_curr_title','general','Comprehensive 22-Week Curriculum Modules (10 Core Subjects)','官方 22 周教学大纲（10 门专业核心科目）','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(524,'eca_faq_a1','general','Yes! All theoretical lectures and interactive classroom modules are delivered live online with expert early childhood instructors. You will attend flexible online sessions, followed by your guaranteed in-person daycare practicum in your local GTA area.','可以！所有理论课程与互动研讨均采用线上名师实时直播教学，配合课后录播复习，随后由学院为您就近安排当地安省持牌日托中心进行实地跟岗实习。','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(525,'eca_faq_a2','general','The program is 22 weeks in total, combining comprehensive theoretical foundations, creative workshop labs, and 500+ hours of hands-on field practicum in licensed Ontario daycare centers.','课程总计 22 周，包含系统的幼儿心理与启蒙教育理论课、教案设计工坊以及 500+ 小时持牌托儿所全真实战实习。','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(526,'eca_faq_a3','general','An ECA (Early Childcare Assistant) works directly alongside Registered Early Childhood Educators (RECEs) in daycare rooms, assisting with daily routines, learning activities, nutrition, and child supervision. ECA is a fast-track 22-week diploma that allows you to start working in the childcare field quickly.','ECA 是协助主班 ECE 开展日常教学、幼儿生活照料与安全看护的专业人员。ECA 课程周期短（22周），学费更低，能帮助您以最快速度进入安省幼教行业并获得稳定收入，未来还可继续进修成为 RECE。','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(527,'eca_faq_a4','general','Yes! This program is fully eligible for <strong>Better Jobs Ontario (Second Career)</strong>, offering up to <strong>$28,000+</strong> in non-repayable government grants covering 100% of your tuition, learning materials, transportation, and living expenses for qualified applicants.','完全可以！本课程符合安省 <strong>Better Jobs Ontario</strong> 政府资助计划，合资格者最高可获 <strong>$28,000+</strong> 无偿政府全额补贴，无需偿还，学院专家免费协助全程申请。','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(528,'eca_faq_q1','general','Can I study the theory portion of the ECA program online from home?','幼教 ECA 课程可以在家线上学习理论吗？','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(529,'eca_faq_q2','general','How long is the Early Childcare Assistant program?','ECA 幼教助理课程需要学习多久？','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(530,'eca_faq_q3','general','What is the difference between an ECA and an ECE in Ontario?','在安省 ECA（幼教助理）和 ECE（注册幼教）有什么区别？','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(531,'eca_faq_q4','general','Are there government grants available for this program?','我可以申请政府学费资助吗？','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(532,'eca_faq_title','general','Frequently Asked Questions','幼教专业常见问题解答','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(533,'eca_form_desc','general','Reserve your spot or request grant evaluation. An advisor will contact you within 24 hours.','锁定最新开班名额或申请政府学费评估，专业顾问将在 24 小时内与您联系。','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(534,'eca_form_email_lbl','general','Email Address *','电子邮箱 *','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(535,'eca_form_email_ph','general','name@example.com','例如：name@example.com','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(536,'eca_form_grant_check','general','Evaluate for Better Jobs Ontario Grant','评估 Better Jobs Ontario 政府补助金资格','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(537,'eca_form_name_lbl','general','Your Full Name *','您的姓名 *','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(538,'eca_form_name_ph','general','e.g. David Zhang / Sarah Miller','例如：王小明 / 张丽','2026-09-25T20:50:06.150592');
