INSERT INTO "site_translations" VALUES(542,'eca_form_success','general','<strong>Thank You!</strong> Your request has been submitted. Our admissions advisor will reach out shortly.','<strong>感谢您的咨询！</strong> 表单已成功提交，我们的招生顾问将尽快与您取得联系。','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(543,'eca_form_title','general','Apply / Book Consultation','立即申请 / 预约专业咨询','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(544,'eca_hero_badge','general','Ontario Approved Career Diploma • 22-Week Intensive Daycare Placement','安省注册幼教职业文凭 • 22 周持牌日托中心保障实习','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(545,'eca_hero_cta_curriculum','general','View Curriculum Modules','查看 10 门教学大纲','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(546,'eca_hero_cta_grant','general','Book Free Grant Assessment','免费评估政府 $28,000+ 助学金','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(547,'eca_hero_lead','general','Help shape the next generation with Ontario-approved early childhood training. Master child development, health & safety, creative curriculum planning, and gain 500+ hours of guaranteed hands-on field placement in licensed daycares and preschools across the GTA.','投身安省极度紧缺的早期幼儿教育行业。系统学习婴幼儿及学龄前儿童心理发展、健康营养、安全防护与启蒙教案设计，保障进入安省持牌正规幼儿园/日托中心进行 500+ 小时实地带薪/跟岗实习。','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(548,'eca_hero_title','general','Launch Your Rewarding Career as a Certified Early Childcare Assistant (ECA)','开启充满爱心与高薪稳定的职业生涯 • 早期幼儿教育助理 (ECA) 职业文凭','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(549,'eca_m1','general','<strong>Introduction to Early Childhood Education:</strong> Canadian early learning history, CCEYA 2014 regulatory framework, daycare licensing, and professional ethical standards.','<strong>加拿大幼儿教育概论与法规：</strong>早期教育发展历史、安省 CCEYA 2014 日托法规、机构执照要求与职业道德规范。','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(550,'eca_m10','general','<strong>Supervised Field Practicum (500+ Hours):</strong> Hands-on clinical placement in accredited Ontario daycares under experienced RECE mentorship across infant, toddler, and preschool rooms.','<strong>安省持牌日托中心 500+ 小时实习：</strong>在持牌托儿所婴儿班、幼童班和学前班进行全真实操演练，由资深 RECE 导师现场带教。','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(551,'eca_m2','general','<strong>Child Growth & Development (Infancy to Toddler):</strong> Physical, cognitive, emotional milestones (0–30 months), infant brain architecture, and attachment bonds.','<strong>儿童生长与心理（婴儿至幼童）：</strong>0–18个月婴儿与18–30个月幼童的生理、认知、情感与社交发育里程碑及大脑发育理论。','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(552,'eca_m3','general','<strong>Child Growth & Development (Preschool to School-Age):</strong> Developmental milestones (2.5–12 years), language acquisition, fine/gross motor skills, and social dynamics.','<strong>儿童生长与心理（学前期至学龄期）：</strong>2.5–5岁学前儿童与6–12岁学龄儿童的心理特征、语言获得、精细运动与同伴交往。','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(553,'eca_m4','general','<strong>Health, Safety & Nutrition in Childcare:</strong> Sanitary guidelines, infection control, injury prevention, anaphylaxis & food allergies, balanced meals, and emergency protocols.','<strong>日托健康、安全与营养管理：</strong>卫生消毒与传染病防控、安全隐患排查、严重过敏反应管理、营养膳食与儿科急救。','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(554,'eca_m5','general','<strong>Creative Expressions & Sensory Play:</strong> Designing engaging art, music rhythm, storytelling, sensory exploration, and early literacy activities.','<strong>幼儿创意启蒙与感统游戏：</strong>设计激发幼儿想象力与创造力的艺术手工、音乐节奏律动、绘本精读与多感官探索游戏。','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(555,'eca_m6','general','<strong>Positive Behavior Guidance Strategies:</strong> Nurturing emotional self-regulation, conflict resolution, calm classroom routines, and constructive behavioral guidance.','<strong>儿童行为积极引导与班级常规：</strong>儿童心理积极引导策略、情绪自控能力培养、冲突化解技巧与温馨班级日常作息建立。','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(556,'eca_m7','general','<strong>Interpersonal Communications:</strong> Building partnerships with diverse Canadian families, daily parent reports, collaboration with RECEs, and Ministry inspections.','<strong>家园共育与多文化团队协作：</strong>与多元文化背景家庭建立信任伙伴关系、日常家长交接沟通、与主班幼教（RECE）协作。','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(557,'eca_m8','general','<strong>Program Planning & Documentation:</strong> Implementing ''How Does Learning Happen?'', designing play-based learning spaces, pedagogical documentation, and student portfolios.','<strong>启蒙教案编制与儿童观察记录：</strong>践行安省 ''How Does Learning Happen?'' 指南，设计以玩促学环境，记录儿童成长档案。','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(558,'eca_m9','general','<strong>Supporting Diverse Needs & Inclusion:</strong> Inclusive early childhood practices, neurodiversity support, autism strategies, sensory accommodations, and special education collaboration.','<strong>特殊需求儿童关怀与融合教育：</strong>全包容性幼教理念、神经多样性与自闭症儿童支持、感统失调应对及与特教顾问配合。','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(559,'eca_page_title','general','Early Childcare Assistant Course (ECA) • Daycare Diploma | Victoria International College','早期幼儿教育助理 (ECA) 幼教文凭课程 • 保障持牌日托中心实习 | 维多利亚职业学院','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(560,'eca_prac_box_desc','general','Over <strong>85%</strong> of Victoria College ECA graduates receive permanent job offers directly from their placement host center before graduation!','超过 <strong>85%</strong> 的维多利亚学院 ECA 毕业生在实习期间直接获得实习机构全职录用合同（Job Offer）！','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(561,'eca_prac_box_title','general','Direct Daycare Hiring & Job Offer Success Rate','实习基地直接留用签约率高','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(562,'eca_prac_desc','general','Victoria College coordinates 100% of your hands-on field practicum across accredited daycare centers, Montessori schools, and early learning centers in Toronto, Markham, Richmond Hill, Scarborough, and Mississauga.','维多利亚学院负责全流程对口安排大多伦多地区（Markham、Toronto、Richmond Hill、Scarborough、Mississauga 等）持牌日托中心及蒙特梭利学校的实习岗位，由资深注册幼教（RECE）导师一对一手把手带教。','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(563,'eca_prac_title','general','Guaranteed 500+ Hours Field Placement in Licensed Ontario Daycares','保障 500+ 小时安省持牌日托中心实地跟岗实习','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(564,'eca_side_c_lbl','general','Credential:','文凭认证：','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(565,'eca_side_c_val','general','Early Childcare Assistant Diploma','安省官方 ECA 幼教文凭','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(566,'eca_side_d_lbl','general','Duration:','学制时长：','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(567,'eca_side_d_val','general','22 Weeks','22 周','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(568,'eca_side_del_lbl','general','Delivery:','授课模式：','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(569,'eca_side_del_val','general','Live Online + Daycare Practicum','名师直播网课 + 托儿所实习','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(570,'eca_side_grant_badge','general','GOVERNMENT GRANTS','政府全额资助','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(571,'eca_side_grant_btn','general','Check Eligibility Now','立即测试申请资格','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(572,'eca_side_grant_desc','general','Study Early Childcare Assistant with zero out-of-pocket tuition. Book a 100% free eligibility assessment with our funding specialists today.','零学费负担就读幼教助理黄金专业。立即预约专家一对一免费评估您的资助申请资格。','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(573,'eca_side_grant_title','general','Get Up to $28,000+ Grant','最高可获 $28,000+ 补助金','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(574,'eca_side_hot_lbl','general','Hotline:','咨询热线：','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(575,'eca_side_loc_lbl','general','Locations:','校区地点：','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(576,'eca_side_loc_val','general','Markham Main Campus / GTA Daycares','万锦主校区 / GTA 日托中心','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(577,'eca_side_p_lbl','general','Practicum:','实操实习：','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(578,'eca_side_p_val','general','500+ Hours Guaranteed','500+ 小时持牌托儿所保障','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(579,'eca_side_snap_title','general','Program Snapshot','专业概览速查','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(580,'eca_stat_1_lbl','general','Comprehensive Theory + 500+ Hours Daycare Placement','网课理论/校区实操 + 500+小时持牌幼儿园实地实习','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(581,'eca_stat_1_val','general','22 Weeks','22 周','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(582,'eca_stat_2_lbl','general','Rewarding Career Growth + Ontario Wage Enhancement (WEG)','大多伦多托儿幼教稳定高需求 + 安省政府薪资补贴 (WEG)','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(583,'eca_stat_2_val','general','High Demand','极具潜力','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(584,'eca_stat_3_lbl','general','Guaranteed Practicum in Accredited Daycare Centers','对口签约安省正规持牌日托中心与早教机构','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(585,'eca_stat_3_val','general','100% Daycare Placement','100% 保障实习','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(586,'eca_stat_4_lbl','general','Eligible for Full Better Jobs Ontario Government Funding','符合 Better Jobs Ontario 政府全额无偿资助','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(587,'eca_stat_4_val','general','Up to $28,000+','最高 $28,000+','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(588,'eca_why_1_desc','general','With thousands of new subsidized childcare spaces opening across Ontario, certified Early Childcare Assistants enjoy extraordinary job security, permanent employment, and signing bonuses.','安省日托补贴政策全面落地，新增数万个入托名额，持证幼教助理常年供不应求，毕业即对口就业。','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(589,'eca_why_1_title','general','Historic Industry Demand','历史性行业缺口与高就业率','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(590,'eca_why_2_desc','general','Make a lasting, positive impact on young children''s cognitive, emotional, and social development during their most critical formative years.','在儿童大脑发育黄金期给予关爱与科学启蒙，陪伴孩子们健康快乐成长，深受家长信赖与社会尊重。','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(591,'eca_why_2_title','general','Rewarding & Meaningful Work','充满爱心与成就感的工作','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(592,'eca_why_3_desc','general','Work in modern, licensed childcare facilities, early learning centers, and school boards alongside dedicated teams of Registered Early Childhood Educators (RECEs).','在安省持牌正规托儿所、幼儿园及公校课后班工作，与注册幼教老师（RECE）团队协作，工作时间规律，带薪假期充裕。','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(593,'eca_why_3_title','general','Safe & Collaborative Work Environment','安全、正规与舒适的工作环境','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(594,'eca_why_4_desc','general','Gain vital Canadian frontline experience and open doors to accelerated RECE diploma pathways, daycare supervisory roles, or private home childcare business ownership.','快速积累加国本土一线幼教经验，未来可无缝衔接安省注册幼教（RECE）进阶文凭、日托主管或创办家庭日托。','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(595,'eca_why_4_title','general','Clear Career Progression','通往 RECE 幼教名师的快捷跳板','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(596,'eca_why_subtitle','general','Early childhood education in Ontario is undergoing historic expansion driven by the federal $10-a-day Canada-Wide Early Learning and Child Care (CWELCC) plan. Daycare centers, preschools, and kindergarten programs across the Greater Toronto Area face severe shortages of certified, compassionate educators and assistants.','随着加拿大联邦及安省政府全面推行 $10/天普惠日托计划（CWELCC），全省各类托儿所、幼儿园和早教中心迎来历史性大扩建，持证幼教助理（ECA）与幼教老师长期极度紧缺，成为加国最抢手、最温暖且极具社会价值的黄金职业之一。','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(597,'eca_why_title','general','Why Choose Early Childcare Assistant (ECA) as Your Canadian Career?','为什么选择成为早期幼儿教育助理 (ECA)？','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(598,'elec_adm_1','general','Ontario Secondary School Diploma (OSSD / Grade 12) or Canadian / International equivalent evaluation.','具备安大略省高中毕业文凭（OSSD / 12年级）或加国及海外同等学历评估认证。','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(599,'elec_adm_2','general','Mature Student Admission: 18 years of age or older with passing score on the Wonderlic entrance assessment.','成熟学生通道：年满 18 周岁，并通过学院基础能力测评（校区/线上免费测评）。','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(600,'elec_adm_3','general','Trade Qualifier candidates: Domestic or international electrical trade experience eligible for Skilled Trades Ontario exam challenge.','Trade Qualifier 经验挑战通道：具备海内外电气、自动化、机械、机电相关工程经验，希望快速免学徒直接考牌的人士。','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(601,'elec_adm_4','general','Registered Apprentices: Currently registered with Ministry of Labour, Immigration, Training and Skills Development (MLITSD).','现职学徒及电工助手：已在安省技术移民及技能发展厅（MLITSD）注册学徒或从事 Helper 工作的技工。','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(602,'elec_adm_5','general','Basic mathematical proficiency (algebra and trigonometry fundamentals) and strong safety awareness.','具备基础数学逻辑（初等代数与几何）以及严谨的安全防护意识。','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(603,'elec_adm_title','general','Admission Requirements & Prerequisites','入学报读条件与适合人群','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(604,'elec_cred_1_desc','general','Official verification of completion in Canadian Electrical Code theory and Certificate of Qualification examination prep.','维多利亚学院官方颁发的加拿大电气规范理论与 Red Seal 考前冲刺培训结业证书。','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(605,'elec_cred_1_title','general','Ontario 309A / 442A Exam Readiness Certificate','安省 309A / 442A 考证通关结业证书','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(606,'elec_cred_2_desc','general','Demonstrates advanced mastery in Ontario Electrical Safety Code (OESC) interpretation, ampacity tables, and conductor sizing.','深度掌握安省电气安全局（OESC）各项安全法规、导线载流量校核、短路保护与变压器选型。','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(607,'elec_cred_2_title','general','Canadian Electrical Code (CEC) Specialist Credential','加拿大电气规范 (CEC) 规范应用专家认证','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(608,'elec_cred_3_desc','general','Comprehensive training in CSA Z462 electrical safety standards, high-voltage isolation, hazard boundaries, and PPE protocols.','全面掌握 CSA Z462 工作场所电气安全操作规程、高压隔离排空、防护绝缘装备（PPE）与急救规范。','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(609,'elec_cred_3_title','general','Lockout/Tagout (LOTO) & Arc Flash Safety Record','电气安全、LOTO 挂牌上锁与电弧防护证书','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(610,'elec_cred_4_desc','general','Practical portfolio showcasing single-line diagrams, commercial branch load schedules, 3-phase balancing, and motor control circuits.','独立完成商业单线配电系统图（Single-Line Diagram）、三相平衡负荷表、照明动力回路及电机控制原理图编制。','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(611,'elec_cred_4_title','general','Commercial Blueprint & Schematic Sizing Portfolio','商业电气施工图纸识图与负荷计算作品集','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(612,'elec_cred_sub','general','Upon completion of training and practical assessments, students achieve recognized milestones toward their journeyperson license:','顺利完成全部理论培训与实操考核后，学员将获得加国电气行业高度认可的实战能力与考证资质：','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(613,'elec_cred_title','general','Credentials, Certifications & Exam Readiness','官方培训资质、技能成果与考证直通','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(614,'elec_curr_desc','general','A rigorous, code-focused curriculum preparing students for both field mastery and the Skilled Trades Ontario (STO) Red Seal licensing exam:','紧扣 Skilled Trades Ontario 考纲要求与加国一线工地施工标准精心设计，理论考点与动手实操并重：','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(615,'elec_curr_title','general','Comprehensive 10-Module Curriculum Outline','官方 10 门专业系统核心课程模块','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(616,'elec_faq_a1','general','309A Construction and Maintenance Electrician is Ontario''s most versatile license, permitting work in residential, commercial, institutional, and industrial settings. 442A Industrial Electrician focuses specifically on factory automation, manufacturing plant machinery, motor controls, PLCs, and industrial electrical maintenance.','309A 建筑与维护电工（Construction & Maintenance Electrician）是加国适用范围最广的电工执照，可在民用住宅、商业大楼、公共设施及工业厂房等所有领域合法执业；442A 工业电工（Industrial Electrician）则专注在工厂制造企业、自动化生产线、机械设备电气维护与 PLC 控制系统。','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(617,'elec_faq_a2','general','Yes! Through Skilled Trades Ontario''s Trade Equivalency Assessment (Trade Qualifier pathway), individuals with verified work experience (typically 9,000+ hours for 309A) can apply to challenge the Certificate of Qualification exam directly without repeating a 5-year apprenticeship.','可以！通过安省技术工种局（Skilled Trades Ontario）的 Trade Equivalency Assessment（Trade Qualifier）海外经验评估，只要证明累积了相应工时（309A 通常为 9,000 小时，442A 通常为 8,100 小时），即可获批直接参加执照考试，无需从头重新做 5 年学徒。维多利亚学院提供全程经验认证指导。','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(618,'elec_faq_a3','general','Yes! We offer flexible weekend and evening cohort schedules specifically designed for working adults, trades helpers, and apprentices to study code theory online and attend hands-on labs on weekends.','有！我们专门开设了周末及晚间班，所有理论与规范精讲均支持在线直播与高清录播无限次回放，实操集中在周末进行，让您在不影响全职工作的同时高效备考。','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(619,'elec_faq_a4','general','Yes! Victoria College''s programs are eligible for Better Jobs Ontario (up to $28,000+ non-repayable grant covering tuition, books, tools, and living costs) as well as federal Apprenticeship Incentive Grants and Canada Apprentice Loans for registered apprentices.','可以！本课程符合安省 Better Jobs Ontario 政府资助计划，合资格者最高可获 $28,000+ 无需偿还的政府全额补贴，100% 报销学费、工具教材及生活津贴，学院专家免费协助全程申请。','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(620,'elec_faq_a5','general','Yes! In addition to in-depth Canadian Electrical Code theory and exam question drills, students train in our dedicated electrical lab with residential panels, 3-phase disconnects, transformers, motor control boards, and conduit bending equipment.','包含！除了深度的 CEC 电气规范精讲与红宝书全真题库模考，学员还将在官方认可实训基地亲自动手进行 100A/200A 配电盘、三相配电、变压器接线、电机磁力启动器与管道弯管实操演练。','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(621,'elec_faq_a6','general','We provide 1-on-1 resume optimization for the Canadian trade market, guidance on joining IBEW union locals or CLAC, and direct networking referrals to licensed electrical contractor partners across the GTA.','是的！学院提供加国技工英文简历一对一修改、IBEW 国际电工工会申请指导，并向大多伦多地区长期合作的大中型持牌电气工程公司直接内推。','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(622,'elec_faq_q1','general','What is the difference between 309A Construction & Maintenance and 442A Industrial Electrician?','309A 建筑维护电工和 442A 工业电工有什么区别？','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(623,'elec_faq_q2','general','Can I challenge the 309A / 442A exam if I have international or non-registered electrical experience?','我有海外电气工作经验，可以直接在安省挑战考电工牌照吗？','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(624,'elec_faq_q3','general','Can I attend classes while working full-time?','平时需要全职上班，有适合业余时间学习的班型吗？','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(625,'elec_faq_q4','general','Are there government grants or financial aid available for this program?','我可以申请政府全额学费资助吗？','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(626,'elec_faq_q5','general','Does the course include hands-on practical wiring training?','课程包含动手实操接线训练吗？','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(627,'elec_faq_q6','general','How does Victoria College support graduates with finding jobs or joining the union?','毕业后学校会协助推荐工作或加入工会吗？','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(628,'elec_faq_title','general','Frequently Asked Questions','常见问题解答 (FAQ)','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(629,'elec_form_desc','general','Reserve your spot or request trade qualifier evaluation. An advisor will contact you within 24 hours.','预约名师 1对1 免费评估加国考电工牌照资质及海外经验资格，锁定最新开班名额。','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(630,'elec_form_email_lbl','general','Email Address *','电子邮箱 *','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(631,'elec_form_email_ph','general','name@example.com','例如：name@example.com','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(632,'elec_form_grant_check','general','I am interested in applying for Government Grants ($28,000+)','我想了解并申请政府最高 $28,000+ 免费学费补助','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(633,'elec_form_name_lbl','general','Your Full Name *','您的姓名 *','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(634,'elec_form_name_ph','general','e.g. Jason Chen / Michael Smith','例如：陈建国 / 李强','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(635,'elec_form_phone_lbl','general','Phone Number *','联系电话 *','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(636,'elec_form_phone_ph','general','416-665-6668','例如：416-665-6668','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(637,'elec_form_submit','general','Submit Consultation Request','提交咨询与预约','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(638,'elec_form_success','general','<strong>Thank You!</strong> Your request has been submitted. Our trade education advisor will reach out shortly.','<strong>感谢您的咨询！</strong> 表单已成功提交，我们的持牌电工课程规划顾问将尽快与您取得联系。','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(639,'elec_form_title','general','Apply / Book Free Consultation','立即申请 / 预约免费电工评估','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(640,'elec_hero_badge','general','Ontario Skilled Trades • 309A / 442A Pre-Exam & Licensing','安省持牌技工高薪黄金专业 • 309A / 442A 考证与实操','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(641,'elec_hero_cta_book','general','Book Free Trade Consultation','立即免费预约电工评估','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(642,'elec_hero_cta_curriculum','general','Explore 10-Module Curriculum','查看 10 门专业教学大纲','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(643,'elec_hero_lead','general','Coached by veteran Master Electricians with 20+ years of Canadian union, commercial, and industrial contracting experience. Master the Canadian Electrical Code (CEC / OESC), hands-on residential & 3-phase commercial wiring, motor controls, blueprint reading, and trade exam test banks to pass your Certificate of Qualification (C of Q) on your first attempt.','由安省 20 余年一线西人大型工程公司项目主管、资深持牌 Master Electrician 名师亲自授课。将加国最新电气规范（CEC / OESC）核心考点精讲、官方认可学徒实训基地 1对1 动手实操接线（民用配电箱/三相电/变压器/电机控制/管道弯管）与红宝书全真题库模考融为一体，助您一次性高分通关拿牌并对口就业！','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(644,'elec_hero_stat_1_lbl','general','Red Seal Licensed Journeyperson','安省红印执照金牌技工 • 工会优厚待遇','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(645,'elec_hero_stat_1_sub','general','Union Scale & Comprehensive Pension','红印执照 / 工会优厚待遇与丰厚养老金','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(646,'elec_hero_stat_1_val','general','Top Earning','高薪典范','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(647,'elec_hero_stat_2_lbl','general','Master Electrician Taught','大师级持牌电工亲授','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(648,'elec_hero_stat_2_sub','general','Senior Project Leads from Top Firms','加国一线大型西人工程公司资深项目主管','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(649,'elec_hero_stat_2_val','general','20+ Yrs Mentorship','20+ 年名师带教','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(650,'elec_hero_stat_3_lbl','general','Apprenticeship Facility','官方认可学徒实训基地','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(651,'elec_hero_stat_3_sub','general','Panels, 3-Phase, Motors & Transformers','配电箱、三相电、变压器与电机控制','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(652,'elec_hero_stat_3_val','general','1-on-1 Hands-on Labs','1对1 动手实操机房','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(653,'elec_hero_stat_4_lbl','general','Government Funding Eligible','符合政府全额无偿资助','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(654,'elec_hero_stat_4_sub','general','Better Jobs Ontario & Apprentice Grants','Better Jobs Ontario 及学徒专项津贴','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(655,'elec_hero_stat_4_val','general','Up to $28,000+ Grant','$28,000+ 政府补贴','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(656,'elec_hero_title','general','Master the Canadian Electrical Code & Fast-Track Your 309A / 442A License','精通加拿大电气规范 (CEC) • 快速通关安省 309A 建筑与 442A 工业电工牌照','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(657,'elec_lab_box_desc','general','Over 90% of our exam preparation graduates successfully pass their Red Seal / C of Q exam and gain rapid referrals to top GTA electrical contractors and union locals!','维多利亚学院电工班学员考试通过率名列前茅，超过 90% 的积极学员在考取牌照后迅速获得知名西人/华人电气工程公司聘用或成功加入 IBEW 电工工会！','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(658,'elec_lab_box_title','general','Direct Contractor Networking & Trade Qualifier Guidance','大多伦多工程团队对口直推与工会内荐','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(659,'elec_lab_desc','general','Victoria International College provides students with direct access to dedicated electrical training workstations. Students gain practical, muscle-memory experience wiring real electrical equipment under the supervision of practicing Master Electricians.','维多利亚职业学院配备标准电气实训工位，学员在资深持牌 Master Electrician 导师的指导下，直接动手操作真实配电箱、工业变压器、电机控制柜与弯管设备，迅速将规范转化为肌肉记忆实战能力。','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(660,'elec_lab_title','general','Hands-on Electrical Lab & Training Facility','官方认可电工实训基地与 1对1 动手实操','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(661,'elec_m10_d','general','Timed full-length mock exams modeled on the Skilled Trades Ontario exam blueprint. Detailed breakdown of tricky questions, formula shortcuts, and time-management techniques.','严格按照 Skilled Trades Ontario 统考模式进行限时全真模考，深度拆解高频陷阱题、公式速记技巧与应试时间分配，确保一次性高分通关！','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(662,'elec_m10_h','general','30 Hours','30 学时','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(663,'elec_m10_t','general','Red Seal 309A / 442A C of Q Mock Exam Simulation & Question Bank','安省 309A / 442A 执照考试全真模考冲刺与红宝书题库精讲','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(664,'elec_m1_d','general','Code layout, Section 0–16 general rules, conductor ampacity (Tables 1–4), temperature ratings, derating factors (Table 5C), conduit fill (Tables 6A–K), and exam lookup strategies.','Code Book 篇章逻辑、Section 0–16 通用规则、导线载流量表（Tables 1–4）、温度与降容系数（Table 5C）、管内穿线率表（Tables 6A–K）及快速定位考点策略。','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(665,'elec_m1_h','general','30 Hours','30 学时','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(666,'elec_m1_t','general','Canadian Electrical Code (CEC / OESC) Structure & Fast Navigation','加拿大电气规范 (CEC / OESC) 架构解析与极速查表秘籍','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(667,'elec_m2_d','general','Occupational Health & Safety Act (OHSA), CSA Z462 electrical workplace safety, shock boundaries, arc flash PPE categories, ground fault protection, and bonding rules (Section 10).','安省职业健康与安全法案（OHSA）、CSA Z462 电气作业安全、触电危险边界、电弧防护级别、接地（Grounding）与接零保护（Bonding - Section 10）。','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(668,'elec_m2_h','general','20 Hours','20 学时','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(669,'elec_m2_t','general','Electrical Safety, PPE, Lockout/Tagout (LOTO) & Arc Flash Protection','电气安全施工规范、PPE、LOTO 挂牌上锁与电弧防范 (Arc Flash)','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(670,'elec_m3_d','general','Ohm''s law, Kirchhoff''s laws, series/parallel combinations, inductance, capacitance, single-phase and 3-phase AC power calculations, power factor correction, and apparent vs active power.','欧姆定律、基尔霍夫定律、串并联回路、感抗与容抗、单相与三相交流功率计算（视在功率、有功功率、无功功率）、功率因数补偿与相序分析。','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(671,'elec_m3_h','general','30 Hours','30 学时','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(672,'elec_m3_t','general','DC/AC Electrical Theory, Magnetism & Power Calculations','直流/交流电理论、电磁学原理与三相电功率计算','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(673,'elec_m4_d','general','Residential load calculations (Section 8), service entrance sizing, main breaker panels, branch circuit design, AFCI/GFCI protection, kitchen/bathroom code rules, and multi-wire circuits.','住宅总负荷计算（Section 8）、进线配电箱配置、断路器选用、分支回路分配、AFCI 电弧断路器与 GFCI 漏电保护器接线、厨卫电气规范及多线分支回路。','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(674,'elec_m4_h','general','35 Hours','35 学时','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(675,'elec_m4_t','general','Residential Wiring Systems & 100A/200A Service Panels','民用住宅电气布线系统与 100A/200A 主配电箱实战','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(676,'elec_m5_d','general','Commercial 120/208V and 347/600V distribution systems, delta and wye connections, neutral conductor sizing, commercial panelboards, disconnect switches, and energy-efficient lighting controls.','商业 120/208V 与 347/600V 配电系统、星形（Wye）与角形（Delta）接法、中性线计算、商业配电盘安装、隔离开关（Disconnect Switches）与智能照明控制系统。','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(677,'elec_m5_h','general','35 Hours','35 学时','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(678,'elec_m5_t','general','3-Phase Power Distribution & Commercial Wiring','三相工业商业配电系统与配电柜接线 (Commercial 3-Phase)','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(679,'elec_m6_d','general','Single-phase and 3-phase transformers (Section 26), step-up and step-down applications, delta-wye connections, autotransformers, turns ratio, primary/secondary overcurrent protection sizing.','单相与三相电力变压器（Section 26）、升压/降压变压器、自耦变压器、变比计算、一次侧/二次侧过电流保护器与熔断器精准整定计算。','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(680,'elec_m6_h','general','30 Hours','30 学时','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(681,'elec_m6_t','general','Transformers: Installation, Connections & Sizing Calculations','变压器原理、接线方式、过流保护与容量选型计算','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(682,'elec_m7_d','general','Single-phase and 3-phase AC induction motors (Section 28), stop/start latching circuits, forward/reversing starters, overload protection sizing, time-delay relays, and ladder schematics.','单相与三相交流感应电动机（Section 28）、启停自锁控制回路、正反转磁力启动器、热过载继电器整定、时间继电器与梯形逻辑控制图识图。','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(683,'elec_m7_h','general','35 Hours','35 学时','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(684,'elec_m7_t','general','Electric Motors, Magnetic Starters & Motor Control Circuits','交流电动机、磁力启动器、控制继电器与电路原理图 (Motor Controls)','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(685,'elec_m8_d','general','Hands-on EMT and rigid conduit bending (90-degree stubs, back-to-back, kicks, 3-point/4-point saddles), mechanical raceways, cable trays (Section 12), and wire pulling practices.','EMT 金属管与刚性管手工/机械弯管（90度弯头、背对背弯、偏置弯 Kick、三点/四点鞍形弯）、电缆桥架安装（Section 12）与工业穿线拉线实操。','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(686,'elec_m8_h','general','30 Hours','30 学时','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(687,'elec_m8_t','general','Conduit Bending, Raceways, Cable Trays & Installation Methods','管道弯管工艺 (Conduit Bending)、电缆桥架与穿线技巧','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(688,'elec_m9_d','general','Architectural and engineering drawing symbols, electrical site plans, single-line power diagrams, panel schedules, lighting layouts, material takeoffs, and project cost estimating.','建筑电气施工图图例符号、配电平面图、系统单线图（Single-Line Diagram）、动力箱负荷明细表、工程材料量核算（Takeoff）与施工报价。','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(689,'elec_m9_h','general','25 Hours','25 学时','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(690,'elec_m9_t','general','Electrical Blueprint Reading, Schematics & Specification Sizing','电气施工图纸识图、图例符号、材料估算与负荷计算书编制','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(691,'elec_page_title','general','Electrician (309A / 442A) Pre-Exam & Hands-on Labs | Victoria International College','安省 309A / 442A 建筑与工业电工考证培训班 | 维多利亚职业学院','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(692,'elec_side_c_lbl','general','Credential:','毕业证书：','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(693,'elec_side_c_val','general','Pre-Exam Training Certificate + Red Seal Prep','考前冲刺培训证书 + 红印备考认证','2026-09-25T20:50:06.150592');
