INSERT INTO "site_translations" VALUES(695,'elec_side_d_val','general','Fast-Track & Weekend Cohorts','考证冲刺班 / 实用周末班（灵活随到随学）','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(696,'elec_side_del_lbl','general','Delivery:','授课模式：','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(697,'elec_side_del_val','general','Hybrid (Online Code + Hands-on Lab)','混成教学（线上规范精讲 + 校区动手实操）','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(698,'elec_side_grant_badge','general','GOVERNMENT GRANTS','安省政府培训资助','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(699,'elec_side_grant_btn','general','Check Eligibility Now','立即免费评估资格','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(700,'elec_side_grant_desc','general','Study Electrician with zero out-of-pocket tuition. Eligible candidates can qualify for up to $28,000+ through Better Jobs Ontario covering tuition, tools, and living allowance.','符合条件的安省居民最高可申请 $28,000+ 加币政府全额无偿培训补助（Better Jobs Ontario），100% 覆盖学费、工具费、教材费及学习期间基本生活费。','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(701,'elec_side_grant_title','general','Get Up to $28,000+ Grant','申请最高 $28,000+ 政府助学金','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(702,'elec_side_hot_lbl','general','Hotline:','咨询热线：','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(703,'elec_side_loc_lbl','general','Locations:','校区地点：','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(704,'elec_side_loc_val','general','Markham Main Campus / Live Online','万锦主校区 / 在线名师直播','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(705,'elec_side_snap_title','general','Program Snapshot','专业概览速查','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(706,'elec_why_1_desc','general','Licensed journeypersons in the GTA command top-tier trade compensation with extensive overtime opportunities, comprehensive union pension plans, full health benefits, and strong career security.','大多伦多持牌电工享有行业顶尖的丰厚薪酬与发展前景，享高额加班津贴、工会丰厚养老金、全家医疗牙医保险及带薪年假。','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(707,'elec_why_1_title','general','Top-Tier Earning Potential & Stability','行业顶薪与极佳稳定性','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(708,'elec_why_2_desc','general','Systematic breakdown of the Canadian Electrical Code (CEC / OESC). Master rapid table navigation, load sizing formulas, and key question patterns to pass the C of Q exam with confidence.','全面系统拆解加拿大电气规范（Canadian Electrical Code / OESC），掌握极速查表技巧、负荷计算公式与高频必考题眼，确保一次性高分考取牌照。','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(709,'elec_why_2_title','general','100% CEC Code Mastery & Exam Fast-Track','100% 攻克加国电气规范 (CEC)','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(710,'elec_why_3_desc','general','Train in our recognized apprenticeship lab: residential 100A/200A distribution panels, commercial 3-phase 600V systems, transformer connections, magnetic motor starters, and conduit bending.','在官方认可学徒基地动手实操：民用 100A/200A 配电盘、商业三相 600V 强电系统、变压器接线、交流接触器与磁力电机启动柜、管道弯管（Conduit Bending）。','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(711,'elec_why_3_title','general','1-on-1 Hands-on Wiring & Distribution Labs','1对1 动手实操与接线实战','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(712,'elec_why_4_desc','general','Expert guidance for experienced tradespeople challenging the exam via the Trade Qualifier pathway, plus direct employer introductions and union dispatch referral networks across the GTA.','协助具备海内外工程经验的学员通过 Trade Qualifier 快速通道申请免学徒直接挑战考证，并向大多伦多知名西人/华人工程公司及工会定向推荐就业。','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(713,'elec_why_4_title','general','Trade Qualifier Support & Job Referrals','海外经验资格评估与对口内推','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(714,'elec_why_sub','general','Electrical trades represent one of Canada''s most respected, lucrative, and recession-proof professions. As Ontario experiences massive infrastructure growth, electric vehicle transitions, and residential expansions, licensed 309A and 442A electricians command premium wages, comprehensive benefits, and strong union representation.','电工是加拿大收入最高、最受社会尊重且极具抗周期性的金牌技工职业之一。随着安省大型基础设施建设、新能源电动汽车充电桩及住宅商业地产的蓬勃发展，持牌 309A 建筑电工与 442A 工业电工常年极度紧缺，薪酬福利优厚，工会保障完善。','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(715,'elec_why_title','general','Why Choose a Career as a Licensed Electrician in Ontario?','为什么选择成为安省持牌电工 (Licensed Electrician)？','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(716,'tech_adm_1','general','Ontario Secondary School Diploma (OSSD / Grade 12) or Canadian / International equivalent credential evaluation.','具备安大略省高中毕业文凭（OSSD / 12年级）或加国及海外同等学历评估认证。','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(717,'tech_adm_2','general','Mature Student Admission: 18 years of age or older with a passing score on the college entrance assessment.','成熟学生通道：年满 18 周岁，并通过学院入学基础能力测评（校区/线上免费测评）。','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(718,'tech_adm_3','general','Basic computer literacy and logical problem-solving aptitude (no prior coding experience strictly required; introductory bootcamp modules included).','零基础转行人员：理工科毕业生、文商科转行 IT 人士（课程包含保姆级编程入门引导模块）。','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(719,'tech_adm_4','general','Career changers, engineering/science graduates, and existing IT professionals looking to upskill with modern AI and Full-Stack technologies.','在职技术提升人员：已有传统开发经验，希望迅速掌握 React、Next.js、AWS 云计算与 Generative AI 大模型落地的 IT 从业者。','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(720,'tech_adm_5','general','English language proficiency suitable for technical communication and documentation.','具备基本的计算机操作习惯与逻辑思维能力，具有较强的学习意愿。','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(721,'tech_adm_title','general','Admission Requirements & Prerequisites','入学报读条件与适合人群','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(722,'tech_cred_1_desc','general','Registered vocational diploma verifying mastery of modern full stack software engineering and database systems.','安省教育部注册职业学院颁发的正规职业大专文凭，权威验证全栈软件开发与数据库工程专业能力。','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(723,'tech_cred_1_title','general','Full Stack Web Technician Career Diploma','Full Stack Web Technician 职业大专文凭','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(724,'tech_cred_2_desc','general','Specialized micro-credential certifying hands-on proficiency in LLM API integration, prompt engineering, and RAG systems.','专项认证微证书，证明学员具备大模型 API 集成、RAG 企业知识库构建及 AI 智能应用开发实操能力。','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(725,'tech_cred_2_title','general','Generative AI Engineering Mini-Credential','生成式 AI 智能工程微证书 (AI Mini-Credential)','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(726,'tech_cred_3_desc','general','Proof of competence in containerization, cloud infrastructure provisioning, serverless functions, and CI/CD pipelines.','证明掌握 Docker 容器化、AWS 云服务配置、自动化构建测试与无服务器计算架构运维能力。','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(727,'tech_cred_3_title','general','AWS Cloud & DevOps Practitioner Badge','AWS 云原生与 DevOps 实践认证徽章','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(728,'tech_cred_4_desc','general','A live, fully deployed full-stack SaaS application with authentication, payments, database persistence, and AI features on GitHub.','在 GitHub 上交付具备完整用户鉴权、支付结算、数据库持久化及 AI 智能问答特性的线上真实运营级 SaaS 平台。','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(729,'tech_cred_4_title','general','Production-Grade Capstone SaaS Portfolio','工业级商业 Capstone SaaS 项目作品集','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(730,'tech_cred_sub','general','Graduates earn recognized career credentials and build an employer-ready GitHub portfolio:','毕业学员将获得安省官方认可的职业大专文凭及极具就业竞争力的项目作品集：','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(731,'tech_cred_title','general','Diplomas, Micro-Credentials & Portfolio Milestones','职业文凭、微证书与实战项目里程碑','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(732,'tech_curr_desc','general','A structured, hands-on 32-week software engineering curriculum designed to take you from foundational programming to enterprise-ready AI full-stack developer:','紧扣北美一线科技大厂与金融机构用人标准的循序渐进实战大纲，助零基础与进阶学员系统蜕变为企业级 AI 全栈工程师：','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(733,'tech_curr_title','general','Comprehensive 10-Module Curriculum Outline','32 周 10 大核心课程模块大纲','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(734,'tech_faq_a1','general','No prior coding background is required! Our program is carefully designed to take beginners from programming fundamentals to enterprise-level full-stack and AI engineering through structured labs, step-by-step guidance, and mentor code reviews.','完全可以！我们的课程体系经过 20 余年持续迭代，从零基础编程底层逻辑（变量、循环、数据结构）讲起，循序渐进过渡到微服务与 AI 大模型应用。课程配备助教答疑、代码逐行审查与丰富随堂练习，确保零基础学员扎实吸收。','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(735,'tech_faq_a2','general','The AI Mini-Credential is a cutting-edge curriculum track covering Generative AI integration, LLM APIs (OpenAI GPT-4, Claude), prompt engineering, Retrieval-Augmented Generation (RAG), and vector databases. You''ll build smart web applications capable of semantic search, automated summarization, AI chat, and workflow automation.','AI 微证书涵盖当前最前沿的生成式 AI 实战技术：OpenAI / Claude API 调用、Prompt 提示词工程进阶、LangChain 框架、RAG 企业私有知识库检索增强与向量数据库应用。学员将亲手打造具备语义搜索、智能问答与自动化工作流的 AI 智能 Web 应用。','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(736,'tech_faq_a3','general','You will gain hands-on mastery in HTML5, CSS3, Tailwind CSS, JavaScript (ES6+), TypeScript, React 19, Next.js, Node.js, Express, Java, Spring Boot, PostgreSQL, MongoDB, Redis, Docker, AWS (EC2/S3/RDS/Lambda), Git/GitHub, and OpenAI/LangChain.','涵盖当前北美招聘市场需求最大的全家桶：HTML5、CSS3、Tailwind CSS、JavaScript (ES6+)、TypeScript、React 19、Next.js、Node.js、Express、Java、Spring Boot 3、PostgreSQL、MySQL、MongoDB、Redis、Docker、AWS 云服务及 Git/GitHub。','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(737,'tech_faq_a4','general','Yes! Victoria International College is a registered career college under the Ontario Career Colleges Act, 2005. Eligible individuals (unemployed, laid-off, gig workers, or underemployed) can qualify for up to $28,000+ in non-repayable Better Jobs Ontario funding covering 100% of tuition, tech equipment, and living costs.','可以！维多利亚学院为安省正规注册职业学院，本专业完全符合 Better Jobs Ontario 政府资助计划。失业、被裁员、领过 EI、自雇或低收入人士最高可获 $28,000+ 无需偿还的政府全额资助（包括学费、电脑费与生活费），学院专家免费一对一协助申请。','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(738,'tech_faq_a5','general','We provide comprehensive tech career services: 1-on-1 resume optimization, GitHub portfolio polishing, technical mock interviews (data structures, algorithms, system design), LeetCode interview preparation, and direct job referrals to our GTA employer hiring network.','学院提供全方位的 IT 就业辅导体系：一对一简历深度技术包装、GitHub 代码库规范打磨、LeetCode 高频算法真题精讲、系统设计与全真大厂模拟技术面试，并向大多伦多本地合作雇主库直接内推。','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(739,'tech_faq_a6','general','We offer flexible formats including full-time weekday cohorts and part-time evening/weekend tracks. All live sessions are recorded in HD for 24/7 review, combined with collaborative online lab workstations and on-campus mentor access.','我们提供全日制脱产班及业余晚间/周末班等多种灵活班型。所有线上直播课程均支持高清录播无限次回放，并配套全天候线上协作机房与校区导师面授答疑。','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(740,'tech_faq_q1','general','Do I need a Computer Science degree or prior coding experience to enroll?','零基础或者没有计算机背景可以学会吗？','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(741,'tech_faq_q2','general','What is the AI Mini-Credential included in this program?','课程中的 AI 微证书（AI Mini-Credential）包含哪些核心内容？','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(742,'tech_faq_q3','general','What technologies and frameworks will I master?','课程会教授哪些主流开发语言和框架？','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(743,'tech_faq_q4','general','Is this program eligible for government grants like Better Jobs Ontario?','我可以申请政府全额学费资助吗？','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(744,'tech_faq_q5','general','How does Victoria College support students with job placement?','毕业后学校如何辅导就业？','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(745,'tech_faq_q6','general','What is the class schedule and format?','上课时间如何安排？有录播可以复习吗？','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(746,'tech_faq_title','general','Frequently Asked Questions','常见问题解答 (FAQ)','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(747,'tech_form_desc','general','Reserve your spot or request grant evaluation. An advisor will contact you within 24 hours.','预约名师 1对1 免费评估 IT 转行规划、助学金申请资格及锁定最新开班名额。','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(748,'tech_form_email_lbl','general','Email Address *','电子邮箱 *','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(749,'tech_form_email_ph','general','name@example.com','例如：name@example.com','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(750,'tech_form_grant_check','general','I am interested in applying for Government Grants ($28,000+)','我想了解并申请政府最高 $28,000+ 免费学费补助','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(751,'tech_form_name_lbl','general','Your Full Name *','您的姓名 *','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(752,'tech_form_name_ph','general','e.g. Alex Zhang / David Miller','例如：张伟 / 李敏','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(753,'tech_form_phone_lbl','general','Phone Number *','联系电话 *','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(754,'tech_form_phone_ph','general','416-665-6668','例如：416-665-6668','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(755,'tech_form_submit','general','Submit Consultation Request','提交咨询与预约','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(756,'tech_form_success','general','<strong>Thank You!</strong> Your request has been submitted. Our tech admissions advisor will reach out shortly.','<strong>感谢您的咨询！</strong> 表单已成功提交，我们的 IT 课程规划顾问将尽快与您取得联系。','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(757,'tech_form_title','general','Apply / Book Free Tech Consultation','立即申请 / 预约免费 IT 职业规划','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(758,'tech_hero_badge','general','Career Diploma • AI Mini-Credential • 32-Week Intensive','加国紧缺高薪 IT 职业文凭 • 含 AI 微证书 • 32周实战冲刺','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(759,'tech_hero_cta_book','general','Book Free Tech Career Consultation','预约免费名师 IT 规划咨询','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(760,'tech_hero_cta_curriculum','general','Explore 10-Module Curriculum','查看 10 大核心模块大纲','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(761,'tech_hero_lead','general','Coached by senior tech leads from top Canadian financial institutions and tech enterprises. Master modern frontend architecture (React 19 / Next.js / TypeScript), robust backend microservices (Node.js / Python / Spring Boot), cloud DevOps (AWS / Docker), and cutting-edge Generative AI engineering (OpenAI API, LangChain, RAG, Vector DBs). Build production-ready portfolio projects and land high-paying software engineering careers.','由加拿大顶级银行与科技名企资深架构师亲授。从底层编程基础到现代前端工程（React 19 / Next.js / TypeScript）、企业级后端微服务（Node.js / Python / Java Spring Boot）、AWS 云原生运维（Docker / CI/CD），并深度融入前沿生成式 AI 大模型开发（OpenAI API, LangChain, RAG 检索增强, 向量数据库）。手把手带领学员打造高含金量商业项目作品集，直通北美高薪软件工程师就业岗位。','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(762,'tech_hero_stat_1_lbl','general','High-Growth Tech Career & AI Integration','北美高科技紧缺开发岗位与前沿 AI 实战','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(763,'tech_hero_stat_1_sub','general','Enterprise Web & Cloud Solutions','企业级微服务与全栈云原生开发','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(764,'tech_hero_stat_1_val','general','高薪赛道','高薪赛道','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(765,'tech_hero_stat_2_lbl','general','Real-World Commercial Portfolio','商业级真实项目作品集','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(766,'tech_hero_stat_2_sub','general','SaaS, AI Integrations & GitHub Repos','企业级 SaaS、AI 集成与 GitHub 真实代码仓库','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(767,'tech_hero_stat_2_val','general','100% Project Labs','100% 实战机房','2026-09-25T20:50:06.150592');
