INSERT INTO "site_translations" VALUES(774,'tech_hero_title','general','Master Full-Stack Web Development & Enterprise Generative AI Integration','全栈软件工程开发与 AI 微证书大专文凭班','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(775,'tech_lab_box_desc','general','Over 90% of our active tech graduates secure full-stack, frontend, backend, or QA engineering roles within 3 to 6 months of graduation, working across Toronto''s thriving fintech, healthcare tech, and software sectors!','维多利亚学院 IT 毕业生在加国各大银行（RBC, TD, BMO, CIBC, Scotiabank）、金融科技、医疗健康与知名科技公司广泛任职，毕业 3–6 个月内积极就业率超 90%！','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(776,'tech_lab_box_title','general','Direct Tech Employer Introductions & Alumni Referral Network','大多伦多地区科技名企对口内推与校友合作网络','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(777,'tech_lab_desc','general','Victoria International College provides high-performance computing environments and live cloud sandbox accounts. Students collaborate in agile Scrum teams to deliver enterprise software solutions with clean code, testing, and CI/CD automation.','学员按敏捷敏捷开发团队（Scrum Team）编制，在加国名企资深架构师带领下，全程使用 Jira、GitHub 进行企业级规范的代码提交、Code Review、CI/CD 部署与自动化测试，亲手打造可写进简历的高含金量真实商业作品集。','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(778,'tech_lab_title','general','Enterprise Coding Lab & Capstone Project','企业级全真实训机房与商业 Capstone 毕业大项目','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(779,'tech_m10_d','general','Build and deploy an enterprise-grade AI-powered SaaS application; comprehensive system design reviews (scalability, microservices, load balancing), LeetCode coding interview drills, and mock tech screens.','团队敏捷协作交付具备 AI 智能特性的工业级全栈云平台；系统架构设计（高并发、分布式、负载均衡）、LeetCode 经典大厂算法真题精讲与一对一模拟面试。','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(780,'tech_m10_h','general','40 Hours','40 学时','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(781,'tech_m10_t','general','Enterprise Capstone Project, System Design & Tech Interview Mastery','毕业大项目 Capstone：工业级 AI 赋能 SaaS 云平台与名企面试冲刺','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(782,'tech_m1_d','general','Core algorithms, data structures (arrays, linked lists, hash maps, trees), Big-O complexity, Object-Oriented Programming (OOP) principles, clean code design, and Git version control workflows.','核心算法、常用数据结构（数组、链表、哈希表、二叉树）、时间与空间复杂度（Big-O）、面向对象设计原则（SOLID）、代码整洁之道与 Git 版本控制规范。','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(783,'tech_m1_h','general','35 Hours','35 学时','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(784,'tech_m1_t','general','Computer Science Fundamentals, OOP & Core Programming Architecture','计算机底层核心、面向对象编程 (OOP) 与算法数据结构','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(785,'tech_m2_d','general','Semantic HTML, Flexbox, CSS Grid, Tailwind CSS, DOM manipulation, ES6+ features (closures, promises, async/await, modules), event-driven programming, and client-side debugging.','语义化 HTML5、Flexbox、CSS Grid、Tailwind CSS、DOM 树操作、ES6+ 核心特性（闭包、原型链、Promise、async/await、模块化）、事件驱动模型与浏览器调试技巧。','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(786,'tech_m2_h','general','35 Hours','35 学时','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(787,'tech_m2_t','general','Modern Frontend Core: HTML5, CSS3, Responsive Design & Modern JavaScript (ES6+)','现代前端基础：HTML5、CSS3 响应式布局与 JavaScript (ES6+) 进阶','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(788,'tech_m3_d','general','TypeScript static typing, interfaces, generics; React 19 functional components, custom hooks, context API, state management with Redux Toolkit/Zustand, and performance optimization.','TypeScript 静态类型系统、接口与泛型；React 19 函数式组件、Custom Hooks 自定义钩子、Context API、Redux Toolkit / Zustand 状态管理与前端性能极致调优。','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(789,'tech_m3_h','general','40 Hours','40 学时','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(790,'tech_m3_t','general','Enterprise Frontend Engineering: TypeScript & React 19 Architecture','企业级前端工程：TypeScript 与 React 19 核心架构','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(791,'tech_m4_d','general','Next.js App Router, React Server Components (RSC), Server-Side Rendering (SSR), Static Site Generation (SSG), dynamic routing, API route handlers, and middleware security.','Next.js App Router 架构、服务端组件与客户端组件交互、服务端渲染 (SSR)、静态生成 (SSG)、动态路由传参、API Route Handlers 与安全中间件。','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(792,'tech_m4_h','general','35 Hours','35 学时','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(793,'tech_m4_t','general','Next.js Full-Stack Architecture: Server Components, SSR & App Router','Next.js 全栈架构：服务端组件 (RSC)、SSR 与 App Router 路由','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(794,'tech_m5_d','general','Asynchronous event-loop architecture, Express.js middleware, RESTful API design standards, JWT / OAuth2 authentication, rate limiting, error handling, and unit testing with Jest.','Node.js 异步非阻塞事件循环机制、Express 中间件架构、RESTful API 行业标准设计、JWT / OAuth2 鉴权与安全防护、限流降级及 Jest 单元测试。','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(795,'tech_m5_h','general','35 Hours','35 学时','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(796,'tech_m5_t','general','Backend Engineering: Node.js, Express & RESTful Microservices','现代后端工程：Node.js、Express 框架与 RESTful 微服务','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(797,'tech_m6_d','general','Core & Advanced Java, JVM internals, Spring Boot 3, Dependency Injection, Spring MVC, Spring Security, MyBatis / Hibernate ORM, and enterprise service architecture.','Java 核心进阶、JVM 运行机制、Spring Boot 3 自动装配、依赖注入 (IoC/DI)、Spring MVC 控制层、Spring Security 权限控制与 MyBatis / Hibernate 数据库持久层。','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(798,'tech_m6_h','general','35 Hours','35 学时','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(799,'tech_m6_t','general','Enterprise Java & Spring Boot Microservices Ecosystem','企业级 Java 后端微服务生态：Spring Boot 3 与 MyBatis','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(800,'tech_m7_d','general','PostgreSQL and MySQL schema design, complex JOINs, indexing & query optimization, MongoDB document modeling, Prisma ORM, and Redis distributed caching.','PostgreSQL 与 MySQL 数据库表设计、复杂 JOIN 查询、索引优化与执行计划分析、MongoDB 文档建模、Prisma ORM 以及 Redis 分布式缓存与消息队列实战。','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(801,'tech_m7_h','general','35 Hours','35 学时','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(802,'tech_m7_t','general','Database Engineering: Relational SQL, NoSQL & High-Performance Caching','数据库架构与优化：SQL 关系型、NoSQL 与 Redis 高性能缓存','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(803,'tech_m8_d','general','OpenAI / Anthropic Claude API integration, prompt engineering techniques, LangChain / LlamaIndex workflows, Retrieval-Augmented Generation (RAG), embeddings, and Pinecone/ChromaDB vector search.','OpenAI / Claude API 深度集成、Prompt 提示词工程进阶、LangChain / LlamaIndex 编排、RAG 检索增强企业知识库、Embeddings 向量嵌入与 Pinecone/ChromaDB 向量搜索。','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(804,'tech_m8_h','general','40 Hours','40 学时','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(805,'tech_m8_t','general','Generative AI Engineering: LLMs, OpenAI API, LangChain & Vector Databases','AI 智能工程微证书：LLM 大模型、OpenAI API、LangChain 与向量数据库','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(806,'tech_m9_d','general','Containerizing multi-service apps with Docker & Docker Compose, AWS cloud services (EC2, S3, RDS, Lambda), Vercel deployment, GitHub Actions automated CI/CD pipelines, and environment secrets.','多服务 Dockerfile 与 Docker Compose 容器编排、AWS 核心云服务（EC2, S3, RDS, Lambda）、Vercel 云端部署、GitHub Actions 自动化构建与环境变量安全配置。','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(807,'tech_m9_h','general','30 Hours','30 学时','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(808,'tech_m9_t','general','Cloud Infrastructure, Docker Containers & DevOps CI/CD Pipelines','云原生基础设施：Docker 容器化、AWS 云部署与 CI/CD 自动化流水线','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(809,'tech_page_title','general','Full Stack Web Development with AI Mini-Credential | Victoria International College','全栈软件开发与 AI 微证书大专文凭班 | 维多利亚职业学院','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(810,'tech_side_c_lbl','general','Credential:','毕业证书：','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(811,'tech_side_c_val','general','Full Stack Web Technician Diploma + AI Mini-Credential','Full Stack Web Technician 职业文凭 + AI 微证书','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(812,'tech_side_d_lbl','general','Duration:','课程周期：','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(813,'tech_side_d_val','general','32 Weeks (Labs + Capstone)','32 周（高强度实操机房 + 毕业商业大项目）','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(814,'tech_side_del_lbl','general','Delivery:','授课模式：','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(815,'tech_side_del_val','general','Live Online + In-Person Campus Labs','混成教学（线上高清直播 + 校区实操机房）','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(816,'tech_side_grant_badge','general','GOVERNMENT GRANTS','安省政府培训资助','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(817,'tech_side_grant_btn','general','Check Eligibility Now','立即免费评估资助资格','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(818,'tech_side_grant_desc','general','Study Full Stack Web with AI with zero out-of-pocket tuition. Eligible candidates can qualify for up to $28,000+ through Better Jobs Ontario covering tuition, tech allowance, and living support.','符合条件的安省居民最高可申请 $28,000+ 加币政府全额无偿培训补助（Better Jobs Ontario），100% 覆盖学费、电脑设备费、书本教材费及学习期间基本生活津贴。','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(819,'tech_side_grant_title','general','Get Up to $28,000+ Grant','申请最高 $28,000+ 政府全额助学金','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(820,'tech_side_hot_lbl','general','Hotline:','咨询热线：','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(821,'tech_side_loc_lbl','general','Locations:','校区地点：','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(822,'tech_side_loc_val','general','Markham Main Campus / Live Online','万锦主校区 / 在线名师直播','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(823,'tech_side_snap_title','general','Program Snapshot','专业概览速查','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(824,'tech_why_1_desc','general','Master end-to-end full stack development: React 19, Next.js App Router, TypeScript, Node.js, Python, Spring Boot, PostgreSQL, MongoDB, and Redis caching.','系统掌握全栈开发主流技术：React 19、Next.js App Router、TypeScript、Node.js、Python、Spring Boot 3、PostgreSQL、MongoDB 与 Redis 高性能缓存。','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(825,'tech_why_1_title','general','Modern Enterprise Full-Stack Architecture','企业级现代全栈工程技术栈','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(826,'tech_why_2_desc','general','Stand out from traditional coders. Build intelligent applications with OpenAI/Claude APIs, LangChain, Retrieval-Augmented Generation (RAG), and vector databases.','打破传统码农局限。深入掌握 OpenAI / Claude API 调用、Prompt 提示词工程、LangChain 框架、RAG 知识库检索增强与向量数据库实战。','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(827,'tech_why_2_title','general','Integrated Generative AI & LLM Engineering','深度融入生成式 AI 与 LLM 大模型开发','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(828,'tech_why_3_desc','general','Gain hands-on experience containerizing apps with Docker, deploying to AWS (EC2, S3, RDS, Lambda), and setting up automated CI/CD pipelines via GitHub Actions.','实战 Docker 容器化打包、AWS 云端基础设施（EC2, S3, RDS, Lambda）配置，以及基于 GitHub Actions 的自动化 CI/CD 持续集成部署流程。','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(829,'tech_why_3_title','general','Cloud Native DevOps & Production Deployment','云原生 DevOps 与生产环境自动化部署','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(830,'tech_why_4_desc','general','Get tailored resume packaging, GitHub code review, LeetCode algorithmic drills, system design practice, and direct introductions to hiring tech partners across the GTA.','名师提供简历技术深度包装、GitHub 代码库规范打磨、LeetCode 高频算法精讲、系统架构设计（System Design）与大多伦多本地科技雇主直推。','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(831,'tech_why_4_title','general','1-on-1 Tech Interview Coaching & Job Referrals','一对一技术面试辅导与名企内推','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(832,'tech_why_sub','general','Software development continues to be one of Canada''s most in-demand, resilient, and highest-paying career paths. With the explosive rise of Generative AI, developers who understand how to build robust full-stack web applications and integrate AI capabilities command top market compensation.','软件开发始终是加拿大就业市场需求最旺盛、抗周期能力最强、薪资天花板最高的黄金职业之一。随着生成式 AI 与大模型技术的爆发，具备扎实全栈工程开发能力并精通 AI 集成落地的复合型开发者在招聘市场备受追捧。','2026-09-25T20:50:06.150592');
INSERT INTO "site_translations" VALUES(833,'tech_why_title','general','Why Choose Full Stack Web Development with AI Mini-Credential?','为什么选择全栈软件开发与 AI 微证书课程？','2026-09-25T20:50:06.150592');
